std::string dbms::sqlstateForDBStatus(DBStatus res) {
    switch (res) {
        case DBStatus::OK: return "00000";
        case DBStatus::TABLE_NOT_FOUND: return "42P01";
        case DBStatus::DATABASE_NOT_FOUND: return "3D000";
        case DBStatus::TABLE_ALREADY_EXISTS: return "42P07";
        case DBStatus::INVALID_VALUE: return "22023";
        case DBStatus::INVALID_ARGUMENT: return "22023";
        case DBStatus::NULL_NOT_ALLOWED: return "23502";
        case DBStatus::SYNTAX_ERROR: return "42601";
        case DBStatus::DUPLICATE_KEY: return "23505";
        case DBStatus::LOCK_CONFLICT: return "55P03";
        case DBStatus::SERIALIZATION_FAILURE: return "40001";
        case DBStatus::IO_ERROR: return "58030";
        case DBStatus::CORRUPTED_DATA: return "XX001";
        default: return "XX000";
    }
}

namespace {

using SqlRow = dbms::StorageEngine::SqlRow;

SqlRow sqlRowFromLegacy(
    const std::map<std::string, std::string>& values) {
    SqlRow result;
    for (const auto& [column, value] : values) {
        if (value == "NULL") result[column] = std::nullopt;
        else result[column] = value;
    }
    return result;
}

std::map<std::string, std::string> legacyRowFromSql(
    const SqlRow& values) {
    std::map<std::string, std::string> result;
    for (const auto& [column, value] : values) {
        result[column] = value ? *value : "NULL";
    }
    return result;
}

void splitSqlRow(const SqlRow& source,
                 std::map<std::string, std::string>& values,
                 std::set<std::string>& nullColumns) {
    values.clear();
    nullColumns.clear();
    for (const auto& [column, value] : source) {
        values[column] = value.value_or(std::string{});
        if (!value) nullColumns.insert(column);
    }
}

SqlRow joinSqlRow(const std::map<std::string, std::string>& values,
                  const std::set<std::string>& nullColumns) {
    SqlRow result;
    for (const auto& [column, value] : values) {
        if (nullColumns.count(column) != 0) result[column] = std::nullopt;
        else result[column] = value;
    }
    return result;
}

}  // namespace

static std::string escapeString(const std::string& s) {
    std::string r;
    for (char c : s) {
        if (c == ' ') r += "\\s";
        else if (c == '\n') r += "\\n";
        else if (c == '\\') r += "\\\\";
        else r += c;
    }
    return r;
}

static std::string unescapeString(const std::string& s) {
    std::string r;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            if (s[i + 1] == 's') { r += ' '; ++i; }
            else if (s[i + 1] == 'n') { r += '\n'; ++i; }
            else if (s[i + 1] == '\\') { r += '\\'; ++i; }
            else r += s[i];
        } else {
            r += s[i];
        }
    }
    return r;
}

// Session temporary relations are deliberately kept out of the user-visible
// namespace.  The numeric backend component makes this predicate unambiguous
// and lets startup remove both catalog entries and orphaned relation forks
// left behind by a crashed backend.
static bool isSessionTempPhysicalName(const std::string& name) {
    constexpr const char* prefix = "__tmp_";
    constexpr size_t prefixLen = 6;
    if (name.rfind(prefix, 0) != 0) return false;

    const size_t separator = name.find('_', prefixLen);
    if (separator == prefixLen || separator == std::string::npos ||
        separator + 1 >= name.size()) {
        return false;
    }
    for (size_t i = prefixLen; i < separator; ++i) {
        if (name[i] < '0' || name[i] > '9') return false;
    }
    return true;
}

// Physical backups contain a complete database layout but are not active
// databases. Mark them explicitly so startup recovery never replays their
// WAL or follows their stale external-tablespace paths.
static constexpr const char* kPhysicalBackupMarker = ".dbms_physical_backup";

