// ========================================================================
// Row-Level Security helpers
// ========================================================================
static std::string toLowerUtf8(const std::string& s);

static bool shouldEnforceRLS(const TableSchema& tbl, const std::string& user) {
    if (!tbl.rowLevelSecurity) return false;
    if (tbl.forceRowLevelSecurity || user.empty()) return true;

    // RLS bypass is a role attribute, not a username convention. Unknown
    // identities fail closed; authenticated superusers and BYPASSRLS roles
    // bypass ordinary RLS, while FORCE ROW LEVEL SECURITY still applies it.
    const auto account = authCatalog().getAuthIdByName(user);
    if (!account) return true;

    // PostgreSQL table owners bypass ordinary RLS. FORCE ROW LEVEL SECURITY
    // is handled above and deliberately applies policies to the owner too.
    // Require an existing role before comparing names; an arbitrary or
    // unauthenticated identity must never become an owner bypass.
    if (!tbl.owner.empty() && tbl.owner == account->rolname) return false;

    return !(account->rolsuper || account->rolbypassrls);
}

static bool evaluateRlsPolicies(
    const std::vector<StorageEngine::RowPolicy>& policies,
    bool withCheck,
    const std::map<std::string, std::string>& values,
    const std::map<std::string, std::string>& typeHints,
    const std::string& dbname,
    const std::string& user,
    bool& evaluationError) {
    bool hasPermissive = false;
    bool permissivePassed = false;

    for (const auto& policy : policies) {
        std::string expression = withCheck ? policy.withCheckExpr : policy.usingExpr;
        // PostgreSQL uses USING as the default WITH CHECK expression for
        // ALL and UPDATE policies when WITH CHECK is omitted.
        if (withCheck && expression.empty()) {
            const std::string command = toLowerUtf8(policy.cmd);
            if (command == "all" || command == "update") {
                expression = policy.usingExpr;
            }
        }

        bool passed = true;
        if (!expression.empty()) {
            std::string error;
            passed = ExprHelper::evalBool(expression, values, typeHints, &error,
                                          dbname, user);
            if (!error.empty()) {
                evaluationError = true;
                return false;
            }
        }

        if (policy.permissive) {
            hasPermissive = true;
            permissivePassed = permissivePassed || passed;
        } else if (!passed) {
            // Every applicable restrictive policy must accept the row.
            return false;
        }
    }

    // A set containing only restrictive policies is still default-deny: a
    // permissive policy must establish the positive access set first.
    return hasPermissive && permissivePassed;
}

static bool rowPassesRLS(const StorageEngine* engine,
                         const std::string& dbname,
                         const std::string& tablename,
                         const TableSchema& tbl,
                         const std::string& command,
                         const std::map<std::string, std::string>& values,
                         const std::map<std::string, std::string>& typeHints,
                         bool withCheck) {
    if (!engine) return false;
    const std::string user = StorageEngine::getRLSUser();
    if (!shouldEnforceRLS(tbl, user)) return true;
    const auto policies = engine->getApplicablePolicies(dbname, tablename, command, user);
    if (policies.empty()) return false;

    bool evaluationError = false;
    return evaluateRlsPolicies(policies, withCheck, values, typeHints,
                               dbname, user, evaluationError) &&
           !evaluationError;
}

// ========================================================================
// Unicode string helpers
// ========================================================================
static std::string toUpperUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towupper(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

static std::string toLowerUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towlower(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

bool StorageEngine::ReadView::isVisible(uint64_t rowTxnId) const {
    if (rowTxnId == 0) return true;              // non-transactional rows always visible
    if (rowTxnId == creatorTxnId) return true;   // inserted by current transaction
    // Prepared transactions are retained in the active xid set across a
    // process restart. Check that set before age-based snapshot shortcuts:
    // a prepared xid may be numerically older than this snapshot's xmin but
    // must remain invisible until COMMIT PREPARED.
    if (activeTxnIds.count(rowTxnId)) return false;
    if (subTxnIds.count(rowTxnId)) return false;
    if (rowTxnId >= lowLimitId) return false;    // all newer xids not started

    // Snapshot xmin only proves that an older xid is no longer active; it
    // does not prove that it committed. Consult CLOG for every non-current
    // xid below xmax so an old aborted INSERT cannot become visible merely
    // because newer transactions advanced the snapshot horizon.
    if (commitLog) {
        auto status = commitLog->getStatus(static_cast<TxnId>(rowTxnId));
        if (status == CommitLog::Status::Committed) return true;
        // ABORTED, SUB_COMMITTED, and an unflushed IN_PROGRESS status are all
        // non-visible. Never infer a commit from a missing/unfinished CLOG
        // entry: doing so leaks uncommitted rows across snapshots.
        return false;
    }

    // Legacy callers without a CLOG retain the snapshot-only fallback.
    return true;
}

// Visibility using the current PostgreSQL-style HeapTupleHeader.
bool StorageEngine::ReadView::isVisible(const char* rowBuffer, size_t len, uint32_t formatVersion) const {
    if (len == 0) return false;
    if (!usesHeapTupleHeader(formatVersion)) return false;

    if (len < sizeof(HeapTupleHeaderData)) return false;
    const auto* htup = castHeapHeader(rowBuffer);

    uint64_t xmin = htup->t_fields.t_xmin;
    uint64_t xmax = htup->t_fields.t_xmax;

    // Use hint bits when available
    bool xminComm = xminCommitted(htup);
    bool xminInv = xminInvalid(htup);
    bool xmaxComm = xmaxCommitted(htup);
    bool xmaxInv = xmaxInvalid(htup);

    // --- xmin visibility ---
    bool xminVisible = false;
    if (xmin == 0) {
        xminVisible = true;
    } else if (xminInv) {
        xminVisible = false;
    } else if (xmin == creatorTxnId) {
        xminVisible = true;
    } else if (activeTxnIds.count(xmin)) {
        xminVisible = false; // transaction is still in progress
    } else if (subTxnIds.count(xmin)) {
        xminVisible = false; // subtransaction in progress
    } else if (xmin >= lowLimitId) {
        xminVisible = false;
    } else if (commitLog) {
        // CLOG is authoritative when it is available.  PITR can deliberately
        // change a transaction that committed on the source timeline into an
        // aborted transaction on the restored timeline, while heap pages may
        // still carry the old committed hint bit.
        auto s = commitLog->getStatus(static_cast<TxnId>(xmin));
        xminVisible = (s == CommitLog::Status::Committed);
    } else if (xminComm) {
        // Legacy callers without a CLOG may still use the tuple hint.
        xminVisible = true;
    } else {
        xminVisible = true; // fallback
    }

    if (!xminVisible) return false;

    // --- xmax (deletion/lock) visibility ---
    if (xmax == 0 || xmaxInv) return true; // not deleted
    if (xmaxIsLock(htup)) return true;     // xmax is only a lock, not deletion

    bool xmaxVisible = false; // true means row is still visible (delete not committed)
    if (xmax == creatorTxnId) {
        xmaxVisible = false; // current tx deleted it
    } else if (activeTxnIds.count(xmax) || subTxnIds.count(xmax)) {
        xmaxVisible = true; // prepared/in-progress delete is not committed
    } else if (xmax >= lowLimitId) {
        xmaxVisible = true;
    } else if (commitLog) {
        // As with xmin, a restored timeline's CLOG overrides stale source-
        // timeline commit hints left in the heap tuple.
        auto s = commitLog->getStatus(static_cast<TxnId>(xmax));
        xmaxVisible = (s != CommitLog::Status::Committed);
    } else if (xmaxComm) {
        // The delete committed and was no longer active at snapshot time.
        xmaxVisible = false;
    } else {
        xmaxVisible = true;
    }

    return xmaxVisible;
}

static std::string trim(const std::string& s) {
    size_t a = 0;
    while (a < s.size() && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
    size_t b = s.size();
    while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
    return s.substr(a, b - a);
}

static bool parseFloatLiteral(const std::string& input, float& value) {
    const std::string token = trim(input);
    if (token.empty()) return false;
    try {
        size_t consumed = 0;
        value = std::stof(token, &consumed);
        return consumed == token.size();
    } catch (...) {
        return false;
    }
}

static bool parseDoubleLiteral(const std::string& input, double& value) {
    const std::string token = trim(input);
    if (token.empty()) return false;
    try {
        size_t consumed = 0;
        value = std::stod(token, &consumed);
        return consumed == token.size();
    } catch (...) {
        return false;
    }
}

static bool parseFiniteDouble(const std::string& input, double& value) {
    return parseDoubleLiteral(input, value) && std::isfinite(value);
}

template <typename Floating>
static std::string formatFloatingValue(Floating value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return std::signbit(value) ? "-Infinity" : "Infinity";

    char buffer[64];
    const auto converted = std::to_chars(
        buffer, buffer + sizeof(buffer), value, std::chars_format::general);
    if (converted.ec == std::errc())
        return std::string(buffer, converted.ptr);

    // libstdc++ implementations with incomplete floating-point to_chars
    // support still get a lossless fallback.
    std::ostringstream out;
    out << std::setprecision(std::numeric_limits<Floating>::max_digits10)
        << value;
    return out.str();
}

static std::string formatPointCoordinate(double value) {
    return formatFloatingValue(value);
}

static std::string canonicalColumnKeyValue(const Column& column,
                                           const std::string& value) {
    if (value.empty()) return {};
    if (column.dataType == "float") {
        float parsed = 0.0f;
        if (!parseFloatLiteral(value, parsed)) return value;
        // IEEE -0 and +0 compare equal even though their display forms and
        // bit patterns differ. Index/constraint keys must therefore merge.
        return parsed == 0.0f ? "0" : formatFloatingValue(parsed);
    }
    if (column.dataType == "double" || column.dataType == "decimal") {
        double parsed = 0.0;
        if (!parseDoubleLiteral(value, parsed)) return value;
        return parsed == 0.0 ? "0" : formatFloatingValue(parsed);
    }
    return value;
}

template <typename Floating>
static int compareFloatingValues(Floating left, Floating right) {
    const bool leftNaN = std::isnan(left);
    const bool rightNaN = std::isnan(right);
    if (leftNaN) return rightNaN ? 0 : 1;
    if (rightNaN) return -1;
    return left < right ? -1 : (right < left ? 1 : 0);
}

static bool floatingPredicateMatches(const std::string& op, int comparison) {
    if (op == "=") return comparison == 0;
    if (op == "!=" || op == "<>") return comparison != 0;
    if (op == "<") return comparison < 0;
    if (op == ">") return comparison > 0;
    if (op == "<=") return comparison <= 0;
    if (op == ">=") return comparison >= 0;
    return false;
}

static bool normalizePointLiteral(const std::string& input, std::string& output,
                                  double* parsedX = nullptr,
                                  double* parsedY = nullptr) {
    std::string value = trim(input);
    if (value.size() >= 2 && value.front() == '\'' && value.back() == '\'')
        value = trim(value.substr(1, value.size() - 2));

    if (value.size() >= 5) {
        std::string prefix = value.substr(0, 5);
        for (char& ch : prefix)
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        if (prefix == "point" &&
            (value.size() == 5 || value[5] == '(' ||
             std::isspace(static_cast<unsigned char>(value[5])))) {
            value = trim(value.substr(5));
            if (value.size() < 2 || value.front() != '(' || value.back() != ')')
                return false;
        }
    }
    if ((!value.empty() && value.front() == '(') ||
        (!value.empty() && value.back() == ')')) {
        if (value.size() < 2 || value.front() != '(' || value.back() != ')')
            return false;
        value = trim(value.substr(1, value.size() - 2));
    }

    const size_t comma = value.find(',');
    if (comma == std::string::npos || value.find(',', comma + 1) != std::string::npos)
        return false;
    double x = 0.0;
    double y = 0.0;
    if (!parseFiniteDouble(value.substr(0, comma), x) ||
        !parseFiniteDouble(value.substr(comma + 1), y)) {
        return false;
    }
    output = formatPointCoordinate(x) + "," + formatPointCoordinate(y);
    if (parsedX) *parsedX = x;
    if (parsedY) *parsedY = y;
    return true;
}

static bool normalizePointColumns(const TableSchema& table,
                                  std::map<std::string, std::string>& values,
                                  const std::set<std::string>* nullColumns = nullptr) {
    for (size_t i = 0; i < table.len; ++i) {
        const Column& column = table.cols[i];
        if (column.dataType != "point") continue;
        auto value = values.find(column.dataName);
        const bool isNull = value != values.end() &&
            (nullColumns ? nullColumns->count(column.dataName) != 0
                         : value->second == "NULL");
        if (value == values.end() || value->second.empty() || isNull)
            continue;
        std::string canonical;
        if (!normalizePointLiteral(value->second, canonical)) return false;
        value->second = std::move(canonical);
    }
    return true;
}

static bool variableColumnWidthsValid(
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::set<std::string>* nullColumns = nullptr) {
    for (size_t i = 0; i < table.len; ++i) {
        const Column& column = table.cols[i];
        if (!column.isVariableLength) continue;
        const auto value = values.find(column.dataName);
        const bool isNull = value != values.end() &&
            (nullColumns ? nullColumns->count(column.dataName) != 0
                         : value->second == "NULL");
        if (value == values.end() || isNull) continue;
        const size_t maxLength = column.isArray ? 1024 : column.dsize;
        if (value->second.size() > maxLength) return false;
    }
    return true;
}

static bool columnAcceptsEmptyValue(const Column& column) {
    if (column.isArray) return false;
    if (!column.enumValues.empty()) {
        return std::find(column.enumValues.begin(), column.enumValues.end(),
                         std::string()) != column.enumValues.end();
    }
    const TypeEntry* type =
        TypeRegistry::instance().findType(column.dataType);
    return type && (type->category == TypeCategory::String ||
                    type->category == TypeCategory::Binary);
}

static std::string valueFromRowMap(
    const std::map<std::string, std::string>& values,
    const std::string& columnName) {
    const auto value = values.find(columnName);
    return value == values.end() ? std::string() : value->second;
}

static std::string canonicalKeyValueFromRowMap(
    const std::map<std::string, std::string>& values,
    const TableSchema& table, const std::string& columnName) {
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == columnName) {
            return canonicalColumnKeyValue(
                table.cols[i], valueFromRowMap(values, columnName));
        }
    }
    return {};
}

static std::string buildCompositeKeyFromRowMap(
    const std::map<std::string, std::string>& values,
    const TableSchema& table,
    const std::vector<std::string>& columnNames) {
    std::string key;
    for (const auto& columnName : columnNames) {
        const Column* column = nullptr;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == columnName) {
                column = &table.cols[i];
                break;
            }
        }
        if (!column) continue;
        if (!key.empty()) key += '\x01';
        key += canonicalColumnKeyValue(
            *column, valueFromRowMap(values, columnName));
    }
    return key;
}

// Build a column-name -> data-type map from a TableSchema for expression eval.
static std::map<std::string, std::string> buildTypeHints(const dbms::TableSchema& tbl) {
    std::map<std::string, std::string> hints;
    for (size_t i = 0; i < tbl.len; ++i) {
        hints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
    }
    return hints;
}

// Callers that retain SQL NULL metadata need the evaluator's NULL bit as well
// as its text.  A string result equal to "NULL" is ordinary data and must not
// be folded into SQL NULL at this boundary.
static bool evalExpressionSqlValue(
    const std::string& exprSql,
    const std::map<std::string, std::string>& row,
    const std::map<std::string, std::string>& typeHints,
    const std::string& currentDB,
    std::string& value,
    bool& isNull,
    const std::set<std::string>* nullColumns = nullptr) {
    value.clear();
    isNull = false;
    if (exprSql.empty()) return false;
    const auto result = nullColumns
        ? dbms::ExprHelper::evalStringWithNulls(
              exprSql, row, *nullColumns, typeHints, currentDB)
        : dbms::ExprHelper::evalString(
              exprSql, row, typeHints, currentDB);
    if (!result.ok) return false;
    isNull = result.isNull;
    if (!isNull) value = result.value;
    return true;
}

static bool likeMatch(const std::string& text, const std::string& pattern, bool foldCase = false) {
    std::string t = text;
    std::string p = pattern;
    if (foldCase) {
        for (char& c : t) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        for (char& c : p) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    size_t i = 0, j = 0;
    size_t starIdx = std::string::npos, matchIdx = 0;
    while (i < t.size()) {
        if (j + 1 < p.size() && p[j] == 0x01) {
            // escaped literal (from LIKE ... ESCAPE): next pattern char
            // matches itself exactly.
            if (p[j + 1] != t[i]) return false;
            ++i; j += 2;
        } else if (j < p.size() && p[j] == '%') {
            // wildcard takes precedence over a literal '%' in the TEXT
            starIdx = j++;
            matchIdx = i;
        } else if (j < p.size() && (p[j] == t[i] || p[j] == '_')) {
            ++i; ++j;
        } else if (starIdx != std::string::npos) {
            j = starIdx + 1;
            i = ++matchIdx;
        } else {
            return false;
        }
    }
    while (j < p.size() && p[j] == '%') ++j;
    return j == p.size();
}

// REGEXP pattern matching (ECMAScript syntax), case-insensitive
static bool regexMatch(const std::string& text, const std::string& pattern) {
    try {
        std::regex re(pattern, std::regex::icase | std::regex::ECMAScript);
        return std::regex_search(text, re);
    } catch (...) {
        return false;
    }
}

// ========================================================================
// Helper: fixed-length string IO for the current binary catalog format.
// ========================================================================
static void writeFixedString(std::ostream& out, const std::string& s, size_t len) {
    std::string buf = s;
    buf.resize(len, '\0');
    out.write(buf.data(), static_cast<std::streamsize>(len));
}

static std::string readFixedString(std::istream& in, size_t len) {
    std::string buf(len, '\0');
    in.read(buf.data(), static_cast<std::streamsize>(len));
    auto pos = buf.find('\0');
    if (pos != std::string::npos) buf.resize(pos);
    return buf;
}

static bool validStoredIdentifier(const std::string& value, size_t fieldSize) {
    return value.find('\0') == std::string::npos && value.size() < fieldSize &&
           value.find('/') == std::string::npos &&
           value.find('\\') == std::string::npos &&
           value != "." && value != "..";
}

static std::string primaryKeyConstraintName(const TableSchema& table) {
    if (!table.hasPrimaryKey()) return {};
    const auto storedName = table.storageParams.find(
        PRIMARY_KEY_CONSTRAINT_NAME_PARAM);
    if (storedName != table.storageParams.end() &&
        !storedName->second.empty()) {
        return storedName->second;
    }
    return table.tablename + "_pkey";
}

// Auxiliary object definitions are stored in line-oriented sidecars.  Keep
// their object names safe both as path components and as metadata fields; a
// delimiter or newline here would make the definition ambiguous on reload.
static bool validMetadataObjectName(const std::string& value) {
    if (value.empty() || !validStoredIdentifier(value, MAX_TABLE_NAME_LEN)) {
        return false;
    }
    for (char c : value) {
        if (c == '|' || c == ':' || c == ',' || c == '\n' || c == '\r') {
            return false;
        }
    }
    return true;
}

static bool ensureMetadataDirectory(const std::filesystem::path& path) {
    std::error_code error;
    if (std::filesystem::exists(path, error)) {
        return !error && std::filesystem::is_directory(path, error) && !error;
    }
    if (!std::filesystem::create_directories(path, error) && error) return false;
    return std::filesystem::is_directory(path, error) && !error;
}

static DBStatus persistMetadata(const std::filesystem::path& path,
                                const std::string& contents) {
    return index_file::writeAtomically(path, contents) ? DBStatus::OK : DBStatus::IO_ERROR;
}

static bool normalizeForeignKeyAction(const std::string& action,
                                      std::string& normalized) {
    std::string compact;
    compact.reserve(action.size());
    for (const char c : action) {
        if (std::isspace(static_cast<unsigned char>(c)) || c == '_') {
            continue;
        }
        compact.push_back(static_cast<char>(
            std::tolower(static_cast<unsigned char>(c))));
    }
    if (compact.empty() || compact == "restrict" ||
        compact == "noaction") {
        normalized = "restrict";
        return true;
    }
    if (compact == "cascade") {
        normalized = "cascade";
        return true;
    }
    if (compact == "setnull") {
        normalized = "setnull";
        return true;
    }
    return false;
}

static bool validateTableSchemaIdentifiers(const TableSchema& tbl, std::string* error) {
    auto reject = [&](const std::string& value, size_t fieldSize, const char* kind) {
        if (validStoredIdentifier(value, fieldSize)) return false;
        if (error) *error = std::string(kind) + " exceeds the current 63-byte identifier limit";
        return true;
    };
    if (reject(tbl.tablename, MAX_TABLE_NAME_LEN, "table name")) return false;
    if (tbl.len > MAX_COLUMNS || tbl.fkLen > MAX_COLUMNS) {
        if (error) *error = "table exceeds the current column or constraint limit";
        return false;
    }
    std::set<std::string> columnNames;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (reject(tbl.cols[i].dataName, MAX_COL_NAME_LEN, "column name") ||
            reject(tbl.cols[i].dataType, MAX_TYPE_NAME_LEN, "type name") ||
            reject(tbl.cols[i].checkConstraintName, MAX_COL_NAME_LEN, "constraint name")) {
            return false;
        }
        if (!columnNames.insert(tbl.cols[i].dataName).second) {
            if (error) {
                *error = "duplicate column name: " + tbl.cols[i].dataName;
            }
            return false;
        }
        if (tbl.cols[i].checkExpr.size() >
            std::numeric_limits<uint16_t>::max()) {
            if (error) *error = "CHECK constraint expression is too long";
            return false;
        }
    }
    std::set<size_t> primaryKeyColumns;
    if (!tbl.pkColIndices.empty()) {
        if (tbl.pkColIndices.size() > tbl.len) {
            if (error) *error = "invalid primary key column metadata";
            return false;
        }
        for (const size_t columnIndex : tbl.pkColIndices) {
            if (columnIndex >= tbl.len ||
                !primaryKeyColumns.insert(columnIndex).second) {
                if (error) *error = "invalid primary key column metadata";
                return false;
            }
        }
        for (size_t columnIndex = 0; columnIndex < tbl.len;
             ++columnIndex) {
            if (tbl.cols[columnIndex].isPrimaryKey &&
                primaryKeyColumns.count(columnIndex) == 0) {
                if (error) {
                    *error = "primary key flags conflict with primary key columns";
                }
                return false;
            }
        }
    }
    for (const auto& name : tbl.uniqueConstraintNames) {
        if (reject(name, MAX_TABLE_NAME_LEN, "constraint name")) return false;
    }
    if (tbl.uniqueConstraints.size() > MAX_COLUMNS ||
        tbl.uniqueConstraintNames.size() > tbl.uniqueConstraints.size()) {
        if (error) *error = "invalid UNIQUE constraint metadata";
        return false;
    }
    for (const auto& constraint : tbl.uniqueConstraints) {
        if (constraint.empty() || constraint.size() > tbl.len) {
            if (error) *error = "UNIQUE constraint requires valid columns";
            return false;
        }
        std::set<size_t> distinctColumns;
        for (const size_t columnIndex : constraint) {
            if (columnIndex >= tbl.len ||
                !distinctColumns.insert(columnIndex).second) {
                if (error) *error = "invalid UNIQUE constraint column metadata";
                return false;
            }
        }
    }
    if (tbl.additionalCheckConstraints.size() > 1024) {
        if (error) *error = "too many CHECK constraints";
        return false;
    }
    for (const auto& check : tbl.additionalCheckConstraints) {
        if (reject(check.name, MAX_TABLE_NAME_LEN, "constraint name")) {
            return false;
        }
        if (check.expression.empty() || check.expression.size() > 1024 * 1024) {
            if (error) *error = "CHECK constraint expression is invalid";
            return false;
        }
    }
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        std::string normalizedDelete;
        std::string normalizedUpdate;
        if (reject(tbl.fks[i].name, MAX_TABLE_NAME_LEN, "constraint name") ||
            reject(tbl.fks[i].refTable, MAX_TABLE_NAME_LEN, "table name") ||
            !normalizeForeignKeyAction(
                tbl.fks[i].onDelete, normalizedDelete) ||
            !normalizeForeignKeyAction(
                tbl.fks[i].onUpdate, normalizedUpdate)) {
            if (error && error->empty()) {
                *error = "unsupported foreign key referential action";
            }
            return false;
        }
        for (const auto& name : tbl.fks[i].colNames) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
        for (const auto& name : tbl.fks[i].refCols) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
    }
    return true;
}

// ========================================================================
// Column / TableSchema
// ========================================================================
void Column::print() const {
    std::cout << "ColumnName: " << dataName << '\n';
    std::cout << "hasNull: " << isNull << '\n';
    std::cout << "PrimaryKey: " << isPrimaryKey << '\n';
    std::cout << "DataType: " << dataType << '\n';
    std::cout << "DataSize: " << dsize << "\n\n";
}

void TableSchema::append(const Column& ncol) {
    if (len < MAX_COLUMNS) {
        cols[len++] = ncol;
    }
}

void TableSchema::appendFK(const ForeignKey& fk) {
    if (fkLen < MAX_COLUMNS) {
        fks[fkLen++] = fk;
    }
}

void TableSchema::print() const {
    std::cout << tablename << "\n\n";
    for (size_t i = 0; i < len; ++i) cols[i].print();
    if (fkLen > 0) {
        std::cout << "Foreign Keys:\n";
        for (size_t i = 0; i < fkLen; ++i) {
            std::cout << "  ";
            for (size_t ci = 0; ci < fks[i].colNames.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].colNames[ci];
            }
            std::cout << " -> " << fks[i].refTable << "(";
            for (size_t ci = 0; ci < fks[i].refCols.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].refCols[ci];
            }
            std::cout << ") ON DELETE " << fks[i].onDelete;
            if (!fks[i].onUpdate.empty() && fks[i].onUpdate != "restrict")
                std::cout << " ON UPDATE " << fks[i].onUpdate;
            std::cout << "\n";
        }
    }
}

size_t TableSchema::rowSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) total += cols[i].dsize;
    return total + rowHeaderSize(formatVersion, len);
}

bool TableSchema::hasVariableLength() const {
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) return true;
    }
    return false;
}

size_t TableSchema::fixedDataSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!cols[i].isVariableLength) total += cols[i].dsize;
    }
    return total;
}

size_t TableSchema::varColCount() const {
    size_t count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) ++count;
    }
    return count;
}

size_t TableSchema::getVarColIndex(size_t colIdx) const {
    size_t idx = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (cols[i].isVariableLength) ++idx;
    }
    return idx;
}

size_t TableSchema::getFixedColOffset(size_t colIdx) const {
    size_t off = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (!cols[i].isVariableLength) off += cols[i].dsize;
    }
    return off;
}

// ========================================================================
// Column constructors
// ========================================================================
Column makeIntColumn(const std::string& name, bool isNull, int scale, bool isPK, bool isUnsigned) {
    Column c;
    c.dataName = name;
    c.isNull = isNull;
    c.isPrimaryKey = isPK;
    c.isUnsigned = isUnsigned;
    if (scale == 0) {
        c.dataType = isUnsigned ? "smallint unsigned" : "smallint";
        c.dsize = 2;
    } else if (scale == 1) {
        c.dataType = isUnsigned ? "tinyint unsigned" : "tinyint";
        c.dsize = 1;
    } else if (scale == 2) {
        c.dataType = isUnsigned ? "int unsigned" : "int";
        c.dsize = 4;
    } else {
        c.dataType = isUnsigned ? "bigint unsigned" : "bigint";
        c.dsize = 8;
    }
    return c;
}

Column makeStringColumn(const std::string& name, bool isNull, size_t length, bool isPK) {
    Column c;
    c.dataName = name;
    c.isNull = isNull;
    c.isPrimaryKey = isPK;
    c.dataType = "char";
    c.dsize = std::max(size_t(1), std::min(length, size_t(1005)));
    return c;
}

