// ========================================================================
// StorageEngine
// ========================================================================
StorageEngine::StorageEngine()
    : lockManager_(LockManager::global()) {
    if (!recoverAllDatabases()) {
        throw std::runtime_error(
            "WAL crash recovery failed; startup aborted to protect data");
    }
    cleanupStaleSessionTemporaryFiles();
    catalogService_ = std::make_unique<CatalogService>(*this);
    for (const auto& dbname : getDatabaseNames()) {
        if (!loadRuntimeStats(dbname, dbPath(dbname) / ".runtime_stats")) {
            throw std::runtime_error(
                "runtime statistics are corrupt or cannot be locked for database " + dbname);
        }
        if (!loadSqlStats(dbname, dbPath(dbname) / ".sql_stats")) {
            throw std::runtime_error(
                "SQL statistics are corrupt or cannot be locked for database " + dbname);
        }
        std::vector<Trigger> triggers;
        if (!loadTriggers(dbname, triggers)) {
            throw std::runtime_error(
                "trigger metadata is corrupt or unreadable for database " + dbname);
        }
    }
    // Keep trigger WHEN semantics available for direct StorageEngine users
    // (unit tests and embedded callers) as well as the interactive frontend.
    // main.cpp installs a richer session-aware evaluator at startup, but the
    // engine must not silently treat every WHEN clause as true when that
    // callback has not been registered yet.
    setWhenConditionEvaluator(
        [](const std::string& condition,
           const std::map<std::string, std::string>& newValues,
           const std::map<std::string, std::string>& oldValues) -> bool {
            std::map<std::string, std::string> values = oldValues;
            values.insert(newValues.begin(), newValues.end());
            std::string error;
            return ExprHelper::evalBool(condition, values, {}, &error);
        });
    lastBackgroundCheckpoint_ = std::chrono::steady_clock::now();
    startBackgroundWorker();
}

StorageEngine::TransactionContext& StorageEngine::transactionContext() const {
    const std::thread::id worker = std::this_thread::get_id();
    std::lock_guard<std::mutex> lock(transactionContextsMutex_);
    auto& context = transactionContexts_[worker];
    if (!context) context = std::make_unique<TransactionContext>();
    return *context;
}

void StorageEngine::endBackendSession() {
    const std::thread::id worker = std::this_thread::get_id();
    if (transactionContext().inTransaction) {
        rollbackTransaction();
    }
    std::lock_guard<std::mutex> lock(transactionContextsMutex_);
    transactionContexts_.erase(worker);
}

StorageEngine::~StorageEngine() {
    stopBackgroundWorker();

    // Persist deferred sequence counters before any teardown; rows inserted
    // outside an explicit transaction never pass a commit boundary.
    flushDeferredSequences();

    // Flush loaded heaps and indexes through the same WAL-aware path used by
    // transaction commit. This closes the crash window where an engine is
    // destroyed with an active transaction: recovery can apply the
    // before-image for uncommitted index changes instead of inheriting a file
    // written directly by a B+Tree/Hash destructor.
    if (catalogService_ && !catalogService_->persistAll()) {
        std::cerr << "[storage] failed to persist catalog during engine shutdown" << std::endl;
    }
    for (const auto& dbname : getDatabaseNames()) {
        if (!persistRuntimeStats(dbname, dbPath(dbname) / ".runtime_stats")) {
            std::cerr << "[storage] failed to persist runtime statistics for database "
                      << dbname << " during engine shutdown" << std::endl;
        }
        if (!persistSqlStats(dbname, dbPath(dbname) / ".sql_stats")) {
            std::cerr << "[storage] failed to persist SQL statistics for database "
                      << dbname << " during engine shutdown" << std::endl;
        }
        if (!flushDatabaseCaches(dbname)) {
            std::cerr << "[storage] failed to flush caches for database " << dbname
                      << " during engine shutdown" << std::endl;
        }
        if (auto* wal = getWAL(dbname)) {
            if (!wal->XLogFlush(wal->currentWriteLsn())) {
                std::cerr << "[storage] failed to flush WAL for database " << dbname
                          << " during engine shutdown" << std::endl;
            }
        }
    }

    // Heap writeback barriers capture their database WAL manager. Member
    // declaration order would otherwise destroy walManagers_ before
    // pageAllocators_; close every allocator explicitly while those captured
    // managers are still alive, including caches for a database removed
    // externally and therefore absent from getDatabaseNames().
    closeAllPageAllocators();

    // A process crash normally ends the whole process, but tests and embedded
    // callers can destroy an engine and construct another one in the same
    // process. Do not leave this engine's abandoned xids in the process-wide
    // active-transaction registry; recovery will still classify their WAL as
    // uncommitted in the next engine instance.
    std::vector<uint64_t> abandonedXids;
    {
        std::lock_guard<std::mutex> lock(transactionContextsMutex_);
        for (const auto& [worker, context] : transactionContexts_) {
            (void)worker;
            if (context && context->inTransaction && context->currentTxnId != 0) {
                abandonedXids.push_back(context->currentTxnId);
            }
        }
        transactionContexts_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        for (uint64_t xid : abandonedXids) {
            activeTransactions_.erase(xid);
            activeTransactionDatabases_.erase(xid);
        }
    }
    if (!abandonedXids.empty()) {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        for (uint64_t xid : abandonedXids) {
            ssiReadSets_.erase(xid);
            ssiWriteSets_.erase(xid);
            ssiReadRelations_.erase(xid);
            ssiWriteRelations_.erase(xid);
            ssiReadPages_.erase(xid);
            ssiWritePages_.erase(xid);
            ssiReadIndexPredicates_.erase(xid);
            ssiWriteIndexKeys_.erase(xid);
            ssiOutEdges_.erase(xid);
            ssiInEdges_.erase(xid);
            for (auto& entry : ssiInEdges_) entry.second.erase(xid);
            for (auto& entry : ssiOutEdges_) entry.second.erase(xid);
        }
    }
}

// ========================================================================
// Background workers (walwriter / bgwriter / checkpointer)
// ========================================================================

void StorageEngine::setBackgroundIntervals(uint32_t loopDelayMs,
                                           uint32_t checkpointIntervalMs) {
    std::lock_guard<std::mutex> lock(backgroundMutex_);
    backgroundLoopDelayMs_ = loopDelayMs;
    backgroundCheckpointIntervalMs_ = checkpointIntervalMs;
}

void StorageEngine::wakeBackgroundWorker() {
    backgroundCv_.notify_one();
}

void StorageEngine::startBackgroundWorker() {
    std::lock_guard<std::mutex> lock(backgroundMutex_);
    if (backgroundThread_.joinable()) return;
    backgroundStop_ = false;
    backgroundThread_ = std::thread(&StorageEngine::backgroundWorkerLoop, this);
}

void StorageEngine::stopBackgroundWorker() {
    {
        std::lock_guard<std::mutex> lock(backgroundMutex_);
        backgroundStop_ = true;
    }
    backgroundCv_.notify_all();
    if (backgroundThread_.joinable()) {
        backgroundThread_.join();
    }
}

void StorageEngine::backgroundWorkerLoop() {
    while (true) {
        std::unique_lock<std::mutex> lock(backgroundMutex_);
        auto delay = std::chrono::milliseconds(backgroundLoopDelayMs_);
        backgroundCv_.wait_for(lock, delay, [this] { return backgroundStop_.load(); });
        if (backgroundStop_.load()) break;
        lock.unlock();

        backgroundWalFlush();
        backgroundBufferFlush();
        backgroundCheckpoint();
        backgroundAutoVacuum();
        backgroundArchiveWAL();
    }
}

static std::filesystem::path archiveDestinationFromConfig();

void StorageEngine::backgroundArchiveWAL() {
    // Archiver: drain .ready segments into the configured destination.
    // Failures keep the .ready marker, so the next loop retries (matching
    // PostgreSQL's archiver retry semantics).
    const auto archiveDir = archiveDestinationFromConfig();
    if (archiveDir.empty()) return;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    for (auto& kv : walManagers_) {
        WALManager* wal = kv.second.get();
        if (!wal) continue;
        const auto pending = wal->pendingArchiveSegments();
        if (pending.empty()) continue;
        if (!wal->archivePendingSegments(archiveDir)) {
            std::cerr << "[archiver] incomplete archive pass for " << kv.first
                      << " (" << pending.size() << " segment(s) pending, will retry)"
                      << std::endl;
        }
    }
}

// Resolve the archive destination from g_config.archiveCommand.
//   "dir:<path>"       -> built-in copy mode, returns <path>
//   external command   -> not supported for built-in copying; returns empty
//   empty / unset      -> archiving disabled
static std::filesystem::path archiveDestinationFromConfig() {
    const std::string& cmd = g_config.archiveCommand;
    if (cmd.rfind("dir:", 0) == 0) {
        std::string dir = cmd.substr(4);
        while (!dir.empty() && dir.back() == ' ') dir.pop_back();
        if (!dir.empty()) return std::filesystem::path(dir);
    }
    return {};
}

void StorageEngine::backgroundAutoVacuum() {
    // Drain auto-vacuum requests off the query path (see
    // maybeAutoVacuum).  Each vacuum still takes the table locks it
    // needs, but no user statement is blocked for the vacuum's full
    // duration — only behind their own lock acquisitions.
    std::vector<std::pair<std::string, std::string>> todo;
    {
        std::lock_guard<std::mutex> lock(autoVacuumMutex_);
        for (const auto& [key, flag] : autoVacuumPending_) {
            if (flag) todo.push_back(key);
        }
        autoVacuumPending_.clear();
    }
    for (const auto& [dbname, tablename] : todo) {
        if (!databaseExists(dbname)) continue;
        const auto t0 = std::chrono::steady_clock::now();
        vacuum(dbname, tablename);
        const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - t0).count();
        if (ms > 500) {
            std::cerr << "[background] auto-vacuum " << dbname << "/"
                      << tablename << " took " << ms << "ms" << std::endl;
        }
    }
}

void StorageEngine::backgroundWalFlush() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    pruneMissingDatabaseCaches();
    // walwriter: fsync all WAL managers up to their current write LSN.
    for (auto& kv : walManagers_) {
        WALManager* wal = kv.second.get();
        if (wal) {
            if (!wal->XLogFlush(wal->currentWriteLsn())) {
                std::cerr << "[background] WAL flush failed for " << kv.first << std::endl;
            }
        }
    }
}

void StorageEngine::backgroundBufferFlush() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    // bgwriter: freeze only unpinned dirty pools, establish the matching WAL
    // durability boundary while their buffer mutex is held, then write. A
    // pinned dirty frame defers the whole allocator so page zero can never
    // publish a page that a statement is still changing.
    for (auto& kv : pageAllocators_) {
        PageAllocator* pa = kv.second.get();
        const size_t separator = kv.first.find('/');
        if (!pa || separator == std::string::npos || separator == 0) continue;
        const std::string dbname = kv.first.substr(0, separator);
        WALManager* wal = getWAL(dbname);
        if (!wal || !pa->flushDirtyUnpinned([wal]() {
                return wal->XLogFlush(wal->currentWriteLsn());
            })) {
            std::cerr << "[background] heap writeback failed for "
                      << kv.first << std::endl;
        }
    }
}

void StorageEngine::backgroundCheckpoint() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
        now - lastBackgroundCheckpoint_).count();
    if (elapsed < static_cast<int64_t>(backgroundCheckpointIntervalMs_)) {
        return;
    }
    lastBackgroundCheckpoint_ = now;

    // checkpointer: run checkpoint for every known database.
    auto dbs = getDatabaseNames();
    for (const auto& dbname : dbs) {
        const auto t0 = std::chrono::steady_clock::now();
        checkpoint(dbname);
        const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - t0).count();
        if (ms > 500) {
            std::cerr << "[background] checkpoint " << dbname
                      << " took " << ms << "ms" << std::endl;
        }
    }
}

// ========================================================================
// Primary Key Index
// ========================================================================
std::filesystem::path StorageEngine::dbPath(const std::string& dbname) const {
    return std::filesystem::path(dbname);
}

std::filesystem::path StorageEngine::schemaPath(const std::string& dbname,
                                                 const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".stc");
}

std::filesystem::path StorageEngine::paramsPath(const std::string& dbname,
                                                 const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".params");
}

std::filesystem::path StorageEngine::relationDir(const std::string& dbname,
                                                  const std::string& tablename) const {
    TableSchema tbl = getTableSchema(dbname, tablename);
    const std::string tablespace = tbl.tablespace.empty() ? "pg_default" : tbl.tablespace;
    auto base = tablespaceDir(dbname, tablespace);
    if (tablespace == "pg_default") return base;
    // A tablespace is shared by databases. Keep each database isolated just
    // like PostgreSQL's per-database tablespace subdirectories.
    return base / dbname;
}

std::filesystem::path StorageEngine::dataPath(const std::string& dbname,
                                               const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".dt");
}

std::filesystem::path StorageEngine::partitionDataPath(const std::string& dbname,
                                                        const std::string& tablename,
                                                        const std::string& partitionName) const {
    return relationDir(dbname, tablename) / (tablename + "#" + partitionName + ".dt");
}

std::filesystem::path StorageEngine::partitionDataPath(const std::string& dbname,
                                                        const std::string& tablename,
                                                        const std::string& partitionName,
                                                        const std::string& subPartitionName) const {
    return relationDir(dbname, tablename) / (tablename + "#" + partitionName + "#" + subPartitionName + ".dt");
}

namespace {

struct PartitionLeaf {
    std::string partition;
    std::string subPartition;
};

std::vector<PartitionLeaf> partitionLeaves(const TableSchema& table) {
    std::vector<std::string> partitions;
    if (table.partitionType == TableSchema::PartitionType::Range) {
        for (const auto& entry : table.rangePartitions) {
            partitions.push_back(entry.first);
        }
    } else if (table.partitionType == TableSchema::PartitionType::List) {
        for (const auto& entry : table.listPartitions) {
            partitions.push_back(entry.first);
        }
    } else if (table.partitionType == TableSchema::PartitionType::Hash) {
        for (size_t index = 0; index < table.hashPartitions; ++index) {
            partitions.push_back("p" + std::to_string(index));
        }
    }
    if (!table.defaultPartitionName.empty() &&
        std::find(partitions.begin(), partitions.end(),
                  table.defaultPartitionName) == partitions.end()) {
        partitions.push_back(table.defaultPartitionName);
    }

    std::vector<PartitionLeaf> leaves;
    for (const auto& partition : partitions) {
        if (table.subPartitionType == TableSchema::PartitionType::Hash) {
            for (size_t index = 0; index < table.subHashPartitions; ++index) {
                leaves.push_back(
                    {partition, "sp" + std::to_string(index)});
            }
        } else {
            leaves.push_back({partition, ""});
        }
    }
    return leaves;
}

// Heap WAL already carries a 32-bit fork number.  Derive a stable non-zero
// physical-partition identity from both path components instead of recording
// a local page as a parent-table page.  A collision is always detected by
// resolving against the complete schema and therefore fails closed.
uint32_t partitionForkNumber(const std::string& partition,
                             const std::string& subPartition) {
    uint32_t hash = 2166136261u;
    const auto add = [&](unsigned char byte, uint32_t& value) {
        value ^= byte;
        value *= 16777619u;
    };
    for (unsigned char byte : partition) add(byte, hash);
    add(0xffu, hash);
    for (unsigned char byte : subPartition) add(byte, hash);
    return hash == 0 ? 1u : hash;
}

bool resolvePartitionFork(const TableSchema& table, uint32_t forkNum,
                          PartitionLeaf& resolved, bool& collision) {
    collision = false;
    bool found = false;
    for (const auto& leaf : partitionLeaves(table)) {
        if (partitionForkNumber(leaf.partition, leaf.subPartition) != forkNum) {
            continue;
        }
        if (found) {
            collision = true;
            return false;
        }
        resolved = leaf;
        found = true;
    }
    return found;
}

bool partitionForkIsUnique(const TableSchema& table,
                           const std::string& partition,
                           const std::string& subPartition) {
    const uint32_t forkNum =
        partitionForkNumber(partition, subPartition);
    PartitionLeaf resolved;
    bool collision = false;
    return resolvePartitionFork(table, forkNum, resolved, collision) &&
           !collision && resolved.partition == partition &&
           resolved.subPartition == subPartition;
}

}  // namespace

std::filesystem::path StorageEngine::fsmPath(const std::string& dbname,
                                               const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".fsm");
}

std::filesystem::path StorageEngine::vmPath(const std::string& dbname,
                                             const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".vm");
}

// Relation forks and access-method files share the table-name prefix, while
// catalog sidecars (for example .stc and .params) remain in dbPath(). Keep
// this predicate in one place so migration, snapshot filtering and DROP use
// identical boundaries and never confuse table "t" with table "t2".
static bool isRelationPhysicalFileName(const std::string& name,
                                        const std::string& tablename) {
    static constexpr std::string_view tdeSuffix = ".tde";
    static constexpr std::string_view extentMarkerSuffix =
        ".extent_pending";
    if (name.size() > tdeSuffix.size() &&
        name.compare(name.size() - tdeSuffix.size(), tdeSuffix.size(),
                     tdeSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - tdeSuffix.size()), tablename);
    }
    if (name.size() > extentMarkerSuffix.size() &&
        name.compare(name.size() - extentMarkerSuffix.size(),
                     extentMarkerSuffix.size(), extentMarkerSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - extentMarkerSuffix.size()),
            tablename);
    }
    if (name == tablename + ".toast") return true;
    if (name.rfind(tablename + "#", 0) != 0 &&
        name.rfind(tablename + "_", 0) != 0 &&
        name.rfind(tablename + ".", 0) != 0) {
        return false;
    }
    const std::array<std::string, 11> suffixes = {
        ".dt", ".fsm", ".vm", ".idx", ".hidx", ".bidx", ".fti",
        ".gin", ".gist", ".spgist", ".brin"};
    for (const auto& suffix : suffixes) {
        if (name.size() >= suffix.size() &&
            name.compare(name.size() - suffix.size(), suffix.size(), suffix) == 0) {
            return true;
        }
    }
    return name == tablename + ".toastmeta" ||
           name.rfind(tablename + ".idx_", 0) == 0;
}

namespace {

constexpr uint32_t TRUNCATE_STATE_MAGIC = 0x314e5254u;  // 'TRN1'
constexpr uint32_t TRUNCATE_STATE_VERSION = 1;
constexpr size_t TRUNCATE_STATE_PAYLOAD_SIZE =
    sizeof(uint32_t) * 2 + sizeof(uint64_t);
constexpr size_t TRUNCATE_STATE_SIZE =
    TRUNCATE_STATE_PAYLOAD_SIZE + sizeof(uint64_t);

enum class TruncateStateRead { Missing, Valid, Invalid };

std::filesystem::path truncateStatePath(const StorageEngine& engine,
                                        const std::string& dbname,
                                        const std::string& tablename) {
    return engine.dbPath(dbname) / (tablename + ".truncate_state");
}

std::filesystem::path specializedIndexDirtyPath(
    const StorageEngine& engine, const std::string& dbname,
    const std::string& tablename) {
    return engine.dbPath(dbname) /
           (tablename + ".specialized_index_dirty");
}

bool specializedIndexesAreDirty(const StorageEngine& engine,
                                const std::string& dbname,
                                const std::string& tablename) {
    std::error_code error;
    const bool exists = std::filesystem::exists(
        specializedIndexDirtyPath(engine, dbname, tablename), error);
    // Metadata I/O errors must disable the access method rather than allow a
    // stale sidecar to become a complete source of candidate rows.
    return error || exists;
}

uint64_t truncateStateChecksum(const char* data, size_t size) {
    uint64_t hash = 1469598103934665603ULL;
    for (size_t i = 0; i < size; ++i) {
        hash ^= static_cast<unsigned char>(data[i]);
        hash *= 1099511628211ULL;
    }
    return hash;
}

template <typename T>
void appendTruncateState(std::string& bytes, const T& value) {
    bytes.append(reinterpret_cast<const char*>(&value), sizeof(value));
}

bool persistTruncateState(const StorageEngine& engine,
                          const std::string& dbname,
                          const std::string& tablename,
                          Lsn truncateLsn) {
    if (truncateLsn == INVALID_LSN) return false;
    std::string bytes;
    bytes.reserve(TRUNCATE_STATE_SIZE);
    appendTruncateState(bytes, TRUNCATE_STATE_MAGIC);
    appendTruncateState(bytes, TRUNCATE_STATE_VERSION);
    appendTruncateState(bytes, truncateLsn);
    const uint64_t checksum =
        truncateStateChecksum(bytes.data(), bytes.size());
    appendTruncateState(bytes, checksum);
    return index_file::writeAtomically(
        truncateStatePath(engine, dbname, tablename), bytes);
}

TruncateStateRead readTruncateState(const StorageEngine& engine,
                                    const std::string& dbname,
                                    const std::string& tablename,
                                    Lsn& truncateLsn) {
    truncateLsn = INVALID_LSN;
    const auto path = truncateStatePath(engine, dbname, tablename);
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return TruncateStateRead::Invalid;
    if (!exists) return TruncateStateRead::Missing;
    if (!std::filesystem::is_regular_file(path, error) || error ||
        std::filesystem::file_size(path, error) != TRUNCATE_STATE_SIZE ||
        error) {
        return TruncateStateRead::Invalid;
    }
    std::ifstream input(path, std::ios::binary);
    if (!input) return TruncateStateRead::Invalid;
    std::string bytes(TRUNCATE_STATE_SIZE, '\0');
    input.read(bytes.data(), static_cast<std::streamsize>(bytes.size()));
    if (!input || input.peek() != std::char_traits<char>::eof()) {
        return TruncateStateRead::Invalid;
    }
    uint32_t magic = 0;
    uint32_t version = 0;
    uint64_t storedLsn = 0;
    uint64_t storedChecksum = 0;
    size_t offset = 0;
    std::memcpy(&magic, bytes.data() + offset, sizeof(magic));
    offset += sizeof(magic);
    std::memcpy(&version, bytes.data() + offset, sizeof(version));
    offset += sizeof(version);
    std::memcpy(&storedLsn, bytes.data() + offset, sizeof(storedLsn));
    offset += sizeof(storedLsn);
    std::memcpy(
        &storedChecksum, bytes.data() + offset, sizeof(storedChecksum));
    if (magic != TRUNCATE_STATE_MAGIC ||
        version != TRUNCATE_STATE_VERSION || storedLsn == INVALID_LSN ||
        storedChecksum != truncateStateChecksum(
            bytes.data(), TRUNCATE_STATE_PAYLOAD_SIZE)) {
        return TruncateStateRead::Invalid;
    }
    truncateLsn = storedLsn;
    return TruncateStateRead::Valid;
}

bool decodeTruncateWalPayload(const std::vector<char>& data,
                              std::string& tablename) {
    tablename.clear();
    if (data.size() < sizeof(uint32_t)) return false;
    uint32_t length = 0;
    std::memcpy(&length, data.data(), sizeof(length));
    if (length == 0 || length >= MAX_TABLE_NAME_LEN ||
        length > data.size() - sizeof(length)) {
        return false;
    }
    tablename.assign(data.data() + sizeof(length), length);
    if (!validStoredIdentifier(tablename, MAX_TABLE_NAME_LEN)) return false;
    const size_t consumed = sizeof(length) + length;
    if (data.size() - consumed > 7) return false;
    return std::all_of(
        data.begin() + static_cast<std::ptrdiff_t>(consumed), data.end(),
        [](char byte) { return byte == 0; });
}

bool decodeHeapWalTableName(const XLogRecord& record,
                            std::string& tablename) {
    tablename.clear();
    if (record.rmid() != RM_HEAP_ID ||
        record.data.size() < sizeof(uint32_t)) {
        return false;
    }
    uint32_t length = 0;
    std::memcpy(&length, record.data.data(), sizeof(length));
    if (length == 0 || length >= MAX_TABLE_NAME_LEN ||
        length > record.data.size() - sizeof(length)) {
        return false;
    }
    tablename.assign(record.data.data() + sizeof(length), length);
    return validStoredIdentifier(tablename, MAX_TABLE_NAME_LEN);
}

bool syncDirectoryDurably(const std::filesystem::path& path) {
    const int descriptor =
        ::open(path.c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (descriptor < 0) return false;
    const bool synced = ::fsync(descriptor) == 0;
    const bool closed = ::close(descriptor) == 0;
    return synced && closed;
}

constexpr std::string_view kReindexSwapMarkerSuffix = ".reindex_swap";

class ResourceUnlockGuard {
public:
    ResourceUnlockGuard(LockManager& manager, const std::string& resource)
        : manager_(manager), resource_(resource) {}
    ResourceUnlockGuard(const ResourceUnlockGuard&) = delete;
    ResourceUnlockGuard& operator=(const ResourceUnlockGuard&) = delete;
    ~ResourceUnlockGuard() { manager_.unlock(resource_); }

private:
    LockManager& manager_;
    const std::string& resource_;
};

struct ReindexSwapEntry {
    std::filesystem::path target;
    std::filesystem::path temporary;
    std::filesystem::path backup;
};

std::filesystem::path reindexSidecar(const std::filesystem::path& path) {
    return std::filesystem::path(path.string() + ".tde");
}

bool normalizedAbsolutePath(const std::filesystem::path& path,
                            std::filesystem::path& normalized) {
    std::error_code error;
    normalized = std::filesystem::absolute(path, error).lexically_normal();
    return !error && !normalized.empty();
}

bool inspectRegularFile(const std::filesystem::path& path, bool& exists) {
    std::error_code error;
    exists = std::filesystem::exists(path, error);
    if (error) return false;
    return !exists ||
           (std::filesystem::is_regular_file(path, error) && !error);
}

bool removeRegularFileIfPresent(const std::filesystem::path& path) {
    bool exists = false;
    if (!inspectRegularFile(path, exists)) return false;
    if (!exists) return true;
    std::error_code error;
    return std::filesystem::remove(path, error) && !error;
}

bool syncRegularFileDurably(const std::filesystem::path& path) {
    const int descriptor = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (descriptor < 0) return false;
    const bool synced = ::fsync(descriptor) == 0;
    const bool closed = ::close(descriptor) == 0;
    return synced && closed;
}

bool copyRegularFileDurably(const std::filesystem::path& source,
                            const std::filesystem::path& destination) {
    bool sourceExists = false;
    if (!inspectRegularFile(source, sourceExists) || !sourceExists ||
        !removeRegularFileIfPresent(destination)) {
        return false;
    }
    std::error_code error;
    if (!std::filesystem::copy_file(
            source, destination,
            std::filesystem::copy_options::none, error) || error) {
        return false;
    }
    return syncRegularFileDurably(destination);
}

bool validReindexSwapEntry(const ReindexSwapEntry& entry,
                           const std::filesystem::path& relationRoot,
                           const std::string& tablename) {
    std::filesystem::path target;
    std::filesystem::path temporary;
    std::filesystem::path backup;
    std::filesystem::path root;
    if (!normalizedAbsolutePath(entry.target, target) ||
        !normalizedAbsolutePath(entry.temporary, temporary) ||
        !normalizedAbsolutePath(entry.backup, backup) ||
        !normalizedAbsolutePath(relationRoot, root) ||
        target.parent_path() != root || temporary.parent_path() != root ||
        backup.parent_path() != root) {
        return false;
    }

    const std::string targetName = target.filename().string();
    const bool primary = targetName == tablename + ".idx";
    const bool secondary =
        targetName.rfind(tablename + "_", 0) == 0 &&
        targetName.size() > tablename.size() + 5 &&
        targetName.compare(targetName.size() - 4, 4, ".idx") == 0;
    const bool composite =
        targetName.rfind(tablename + ".idx_", 0) == 0 &&
        targetName.size() > tablename.size() + 5;
    if (!primary && !secondary && !composite) return false;

    const std::string temporaryName = temporary.filename().string();
    const std::string backupName = backup.filename().string();
    return temporaryName.rfind(targetName + ".reindex.tmp.", 0) == 0 &&
           backupName.rfind(targetName + ".reindex.old.", 0) == 0;
}

bool serializeReindexSwapPlan(const std::vector<ReindexSwapEntry>& entries,
                              std::string& serialized) {
    if (entries.empty() || entries.size() > 4096) return false;
    std::ostringstream output;
    output << "DBMS_REINDEX_SWAP_V1\n" << entries.size() << '\n';
    for (const auto& entry : entries) {
        output << std::quoted(entry.target.string()) << ' '
               << std::quoted(entry.temporary.string()) << ' '
               << std::quoted(entry.backup.string()) << '\n';
    }
    if (!output) return false;
    serialized = output.str();
    return true;
}

bool readReindexSwapPlan(const std::filesystem::path& marker,
                         const std::filesystem::path& relationRoot,
                         const std::string& tablename,
                         std::vector<ReindexSwapEntry>& entries) {
    entries.clear();
    std::ifstream input(marker);
    std::string magic;
    size_t count = 0;
    if (!std::getline(input, magic) || magic != "DBMS_REINDEX_SWAP_V1" ||
        !(input >> count) || count == 0 || count > 4096) {
        return false;
    }

    std::set<std::filesystem::path> targets;
    for (size_t i = 0; i < count; ++i) {
        std::string targetText;
        std::string temporaryText;
        std::string backupText;
        if (!(input >> std::quoted(targetText) >> std::quoted(temporaryText) >>
              std::quoted(backupText))) {
            return false;
        }
        ReindexSwapEntry entry{
            std::filesystem::path(targetText),
            std::filesystem::path(temporaryText),
            std::filesystem::path(backupText)};
        if (!validReindexSwapEntry(entry, relationRoot, tablename)) return false;
        if (!normalizedAbsolutePath(entry.target, entry.target) ||
            !normalizedAbsolutePath(entry.temporary, entry.temporary) ||
            !normalizedAbsolutePath(entry.backup, entry.backup) ||
            !targets.insert(entry.target).second) {
            return false;
        }
        entries.push_back(std::move(entry));
    }
    std::string trailing;
    return !(input >> trailing) && input.eof() && !input.bad();
}

bool recoverReindexSwapPlan(const std::vector<ReindexSwapEntry>& entries,
                            const std::filesystem::path& marker) {
    std::set<std::filesystem::path> directories;
    for (const auto& entry : entries) {
        const auto targetSidecar = reindexSidecar(entry.target);
        const auto temporarySidecar = reindexSidecar(entry.temporary);
        const auto backupSidecar = reindexSidecar(entry.backup);
        const auto restoreMain =
            std::filesystem::path(entry.backup.string() + ".restore");
        const auto restoreSidecar = reindexSidecar(restoreMain);
        directories.insert(entry.target.parent_path());

        bool backupExists = false;
        bool backupSidecarExists = false;
        if (!inspectRegularFile(entry.backup, backupExists) ||
            !inspectRegularFile(backupSidecar, backupSidecarExists)) {
            return false;
        }

        if (backupExists) {
            if (!copyRegularFileDurably(entry.backup, restoreMain)) return false;
            if (backupSidecarExists) {
                if (!copyRegularFileDurably(
                        backupSidecar, restoreSidecar)) {
                    return false;
                }
            } else {
                bool targetSidecarExists = false;
                if (!inspectRegularFile(
                        targetSidecar, targetSidecarExists) ||
                    !targetSidecarExists) {
                    return false;
                }
            }

            std::error_code error;
            std::filesystem::rename(restoreMain, entry.target, error);
            if (error) return false;
            if (backupSidecarExists) {
                std::filesystem::rename(
                    restoreSidecar, targetSidecar, error);
                if (error) return false;
            }
            if (!syncDirectoryDurably(entry.target.parent_path())) return false;
        } else {
            bool targetExists = false;
            bool targetSidecarExists = false;
            bool temporaryExists = false;
            bool temporarySidecarExists = false;
            if (!inspectRegularFile(entry.target, targetExists) ||
                !inspectRegularFile(targetSidecar, targetSidecarExists) ||
                !inspectRegularFile(entry.temporary, temporaryExists) ||
                !inspectRegularFile(
                    temporarySidecar, temporarySidecarExists) ||
                (temporaryExists && !temporarySidecarExists)) {
                return false;
            }

            // A marker is published only after every replacement pair is
            // durable. If no rollback main exists but a temporary remains,
            // either the old index was already absent (for example during an
            // ALTER rewrite) or the crash preceded the first backup rename.
            // Roll the complete replacement forward. Renaming the main file
            // first makes the only intermediate state recognizable by the
            // remaining temporary sidecar on the next recovery attempt.
            std::error_code error;
            if (temporaryExists) {
                if (!removeRegularFileIfPresent(entry.target)) return false;
                std::filesystem::rename(
                    entry.temporary, entry.target, error);
                if (error) return false;
                targetExists = true;
            }
            if (temporarySidecarExists) {
                if (!targetExists ||
                    !removeRegularFileIfPresent(targetSidecar)) {
                    return false;
                }
                std::filesystem::rename(
                    temporarySidecar, targetSidecar, error);
                if (error) return false;
                targetSidecarExists = true;
            }
            if (!targetExists || !targetSidecarExists ||
                !syncDirectoryDurably(entry.target.parent_path())) {
                return false;
            }
        }

        // Remove the main backup first. If recovery crashes during cleanup,
        // the absence of that file proves the complete target pair should be
        // retained; a leftover sidecar backup is then only garbage.
        if (!removeRegularFileIfPresent(entry.backup) ||
            !removeRegularFileIfPresent(backupSidecar) ||
            !removeRegularFileIfPresent(entry.temporary) ||
            !removeRegularFileIfPresent(temporarySidecar) ||
            !removeRegularFileIfPresent(restoreMain) ||
            !removeRegularFileIfPresent(restoreSidecar)) {
            return false;
        }
    }
    for (const auto& directory : directories) {
        if (!syncDirectoryDurably(directory)) return false;
    }
    if (!removeRegularFileIfPresent(marker)) return false;
    return syncDirectoryDurably(marker.parent_path());
}

bool recoverReindexSwapMarker(const std::filesystem::path& marker,
                              const std::filesystem::path& relationRoot,
                              const std::string& tablename) {
    std::vector<ReindexSwapEntry> entries;
    return readReindexSwapPlan(
               marker, relationRoot, tablename, entries) &&
           recoverReindexSwapPlan(entries, marker);
}

bool clearSpecializedIndexDirty(const StorageEngine& engine,
                                const std::string& dbname,
                                const std::string& tablename) {
    const auto path = specializedIndexDirtyPath(engine, dbname, tablename);
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return false;
    if (!exists) return true;
    if (!std::filesystem::remove(path, error) || error) return false;
    return syncDirectoryDurably(path.parent_path());
}

}  // namespace

std::filesystem::path StorageEngine::tableListPath(const std::string& dbname) const {
    return dbPath(dbname) / "tlist.lst";
}

static int comparePartitionValues(const TableSchema& table,
                                  const std::string& left,
                                  const std::string& right,
                                  bool leftIsBound,
                                  bool rightIsBound) {
    auto sentinel = [](const std::string& value, bool isBound) {
        if (!isBound) return 0;
        std::string normalized = trim(value);
        std::transform(normalized.begin(), normalized.end(),
                       normalized.begin(), [](unsigned char byte) {
                           return static_cast<char>(std::toupper(byte));
                       });
        if (normalized == "MINVALUE") return -1;
        if (normalized == "MAXVALUE") return 1;
        return 0;
    };
    const int leftSentinel = sentinel(left, leftIsBound);
    const int rightSentinel = sentinel(right, rightIsBound);
    if (leftSentinel || rightSentinel) {
        if (leftSentinel == rightSentinel) return 0;
        if (leftSentinel == -1 || rightSentinel == 1) return -1;
        return 1;
    }

    const Column* keyColumn = nullptr;
    for (size_t index = 0; index < table.len; ++index) {
        if (table.cols[index].dataName == table.partitionKey) {
            keyColumn = &table.cols[index];
            break;
        }
    }
    if (keyColumn) {
        const auto equal = StorageEngine::compareValues(
            *keyColumn, left, false, right, false, "=");
        if (equal == StorageEngine::PredicateTruth::True) return 0;
        const auto less = StorageEngine::compareValues(
            *keyColumn, left, false, right, false, "<");
        if (less == StorageEngine::PredicateTruth::True) return -1;
        const auto greater = StorageEngine::compareValues(
            *keyColumn, left, false, right, false, ">");
        if (greater == StorageEngine::PredicateTruth::True) return 1;
    }

    // Some legacy schemas store abbreviated timestamp bounds such as a year.
    // Retain a deterministic fallback for those catalogs while using typed
    // ordering whenever both values are valid for the partition key.
    return left.compare(right);
}

std::string StorageEngine::getPartitionName(const TableSchema& tbl, const std::string& keyVal) const {
    if (tbl.partitionType == TableSchema::PartitionType::None) return "";
    if (tbl.partitionType == TableSchema::PartitionType::Range) {
        for (const auto& rp : tbl.rangePartitions) {
            if (comparePartitionValues(
                    tbl, keyVal, rp.second, false, true) < 0) {
                return rp.first;
            }
        }
        if (!tbl.defaultPartitionName.empty()) return tbl.defaultPartitionName;
        return "";
    }
    if (tbl.partitionType == TableSchema::PartitionType::List) {
        for (const auto& lp : tbl.listPartitions) {
            for (const auto& v : lp.second) {
                if (v == keyVal) return lp.first;
            }
        }
        return tbl.defaultPartitionName;
    }
    if (tbl.partitionType == TableSchema::PartitionType::Hash) {
        if (tbl.hashPartitions == 0) return "";
        size_t h = std::hash<std::string>{}(keyVal) % tbl.hashPartitions;
        return "p" + std::to_string(h);
    }
    return "";
}

std::string StorageEngine::getSubPartitionName(const TableSchema& tbl, const std::string& keyVal) const {
    if (tbl.subPartitionType == TableSchema::PartitionType::None) return "";
    if (tbl.subPartitionType == TableSchema::PartitionType::Hash) {
        if (tbl.subHashPartitions == 0) return "";
        size_t h = std::hash<std::string>{}(keyVal) % tbl.subHashPartitions;
        return "sp" + std::to_string(h);
    }
    return "";
}

std::vector<std::string> StorageEngine::getTargetPartitions(
    const TableSchema& tbl, const std::vector<Condition>& conds) const {
    std::vector<std::string> result;
    if (tbl.partitionType == TableSchema::PartitionType::None) return result;
    if (tbl.partitionKey.empty()) return result;

    // Collect partition-key related conditions
    for (const auto& c : conds) {
        if (c.colName != tbl.partitionKey) continue;
        if (tbl.partitionType == TableSchema::PartitionType::Range) {
            if (c.op == "=") {
                const std::string partition =
                    getPartitionName(tbl, c.value);
                if (!partition.empty()) result.push_back(partition);
            }
            // A range predicate can intersect several intervals.  The schema
            // currently persists only each upper bound, not the declared
            // lower bound, so proving a narrower set is unsafe.  An empty
            // result deliberately selects all leaves and the normal predicate
            // recheck filters them without false negatives.
        } else if (tbl.partitionType == TableSchema::PartitionType::List) {
            if (c.op == "=") {
                const std::string partition =
                    getPartitionName(tbl, c.value);
                if (!partition.empty()) result.push_back(partition);
            }
        } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
            if (c.op == "=") {
                const std::string partition =
                    getPartitionName(tbl, c.value);
                if (!partition.empty()) result.push_back(partition);
            }
        }
    }
    // Deduplicate
    std::sort(result.begin(), result.end());
    result.erase(std::unique(result.begin(), result.end()), result.end());
    return result;
}

DBStatus StorageEngine::attachPartition(const std::string& dbname,
                                          const std::string& tablename,
                                          const std::string& partitionName,
                                          const std::string& partitionSpec) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    if (tbl.partitionType == TableSchema::PartitionType::None) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;  // table is not partitioned
    }

    // Check partition name doesn't already exist
    auto nameExists = [&]() -> bool {
        if (tbl.partitionType == TableSchema::PartitionType::Range) {
            for (const auto& rp : tbl.rangePartitions)
                if (rp.first == partitionName) return true;
            if (tbl.defaultPartitionName == partitionName) return true;
        } else if (tbl.partitionType == TableSchema::PartitionType::List) {
            for (const auto& lp : tbl.listPartitions)
                if (lp.first == partitionName) return true;
            if (tbl.defaultPartitionName == partitionName) return true;
        } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
            if (partitionName.size() > 1 && partitionName[0] == 'p') {
                try {
                    size_t hidx = std::stoull(partitionName.substr(1));
                    if (hidx < tbl.hashPartitions) return true;
                } catch (...) {
                    return false;
                }
            }
        }
        return false;
    };
    if (nameExists()) {
        lockManager_.unlock(tablename);
        return DBStatus::TABLE_ALREADY_EXISTS;
    }

    // Parse partition spec based on partition type
    std::string specLower = partitionSpec;
    std::transform(specLower.begin(), specLower.end(), specLower.begin(), ::tolower);

    if (tbl.partitionType == TableSchema::PartitionType::Range) {
        if (trim(specLower) == "default") {
            if (!tbl.defaultPartitionName.empty()) {
                lockManager_.unlock(tablename);
                return DBStatus::TABLE_ALREADY_EXISTS;
            }
            tbl.defaultPartitionName = partitionName;
        } else {
            // Parse: FOR VALUES FROM (val) TO (val)
            size_t fromPos = specLower.find("from");
            size_t toPos = specLower.find(" to ");
            if (fromPos == std::string::npos || toPos == std::string::npos) {
                lockManager_.unlock(tablename);
                return DBStatus::SYNTAX_ERROR;
            }
            size_t val1lp = partitionSpec.find('(', fromPos);
            size_t val1rp = partitionSpec.find(')', val1lp);
            size_t val2lp = partitionSpec.find('(', toPos);
            size_t val2rp = partitionSpec.find(')', val2lp);
            if (val1lp == std::string::npos || val1rp == std::string::npos ||
                val2lp == std::string::npos || val2rp == std::string::npos) {
                lockManager_.unlock(tablename);
                return DBStatus::SYNTAX_ERROR;
            }
            std::string lowerBound = trim(partitionSpec.substr(val1lp + 1, val1rp - val1lp - 1));
            std::string upperBound = trim(partitionSpec.substr(val2lp + 1, val2rp - val2lp - 1));
            // Strip quotes
            auto unquote = [](std::string& s) {
                if (s.size() >= 2 && ((s.front() == '\'' && s.back() == '\'') ||
                                       (s.front() == '"' && s.back() == '"')))
                    s = s.substr(1, s.size() - 2);
            };
            unquote(lowerBound);
            unquote(upperBound);
            if (comparePartitionValues(
                    tbl, lowerBound, upperBound, true, true) >= 0) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            // Routing is driven by the persisted upper bounds, so maintain
            // their typed order.  Comparing an existing upper bound to the
            // new lower bound inserted contiguous ranges in reverse order
            // when both values were equal.
            auto it = tbl.rangePartitions.begin();
            while (it != tbl.rangePartitions.end() &&
                   comparePartitionValues(
                       tbl, it->second, upperBound, true, true) < 0) {
                ++it;
            }
            if (it != tbl.rangePartitions.end() &&
                comparePartitionValues(
                    tbl, it->second, upperBound, true, true) == 0) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            tbl.rangePartitions.insert(it, {partitionName, upperBound});
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::List) {
        if (trim(specLower) == "default") {
            if (!tbl.defaultPartitionName.empty()) {
                lockManager_.unlock(tablename);
                return DBStatus::TABLE_ALREADY_EXISTS;
            }
            tbl.defaultPartitionName = partitionName;
        } else {
            // Parse: FOR VALUES IN (v1, v2, ...)
            size_t inPos = specLower.find(" in ");
            if (inPos == std::string::npos) {
                lockManager_.unlock(tablename);
                return DBStatus::SYNTAX_ERROR;
            }
            size_t valLp = partitionSpec.find('(', inPos);
            size_t valRp = partitionSpec.find(')', valLp);
            if (valLp == std::string::npos || valRp == std::string::npos) {
                lockManager_.unlock(tablename);
                return DBStatus::SYNTAX_ERROR;
            }
            std::string valsStr = partitionSpec.substr(valLp + 1, valRp - valLp - 1);
            std::vector<std::string> values;
            size_t cp = 0;
            while (cp < valsStr.size()) {
                size_t c = valsStr.find(',', cp);
                std::string v = trim(valsStr.substr(cp, c - cp));
                if (v.size() >= 2 && ((v.front() == '\'' && v.back() == '\'') ||
                                       (v.front() == '"' && v.back() == '"')))
                    v = v.substr(1, v.size() - 2);
                if (!v.empty()) values.push_back(v);
                if (c == std::string::npos) break;
                cp = c + 1;
            }
            tbl.listPartitions.push_back({partitionName, values});
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
        // Hash attach: increase hash partition count if partition name is "pN" where N == current count
        // e.g., ATTACH PARTITION p4 when hashPartitions is 4 → hashPartitions becomes 5
        if (partitionName.size() > 1 && partitionName[0] == 'p') {
            try {
                size_t idx = std::stoull(partitionName.substr(1));
                if (idx == tbl.hashPartitions) {
                    tbl.hashPartitions = idx + 1;
                } else {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE; // hash partitions must be attached in order
                }
            } catch (...) {
                lockManager_.unlock(tablename);
                return DBStatus::SYNTAX_ERROR;
            }
        } else {
            lockManager_.unlock(tablename);
            return DBStatus::SYNTAX_ERROR;
        }
    }

    // Create the partition data file
    {
        auto ppa = std::make_unique<PageAllocator>(
            partitionDataPath(dbname, tablename, partitionName).string(), tbl.rowSize(), pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion);
        ppa->open();
        ppa->close();
    }

    // Rewrite schema
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        std::error_code ignored;
        std::filesystem::remove(
            partitionDataPath(dbname, tablename, partitionName), ignored);
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::detachPartition(const std::string& dbname,
                                          const std::string& tablename,
                                          const std::string& partitionName) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    if (tbl.partitionType == TableSchema::PartitionType::None) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    bool found = false;
    if (tbl.partitionType == TableSchema::PartitionType::Range) {
        if (tbl.defaultPartitionName == partitionName) {
            tbl.defaultPartitionName.clear();
            found = true;
        }
        auto it = std::find_if(tbl.rangePartitions.begin(), tbl.rangePartitions.end(),
                                [&](const auto& rp) { return rp.first == partitionName; });
        if (!found && it != tbl.rangePartitions.end()) {
            tbl.rangePartitions.erase(it);
            found = true;
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::List) {
        if (tbl.defaultPartitionName == partitionName) {
            tbl.defaultPartitionName.clear();
            found = true;
        }
        auto it = std::find_if(tbl.listPartitions.begin(), tbl.listPartitions.end(),
                                [&](const auto& lp) { return lp.first == partitionName; });
        if (!found && it != tbl.listPartitions.end()) {
            tbl.listPartitions.erase(it);
            found = true;
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
        // Removing a hash partition reduces count; only the last partition can be detached
        if (partitionName == "p" + std::to_string(tbl.hashPartitions - 1) && tbl.hashPartitions > 0) {
            tbl.hashPartitions--;
            found = true;
        }
    }

    if (!found) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Rewrite schema
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    // Close any cached page allocator for the detached partition
    pageAllocators_.erase(dbname + "/" + tablename + "#" + partitionName);

    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

std::filesystem::path StorageEngine::walPath(const std::string& dbname) const {
    return dbPath(dbname) / "pg_wal";
}

std::filesystem::path StorageEngine::checkpointPath(const std::string& dbname) const {
    return dbPath(dbname) / "checkpoint";
}

std::filesystem::path StorageEngine::viewPath(const std::string& dbname,
                                               const std::string& viewname) const {
    return viewsDir(dbname) / (viewname + ".view");
}

std::filesystem::path StorageEngine::viewsDir(const std::string& dbname) const {
    return dbPath(dbname) / ".views";
}

namespace {

struct StoredCollation {
    std::string name;
    std::string provider;
    std::string locale;
};

constexpr const char* COLLATION_METADATA_V2_PREFIX = "DBMS_COLLATION_V2:";

std::string encodeCollationField(const std::string& value) {
    static constexpr char hex[] = "0123456789abcdef";
    std::string encoded;
    encoded.reserve(value.size() * 2);
    for (unsigned char byte : value) {
        encoded.push_back(hex[byte >> 4]);
        encoded.push_back(hex[byte & 0x0f]);
    }
    return encoded;
}

bool decodeCollationField(const std::string& encoded, std::string& value) {
    if (encoded.size() % 2 != 0) return false;
    auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };

    value.clear();
    value.reserve(encoded.size() / 2);
    for (size_t i = 0; i < encoded.size(); i += 2) {
        const int high = nibble(encoded[i]);
        const int low = nibble(encoded[i + 1]);
        if (high < 0 || low < 0) {
            value.clear();
            return false;
        }
        value.push_back(static_cast<char>((high << 4) | low));
    }
    return true;
}

bool validStoredCollation(const StoredCollation& collation) {
    return validMetadataObjectName(collation.name) &&
           collation.provider.find('\0') == std::string::npos &&
           collation.locale.find('\0') == std::string::npos;
}

bool parseCollationRecord(const std::string& line, StoredCollation& collation) {
    collation = {};
    if (line.rfind(COLLATION_METADATA_V2_PREFIX, 0) == 0) {
        const size_t prefixLength =
            std::char_traits<char>::length(COLLATION_METADATA_V2_PREFIX);
        const size_t nameEnd = line.find('|', prefixLength);
        if (nameEnd == std::string::npos) return false;
        const size_t providerEnd = line.find('|', nameEnd + 1);
        if (providerEnd == std::string::npos ||
            line.find('|', providerEnd + 1) != std::string::npos) {
            return false;
        }
        if (!decodeCollationField(
                line.substr(prefixLength, nameEnd - prefixLength),
                collation.name) ||
            !decodeCollationField(
                line.substr(nameEnd + 1, providerEnd - nameEnd - 1),
                collation.provider) ||
            !decodeCollationField(
                line.substr(providerEnd + 1), collation.locale)) {
            return false;
        }
    } else {
        const size_t nameEnd = line.find('|');
        if (nameEnd == std::string::npos) return false;
        const size_t providerEnd = line.find('|', nameEnd + 1);
        if (providerEnd == std::string::npos) return false;
        collation.name = line.substr(0, nameEnd);
        collation.provider = line.substr(nameEnd + 1, providerEnd - nameEnd - 1);
        collation.locale = line.substr(providerEnd + 1);
    }
    return validStoredCollation(collation);
}

bool loadStoredCollations(const std::filesystem::path& path,
                          std::vector<StoredCollation>& collations) {
    collations.clear();
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return false;
    if (!exists) return true;

    std::ifstream input(path);
    if (!input) return false;
    std::unordered_set<std::string> names;
    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        StoredCollation collation;
        if (!parseCollationRecord(line, collation) ||
            !names.insert(collation.name).second) {
            return false;
        }
        collations.push_back(std::move(collation));
    }
    return !input.bad();
}

std::string serializeStoredCollations(
    const std::vector<StoredCollation>& collations) {
    std::ostringstream serialized;
    for (const auto& collation : collations) {
        serialized << COLLATION_METADATA_V2_PREFIX
                   << encodeCollationField(collation.name) << '|'
                   << encodeCollationField(collation.provider) << '|'
                   << encodeCollationField(collation.locale) << '\n';
    }
    return serialized.str();
}

struct ResolvedCollation {
    std::string comparisonName;
    bool usesSystemLocale = false;
    bool isBinary = true;
};

bool physicalCollationReference(const std::string& reference,
                                std::string& physicalName) {
    physicalName.clear();
    if (reference.empty() || reference.find('\0') != std::string::npos) {
        return false;
    }
    const size_t separator = reference.find('.');
    if (separator == std::string::npos) {
        physicalName = reference;
        return validMetadataObjectName(physicalName);
    }
    if (separator == 0 || separator + 1 >= reference.size() ||
        reference.find('.', separator + 1) != std::string::npos) {
        return false;
    }
    const std::string schema = reference.substr(0, separator);
    const std::string name = reference.substr(separator + 1);
    if (!validMetadataObjectName(schema) ||
        !validMetadataObjectName(name)) {
        return false;
    }
    physicalName = schema == "public" ? name : schema + "__" + name;
    return validMetadataObjectName(physicalName);
}

DBStatus resolveCollationReference(const StorageEngine& engine,
                                   const std::string& dbname,
                                   const std::string& reference,
                                   ResolvedCollation& resolved,
                                   std::string* error = nullptr) {
    resolved = {};
    auto reject = [&](DBStatus status, const std::string& message) {
        if (error) *error = message;
        return status;
    };

    if (reference.empty()) return DBStatus::OK;
    if (collation::isValid(reference)) {
        resolved.comparisonName = collation::normalizeName(reference);
        resolved.isBinary = collation::isBinary(reference);
        return DBStatus::OK;
    }

    std::string physicalName;
    if (!physicalCollationReference(reference, physicalName)) {
        return reject(DBStatus::INVALID_VALUE,
                      "invalid collation name: " + reference);
    }
    std::vector<StoredCollation> collations;
    if (!loadStoredCollations(
            engine.dbPath(dbname) / ".collations", collations)) {
        return reject(DBStatus::CORRUPTED_DATA,
                      "could not read collation metadata");
    }
    const auto found = std::find_if(
        collations.begin(), collations.end(),
        [&](const StoredCollation& candidate) {
            return candidate.name == physicalName;
        });
    if (found == collations.end()) {
        return reject(DBStatus::INVALID_VALUE,
                      "collation does not exist: " + reference);
    }

    std::string provider = found->provider;
    std::transform(provider.begin(), provider.end(), provider.begin(),
                   [](unsigned char byte) {
                       return static_cast<char>(std::tolower(byte));
                   });
    if (provider != "libc") {
        return reject(DBStatus::INVALID_VALUE,
                      "unsupported collation provider for " + reference);
    }

    const std::string locale = found->locale.empty() ? "C" : found->locale;
    const std::string normalizedLocale = collation::normalizeName(locale);
    if (collation::isValid(locale) && normalizedLocale != "en_us.utf8") {
        resolved.comparisonName = normalizedLocale;
        resolved.isBinary = collation::isBinary(locale);
        return DBStatus::OK;
    }
    if (!collation::isLocaleAvailable(locale)) {
        return reject(DBStatus::INVALID_VALUE,
                      "collation locale is unavailable: " + locale);
    }
    resolved.comparisonName = locale;
    resolved.usesSystemLocale = true;
    resolved.isBinary = false;
    return DBStatus::OK;
}

DBStatus resolveTableCollations(const StorageEngine& engine,
                                const std::string& dbname,
                                TableSchema& table,
                                std::string* error = nullptr) {
    for (size_t columnIndex = 0; columnIndex < table.len; ++columnIndex) {
        Column& column = table.cols[columnIndex];
        column.resolvedCollation.clear();
        column.resolvedCollationUsesLocale = false;
        column.resolvedCollationIsBinary = true;
        if (column.collation.empty()) continue;

        ResolvedCollation resolved;
        const DBStatus status = resolveCollationReference(
            engine, dbname, column.collation, resolved, error);
        if (status != DBStatus::OK) return status;
        column.resolvedCollation = std::move(resolved.comparisonName);
        column.resolvedCollationUsesLocale = resolved.usesSystemLocale;
        column.resolvedCollationIsBinary = resolved.isBinary;
    }
    return DBStatus::OK;
}

int compareTextValues(const Column& column, const std::string& left,
                      const std::string& right) {
    if (column.collation.empty()) return left.compare(right);
    const std::string& effective = column.resolvedCollation.empty()
        ? column.collation : column.resolvedCollation;
    if (column.resolvedCollationUsesLocale) {
        return collation::compareLocale(left, right, effective);
    }
    return collation::compare(left, right, effective);
}

bool columnUsesBinaryCollation(const Column& column) {
    if (column.collation.empty()) return true;
    if (!column.resolvedCollation.empty()) {
        return column.resolvedCollationIsBinary;
    }
    // An unresolved custom name must never enable a binary physical index.
    return collation::isValid(column.collation) &&
           collation::isBinary(column.collation);
}

// Physical B-tree/hash keys are byte ordered, but SQL uniqueness follows the
// column's equality semantics.  Keep the fast canonical-key comparison for
// binary columns and use the resolved collation for non-binary text columns.
bool constraintColumnValuesEqual(const Column& column,
                                 const std::string& left,
                                 const std::string& right) {
    if (!columnUsesBinaryCollation(column)) {
        return compareTextValues(column, left, right) == 0;
    }
    return canonicalColumnKeyValue(column, left) ==
           canonicalColumnKeyValue(column, right);
}

bool constraintKeyValuesEqual(const TableSchema& table,
                              const std::vector<size_t>& columns,
                              const std::vector<std::string>& left,
                              const std::vector<std::string>& right) {
    if (left.size() != columns.size() || right.size() != columns.size()) {
        return false;
    }
    for (size_t valueIndex = 0; valueIndex < columns.size(); ++valueIndex) {
        const size_t columnIndex = columns[valueIndex];
        if (columnIndex >= table.len ||
            !constraintColumnValuesEqual(
                table.cols[columnIndex], left[valueIndex],
                right[valueIndex])) {
            return false;
        }
    }
    return true;
}

bool constraintNeedsCollationScan(const TableSchema& table,
                                  const std::vector<size_t>& columns) {
    return std::any_of(
        columns.begin(), columns.end(), [&](size_t columnIndex) {
            return columnIndex >= table.len ||
                   !columnUsesBinaryCollation(table.cols[columnIndex]);
        });
}

} // namespace

DBStatus StorageEngine::createCollation(const std::string& dbname,
                                        const std::string& collationName,
                                        const std::string& provider,
                                        const std::string& locale) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    const StoredCollation requested{collationName, provider, locale};
    if (!validStoredCollation(requested)) return DBStatus::INVALID_ARGUMENT;
    // Built-ins are resolved before database-local entries.  Reject a public
    // definition that could be persisted successfully but never referenced.
    if (collation::isValid(collationName)) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    const auto path = dbPath(dbname) / ".collations";
    std::vector<StoredCollation> collations;
    if (!loadStoredCollations(path, collations)) return DBStatus::IO_ERROR;
    for (const auto& existing : collations) {
        if (existing.name == collationName) {
            return DBStatus::TABLE_ALREADY_EXISTS;
        }
    }
    collations.push_back(requested);
    return index_file::writeAtomically(
               path, serializeStoredCollations(collations))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::createView(const std::string& dbname,
                                    const std::string& viewname,
                                    const std::string& sql) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(viewname)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto vdir = viewsDir(dbname);
    if (!ensureMetadataDirectory(vdir)) return DBStatus::IO_ERROR;
    if (std::filesystem::exists(viewPath(dbname, viewname))) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    return persistMetadata(viewPath(dbname, viewname), sql);
}

DBStatus StorageEngine::dropView(const std::string& dbname,
                                  const std::string& viewname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(viewname)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = viewPath(dbname, viewname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::error_code error;
    if (!std::filesystem::remove(path, error) || error) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

DBStatus StorageEngine::dropCollation(const std::string& dbname,
                                      const std::string& collationName) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(collationName)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    const auto path = dbPath(dbname) / ".collations";
    std::error_code pathError;
    const bool exists = std::filesystem::exists(path, pathError);
    if (pathError) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::TABLE_NOT_FOUND;

    std::vector<StoredCollation> collations;
    if (!loadStoredCollations(path, collations)) return DBStatus::IO_ERROR;
    if (std::none_of(
            collations.begin(), collations.end(),
            [&](const StoredCollation& collation) {
                return collation.name == collationName;
            })) {
        return DBStatus::TABLE_NOT_FOUND;
    }

    // A table schema persists the logical collation reference.  Removing its
    // definition would make subsequent schema loads either change semantics
    // or fail.  Scan the authoritative schema files before touching the
    // sidecar; do not trust tlist.lst alone because an incomplete catalog
    // update must not hide a dependency.
    std::error_code directoryError;
    std::filesystem::directory_iterator entry(
        dbPath(dbname), directoryError);
    const std::filesystem::directory_iterator end;
    if (directoryError) return DBStatus::IO_ERROR;
    for (; entry != end; entry.increment(directoryError)) {
        if (directoryError) return DBStatus::IO_ERROR;
        const std::string filename = entry->path().filename().string();
        constexpr std::string_view schemaSuffix = ".stc";
        if (filename.size() <= schemaSuffix.size() ||
            filename.compare(filename.size() - schemaSuffix.size(),
                             schemaSuffix.size(), schemaSuffix) != 0) {
            continue;
        }
        std::error_code typeError;
        if (!entry->is_regular_file(typeError)) {
            if (typeError) return DBStatus::IO_ERROR;
            return DBStatus::CORRUPTED_DATA;
        }
        const std::string tableName = filename.substr(
            0, filename.size() - schemaSuffix.size());
        if (!validStoredIdentifier(tableName, MAX_TABLE_NAME_LEN)) {
            return DBStatus::CORRUPTED_DATA;
        }
        std::ifstream schemaInput(entry->path(), std::ios::binary);
        if (!schemaInput) return DBStatus::IO_ERROR;
        const TableSchema table = readSchema(schemaInput, tableName);
        // readSchema preserves the requested name on a successful zero-column
        // schema and returns a value-initialized object on malformed input.
        if (table.tablename != tableName) return DBStatus::CORRUPTED_DATA;
        for (size_t columnIndex = 0; columnIndex < table.len; ++columnIndex) {
            const std::string& reference = table.cols[columnIndex].collation;
            if (reference.empty()) continue;
            std::string physicalReference;
            if (!physicalCollationReference(
                    reference, physicalReference)) {
                return DBStatus::CORRUPTED_DATA;
            }
            if (physicalReference == collationName) {
                return DBStatus::INVALID_VALUE;
            }
        }
    }
    if (directoryError) return DBStatus::IO_ERROR;

    std::vector<StoredCollation> retained;
    retained.reserve(collations.size());
    bool found = false;
    for (auto& collation : collations) {
        if (collation.name == collationName) {
            found = true;
        } else {
            retained.push_back(std::move(collation));
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    if (retained.empty()) {
        std::error_code removeError;
        if (!std::filesystem::remove(path, removeError) || removeError ||
            !syncDirectoryDurably(path.parent_path())) {
            return DBStatus::IO_ERROR;
        }
        return DBStatus::OK;
    }
    return index_file::writeAtomically(
               path, serializeStoredCollations(retained))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

std::vector<std::string> StorageEngine::getCollationNames(
    const std::string& dbname) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<std::string> result;
    if (!databaseExists(dbname)) return result;
    const auto path = dbPath(dbname) / ".collations";
    std::vector<StoredCollation> collations;
    if (!loadStoredCollations(path, collations)) return result;
    for (const auto& collation : collations) result.push_back(collation.name);
    return result;
}

bool StorageEngine::viewExists(const std::string& dbname,
                               const std::string& viewname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(viewname)) return false;
    std::error_code error;
    const bool regular =
        std::filesystem::is_regular_file(viewPath(dbname, viewname), error);
    return regular && !error;
}

std::string StorageEngine::getViewSQL(const std::string& dbname,
                                       const std::string& viewname) const {
    if (!viewExists(dbname, viewname)) return "";
    auto path = viewPath(dbname, viewname);
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string sql((std::istreambuf_iterator<char>(ifs)),
                     std::istreambuf_iterator<char>());
    return sql;
}

std::string StorageEngine::getViewBaseTable(const std::string& dbname,
                                             const std::string& viewname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(viewname)) return "";
    auto path = viewPath(dbname, viewname);
    if (!std::filesystem::exists(path)) return "";
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.substr(0, 11) == "BASE_TABLE:") {
            return line.substr(11);
        }
    }
    return "";
}

std::string StorageEngine::getViewCheckOption(const std::string& dbname,
                                               const std::string& viewname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(viewname)) return "";
    auto path = viewPath(dbname, viewname);
    if (!std::filesystem::exists(path)) return "";
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.substr(0, 17) == "WITH_CHECK_OPTION") {
            size_t colon = line.find(':');
            if (colon != std::string::npos) return line.substr(colon + 1);
            return "CASCADED";
        }
    }
    return "";
}

// Forward declaration for validateViewCheckOption
static std::string buildRowBuffer(const TableSchema& tbl,
                                  const std::map<std::string, std::string>& values,
                                  uint64_t creatorTxnId,
                                  const std::set<size_t>* explicitNullColumns = nullptr);

// ========================================================================
// PostgreSQL HeapTupleHeader row format
// ========================================================================

static bool usesHeapTupleHeader(uint32_t formatVersion) {
    return formatVersion == DATA_FILE_FORMAT_VERSION;
}

static size_t heapTupleHeaderSize(const TableSchema& tbl) {
    return computeHeapHeaderSize(static_cast<int>(tbl.len));
}

static size_t rowHeaderSize(const TableSchema& tbl) {
    return heapTupleHeaderSize(tbl);
}

static size_t rowHeaderSize(uint32_t formatVersion, size_t natts) {
    (void)formatVersion;
    return computeHeapHeaderSize(static_cast<int>(natts));
}

static size_t dataOffset(const TableSchema& tbl) {
    return rowHeaderSize(tbl);
}

static size_t dataOffset(uint32_t formatVersion, size_t natts) {
    return rowHeaderSize(formatVersion, natts);
}

// Build a PostgreSQL HeapTupleHeader
static std::string buildHeapTupleHeader(const TableSchema& tbl,
                                        uint64_t creatorTxnId,
                                        bool hasNull,
                                        bool hasVarWidth) {
    std::string header;
    header.resize(heapTupleHeaderSize(tbl), '\0');
    auto* htup = castHeapHeader(header.data());
    initHeapTupleHeader(htup,
                        static_cast<uint32_t>(creatorTxnId),
                        static_cast<uint16_t>(tbl.len),
                        hasNull,
                        hasVarWidth);
    return header;
}

// Clear/set xmin on a mutable row buffer during rollback restoration.
static void setRowXmin(char* rowBuffer, size_t len, uint32_t formatVersion, uint64_t xmin) {
    if (len == 0) return;
    if (!usesHeapTupleHeader(formatVersion) || len < sizeof(HeapTupleHeaderData)) return;
    auto* htup = castHeapHeader(rowBuffer);
    htup->t_fields.t_xmin = static_cast<uint32_t>(xmin);
}

// Set xmax on a mutable row buffer
static void setRowXmax(char* rowBuffer, size_t len, uint32_t formatVersion, uint64_t xmax) {
    if (len == 0) return;
    if (!usesHeapTupleHeader(formatVersion) || len < sizeof(HeapTupleHeaderData)) return;
    auto* htup = castHeapHeader(rowBuffer);
    htup->t_fields.t_xmax = static_cast<uint32_t>(xmax);
}

// Set ctid on a mutable row buffer
static void setRowCtid(char* rowBuffer, size_t len, uint32_t formatVersion, const ItemPointer& ctid) {
    if (len == 0) return;
    if (!usesHeapTupleHeader(formatVersion) || len < sizeof(HeapTupleHeaderData)) return;
    setCtid(castHeapHeader(rowBuffer), ctid);
}

// Strip the MVCC header and return the payload data
static std::string stripRowHeader(const char* rowBuffer, size_t len, uint32_t formatVersion, size_t natts) {
    size_t hdrLen = rowHeaderSize(formatVersion, natts);
    if (len <= hdrLen) return {};
    if (!usesHeapTupleHeader(formatVersion) || len < sizeof(HeapTupleHeaderData)) return {};
    auto* htup = castHeapHeader(rowBuffer);
    size_t off = htup->t_hoff;
    if (off == 0 || off > len) off = hdrLen;
    return std::string(rowBuffer + off, len - off);
}

static std::string stripRowHeader(const std::string& rowBuffer, uint32_t formatVersion, size_t natts) {
    return stripRowHeader(rowBuffer.data(), rowBuffer.size(), formatVersion, natts);
}

// Replace the payload data of a full row while preserving its MVCC header.
// Used by transaction rollback to restore old column values.
static std::string replaceRowData(const std::string& fullRow,
                                  const std::string& newData,
                                  uint32_t formatVersion,
                                  size_t natts) {
    if (fullRow.empty()) return newData;
    size_t hdrLen = rowHeaderSize(formatVersion, natts);
    if (fullRow.size() < hdrLen) return newData;
    if (!usesHeapTupleHeader(formatVersion) || fullRow.size() < sizeof(HeapTupleHeaderData)) return newData;
    const auto* htup = castHeapHeader(fullRow.data());
    hdrLen = htup->t_hoff;
    std::string result;
    result.reserve(hdrLen + newData.size());
    result.append(fullRow.data(), hdrLen);
    result.append(newData);
    return result;
}

// ========================================================================
// WITH CHECK OPTION helpers
// ========================================================================

static std::string extractViewWhereClause(const std::string& selectSql) {
    std::string lower = selectSql;
    std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
    size_t wherePos = lower.find(" where ");
    if (wherePos == std::string::npos) return "";
    size_t clauseStart = wherePos + 7;
    static const char* endMarkers[] = {" order by ", " group by ", " limit ", " having ", " union ", " intersect ", " except "};
    size_t clauseEnd = selectSql.size();
    for (const char* marker : endMarkers) {
        size_t pos = lower.find(marker, clauseStart);
        if (pos != std::string::npos && pos < clauseEnd) clauseEnd = pos;
    }
    return trim(selectSql.substr(clauseStart, clauseEnd - clauseStart));
}

static std::string normalizeViewCondStr(std::string s) {
    static const char* ops[] = {">=", "<=", "!=", "<>", ">", "<", "="};
    for (const char* op : ops) {
        size_t len = std::strlen(op);
        size_t pos = 0;
        while ((pos = s.find(op, pos)) != std::string::npos) {
            size_t before = pos;
            while (before > 0 && std::isspace(static_cast<unsigned char>(s[before - 1]))) before--;
            size_t after = pos + len;
            while (after < s.size() && std::isspace(static_cast<unsigned char>(s[after]))) after++;
            if (before != pos || after != pos + len) {
                s = s.substr(0, before) + op + s.substr(after);
                pos = before + len;
            } else {
                pos += len;
            }
        }
    }
    struct KW { const char* w; size_t l; const char* r; };
    static const KW kws[] = {
        {"not like", 9, "notlike"}, {"not between", 12, "notbetween"},
        {"not ilike", 9, "notilike"}, {"ilike", 5, "ilike"},
        {"like", 4, "like"}, {"regexp", 6, "regexp"}, {"contains", 8, "contains"},
        {"overlaps", 8, "overlaps"}, {"is not null", 11, "isnotnull"}, {"is null", 7, "isnull"}
    };
    for (const auto& kw : kws) {
        size_t pos = 0;
        while ((pos = s.find(kw.w, pos)) != std::string::npos) {
            size_t before = pos;
            while (before > 0 && std::isspace(static_cast<unsigned char>(s[before - 1]))) before--;
            size_t after = pos + kw.l;
            while (after < s.size() && std::isspace(static_cast<unsigned char>(s[after]))) after++;
            if (before != pos || after != pos + kw.l) {
                s = s.substr(0, before) + kw.r + s.substr(after);
                pos = before + std::strlen(kw.r);
            } else {
                pos += kw.l;
            }
        }
    }
    // overlaps parenthesis form
    size_t pos = 0;
    while ((pos = s.find("overlaps", pos)) != std::string::npos) {
        size_t leftStart = pos;
        while (leftStart > 0 && s[leftStart - 1] != '(') leftStart--;
        if (leftStart == 0 || s[leftStart - 1] != '(') { pos += 8; continue; }
        leftStart--;
        size_t rightEnd = pos + 8;
        while (rightEnd < s.size() && s[rightEnd] != ')') rightEnd++;
        if (rightEnd >= s.size()) { pos += 8; continue; }
        rightEnd++;
        std::string expr = s.substr(leftStart, rightEnd - leftStart);
        std::string inner = expr.substr(1, expr.size() - 2);
        size_t opPos = inner.find(")overlaps(");
        if (opPos != std::string::npos) {
            std::string repl = "overlaps:" + inner.substr(0, opPos) + "," + inner.substr(opPos + 10);
            s = s.substr(0, leftStart) + repl + s.substr(rightEnd);
            pos = leftStart + repl.size();
        } else { pos += 8; }
    }
    return s;
}

static std::string modifyViewLogic(const std::string& logic) {
    if (logic == "(" || logic == ")" || logic == "and" || logic == "or") return logic;
    size_t p = logic.find("not like");
    if (p != std::string::npos)
        return "notlike" + logic.substr(0, p) + " " + logic.substr(p + 9);
    p = logic.find("ilike");
    if (p != std::string::npos) {
        std::string before = logic.substr(0, p);
        std::string after = logic.substr(p + 5);
        return "ilike" + before + " " + after;
    }
    p = logic.find("like");
    if (p != std::string::npos)
        return "like" + logic.substr(0, p) + " " + logic.substr(p + 4);
    p = logic.find("regexp");
    if (p != std::string::npos)
        return "regexp" + logic.substr(0, p) + " " + logic.substr(p + 6);
    p = logic.find("contains");
    if (p != std::string::npos)
        return "contains" + logic.substr(0, p) + " " + logic.substr(p + 8);
    p = logic.find("overlaps");
    if (p != std::string::npos)
        return "overlaps" + logic.substr(0, p) + " " + logic.substr(p + 8);
    p = logic.find("isnotnull");
    if (p != std::string::npos && p + 9 == logic.size())
        return "isnotnull " + logic.substr(0, p);
    p = logic.find("isnull");
    if (p != std::string::npos && p + 6 == logic.size())
        return "isnull " + logic.substr(0, p);
    size_t opStart = std::string::npos, opLen = 0;
    for (size_t i = 0; i < logic.size(); ++i) {
        if (logic[i] == '>' || logic[i] == '<' || logic[i] == '=' || logic[i] == '!') {
            opStart = i; opLen = 1;
            if (i + 1 < logic.size() && (logic[i + 1] == '=' || logic[i + 1] == '>')) {
                if ((logic[i] == '<' && logic[i + 1] == '=') ||
                    (logic[i] == '>' && logic[i + 1] == '=') ||
                    (logic[i] == '!' && logic[i + 1] == '=') ||
                    (logic[i] == '<' && logic[i + 1] == '>')) opLen = 2;
            }
            break;
        }
    }
    if (opStart == std::string::npos) return "";
    std::string op = logic.substr(opStart, opLen);
    std::string before = logic.substr(0, opStart);
    std::string after = logic.substr(opStart + opLen);
    if (after.size() >= 2 && after.front() == '\'' && after.back() == '\'')
        after = after.substr(1, after.size() - 2);
    return op + before + " " + after;
}

static std::vector<std::string> tokenizeViewCond(const std::string& s) {
    std::vector<std::string> tokens;
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
        if (i >= s.size()) break;
        if (s[i] == '(' || s[i] == ')') {
            tokens.emplace_back(1, s[i]);
            ++i; continue;
        }
        size_t start = i;
        while (i < s.size() && !std::isspace(static_cast<unsigned char>(s[i])) && s[i] != '(' && s[i] != ')') ++i;
        tokens.push_back(s.substr(start, i - start));
    }
    return tokens;
}

// Simple DNF breakdown (AND-of-groups for OR semantics)
static std::vector<std::vector<std::string>> breakDownViewConds(const std::vector<std::string>& tokens) {
    if (tokens.size() == 3 && tokens[0] == "(" && tokens[2] == ")")
        return {{tokens[1]}};
    struct Frame { std::vector<std::vector<std::string>> groups; };
    std::vector<Frame> stack;
    stack.push_back(Frame());
    std::vector<std::string> operandStack;
    auto applyAnd = [&](const std::string& right) {
        Frame& cur = stack.back();
        if (!operandStack.empty()) {
            std::string left = operandStack.back(); operandStack.pop_back();
            if (cur.groups.empty()) cur.groups.push_back({left, right});
            else for (auto& g : cur.groups) g.push_back(right);
        } else {
            if (cur.groups.empty()) cur.groups.push_back({right});
            else for (auto& g : cur.groups) g.push_back(right);
        }
    };
    auto applyOr = [&](const std::string& right) {
        Frame& cur = stack.back();
        if (!operandStack.empty()) {
            std::string left = operandStack.back(); operandStack.pop_back();
            if (cur.groups.empty()) { cur.groups.push_back({left}); cur.groups.push_back({right}); }
            else {
                auto old = cur.groups;
                cur.groups.clear();
                for (auto& g : old) {
                    auto g2 = g;
                    g2.push_back(right);
                    cur.groups.push_back(std::move(g));
                    cur.groups.push_back(std::move(g2));
                }
            }
        } else {
            cur.groups.push_back({right});
        }
    };
    auto flushOp = [&](const std::string& op, const std::string& right) {
        if (op == "and") applyAnd(right);
        else if (op == "or") applyOr(right);
    };
    std::string pendingOp;
    for (size_t i = 0; i < tokens.size(); ++i) {
        const std::string& tok = tokens[i];
        if (tok == "(") {
            stack.push_back(Frame());
            pendingOp.clear();
        } else if (tok == ")") {
            if (!operandStack.empty()) {
                std::string last = operandStack.back(); operandStack.pop_back();
                if (!pendingOp.empty()) { flushOp(pendingOp, last); pendingOp.clear(); }
                else if (!stack.back().groups.empty()) {
                    for (auto& g : stack.back().groups) g.push_back(last);
                } else {
                    stack.back().groups.push_back({last});
                }
            }
            auto curGroups = std::move(stack.back().groups);
            stack.pop_back();
            if (!curGroups.empty()) {
                if (stack.back().groups.empty()) stack.back().groups = std::move(curGroups);
                else {
                    auto old = stack.back().groups;
                    stack.back().groups.clear();
                    for (auto& g1 : old)
                        for (auto& g2 : curGroups) {
                            auto merged = g1;
                            merged.insert(merged.end(), g2.begin(), g2.end());
                            stack.back().groups.push_back(std::move(merged));
                        }
                }
            }
        } else if (tok == "and" || tok == "or") {
            if (!operandStack.empty()) {
                std::string last = operandStack.back(); operandStack.pop_back();
                if (!pendingOp.empty()) flushOp(pendingOp, last);
                else operandStack.push_back(last);
            }
            pendingOp = tok;
        } else {
            operandStack.push_back(tok);
        }
    }
    if (!operandStack.empty()) {
        std::string last = operandStack.back(); operandStack.pop_back();
        if (!pendingOp.empty()) flushOp(pendingOp, last);
        else if (!stack.back().groups.empty()) {
            for (auto& g : stack.back().groups) g.push_back(last);
        } else {
            stack.back().groups.push_back({last});
        }
    }
    return stack.back().groups;
}

bool StorageEngine::validateViewCheckOption(
    const std::string& dbname,
    const std::string& viewname,
    const std::map<std::string, std::string>& colValues) const {

    std::string checkOpt = getViewCheckOption(dbname, viewname);
    if (checkOpt.empty()) return true;

    std::string baseTable = getViewBaseTable(dbname, viewname);
    if (baseTable.empty()) return true;

    TableSchema tbl = getTableSchema(dbname, baseTable);

    // Build simulated row buffer and strip MVCC header
    std::string rowBuffer = buildRowBuffer(tbl, colValues, 0);
    std::string dataOnly = stripRowHeader(rowBuffer, tbl.formatVersion, tbl.len);

    // Get view SQL and extract WHERE clause
    std::string viewSql = getViewSQL(dbname, viewname);
    std::string selectSql;
    {
        std::stringstream ss(viewSql);
        std::getline(ss, selectSql);
    }
    std::string whereClause = extractViewWhereClause(selectSql);
    if (whereClause.empty()) return true;

    // Parse WHERE conditions into DNF groups
    std::string normWhere = normalizeViewCondStr(whereClause);
    auto tokens = tokenizeViewCond(normWhere);
    auto groups = breakDownViewConds(tokens);

    // For each DNF group (OR branch), all conditions in the group must be satisfied
    // If ANY group is fully satisfied, the WHERE clause is satisfied
    for (const auto& group : groups) {
        std::vector<std::string> condStrs;
        for (const auto& tok : group) {
            if (tok == "and" || tok == "or" || tok == "(" || tok == ")") continue;
            std::string mc = modifyViewLogic(tok);
            if (!mc.empty()) condStrs.push_back(mc);
        }
        if (condStrs.empty()) continue;
        auto conds = parseConditions(condStrs);
        bool groupSatisfied = true;
        for (const auto& c : conds) {
            if (!evalConditionOnRow(c, dataOnly, tbl)) {
                groupSatisfied = false;
                break;
            }
        }
        if (groupSatisfied) return true;
    }
    return false;
}

std::vector<std::string> StorageEngine::getViewNames(const std::string& dbname) const {
    std::vector<std::string> result;
    if (!databaseExists(dbname)) return result;
    auto vdir = viewsDir(dbname);
    if (!std::filesystem::exists(vdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(vdir)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 5 && name.substr(name.size() - 5) == ".view") {
                result.push_back(name.substr(0, name.size() - 5));
            }
        }
    }
    return result;
}

// ========================================================================
// Materialized views
// ========================================================================

static std::filesystem::path materializedViewPath(const std::string& dbname,
                                                   const std::string& viewname,
                                                   const dbms::StorageEngine* engine) {
    return engine->viewsDir(dbname) / (viewname + ".mview");
}

bool StorageEngine::isMaterializedView(const std::string& dbname,
                                       const std::string& viewname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(viewname)) {
        return false;
    }
    std::error_code error;
    const bool regular = std::filesystem::is_regular_file(
        materializedViewPath(dbname, viewname, this), error);
    return regular && !error;
}

std::string StorageEngine::getMaterializedViewSQL(const std::string& dbname,
                                                   const std::string& viewname) const {
    if (!isMaterializedView(dbname, viewname)) return "";
    auto path = materializedViewPath(dbname, viewname, this);
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string sql((std::istreambuf_iterator<char>(ifs)),
                     std::istreambuf_iterator<char>());
    return sql;
}

std::vector<std::string> StorageEngine::getMaterializedViewNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto vdir = viewsDir(dbname);
    if (!std::filesystem::exists(vdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(vdir)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 6 && name.substr(name.size() - 6) == ".mview") {
                result.push_back(name.substr(0, name.size() - 6));
            }
        }
    }
    return result;
}

DBStatus StorageEngine::dropMaterializedView(const std::string& dbname,
                                              const std::string& viewname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    try {
        // The DDL executor wraps both removals in a physical snapshot. Return
        // the first failure so it can restore that snapshot instead of
        // committing a materialized view with only one half removed.
        const std::string backingTable = materializedViewPrefix(viewname);
        if (tableExists(dbname, backingTable)) {
            const DBStatus status = dropTable(dbname, backingTable);
            if (status != DBStatus::OK) return status;
        }

        const auto path = materializedViewPath(dbname, viewname, this);
        std::error_code error;
        const bool exists = std::filesystem::exists(path, error);
        if (error) return DBStatus::IO_ERROR;
        if (exists) {
            const bool removed = std::filesystem::remove(path, error);
            if (!removed || error) return DBStatus::IO_ERROR;
        }
    } catch (const std::filesystem::filesystem_error&) {
        return DBStatus::IO_ERROR;
    }
    return DBStatus::OK;
}

// ========================================================================
// Stored procedures
// ========================================================================

static std::filesystem::path proceduresDir(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".procs";
}

static std::filesystem::path procedurePath(const std::string& dbname,
                                           const std::string& procname) {
    return std::filesystem::path(dbname) / ".procs" / (procname + ".proc");
}

DBStatus StorageEngine::createProcedure(const std::string& dbname,
                                         const std::string& procname,
                                         const std::vector<ProcParam>& params,
                                         const std::vector<std::string>& statements) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(procname)) return DBStatus::INVALID_ARGUMENT;
    auto pdir = proceduresDir(dbname);
    if (!ensureMetadataDirectory(pdir)) return DBStatus::IO_ERROR;
    if (std::filesystem::exists(procedurePath(dbname, procname))) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ostringstream serialized;
    // Write params metadata line first
    if (!params.empty()) {
        serialized << "PARAMS:";
        for (size_t i = 0; i < params.size(); ++i) {
            if (i > 0) serialized << ',';
            serialized << params[i].name << ':' << params[i].mode << ':' << params[i].type;
        }
        serialized << '\n';
    }
    for (const auto& stmt : statements) {
        serialized << stmt << '\n';
    }
    return persistMetadata(procedurePath(dbname, procname), serialized.str());
}

DBStatus StorageEngine::dropProcedure(const std::string& dbname,
                                       const std::string& procname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(procname)) return DBStatus::INVALID_ARGUMENT;
    auto path = procedurePath(dbname, procname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::error_code error;
    if (!std::filesystem::remove(path, error) || error) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

bool StorageEngine::procedureExists(const std::string& dbname,
                                    const std::string& procname) const {
    return databaseExists(dbname) && validMetadataObjectName(procname) &&
           std::filesystem::exists(procedurePath(dbname, procname));
}

std::vector<std::string> StorageEngine::getProcedureStatements(
    const std::string& dbname, const std::string& procname) const {
    std::vector<std::string> result;
    if (!databaseExists(dbname) || !validMetadataObjectName(procname)) return result;
    auto path = procedurePath(dbname, procname);
    std::ifstream ifs(path);
    if (!ifs) return result;
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        if (line.substr(0, 7) == "PARAMS:") continue;
        result.push_back(line);
    }
    return result;
}

std::vector<StorageEngine::ProcParam> StorageEngine::getProcedureParams(
    const std::string& dbname, const std::string& procname) const {
    std::vector<ProcParam> result;
    if (!databaseExists(dbname) || !validMetadataObjectName(procname)) return result;
    auto path = procedurePath(dbname, procname);
    std::ifstream ifs(path);
    if (!ifs) return result;
    std::string line;
    if (std::getline(ifs, line)) {
        if (line.substr(0, 7) == "PARAMS:") {
            std::string rest = line.substr(7);
            size_t p = 0;
            while (p < rest.size()) {
                size_t comma = rest.find(',', p);
                std::string part = rest.substr(p, comma - p);
                if (!part.empty()) {
                    size_t c1 = part.find(':');
                    size_t c2 = part.find(':', c1 + 1);
                    if (c1 != std::string::npos && c2 != std::string::npos) {
                        ProcParam pp;
                        pp.name = part.substr(0, c1);
                        pp.mode = part.substr(c1 + 1, c2 - c1 - 1);
                        pp.type = part.substr(c2 + 1);
                        result.push_back(pp);
                    }
                }
                if (comma == std::string::npos) break;
                p = comma + 1;
            }
        }
    }
    return result;
}

std::vector<std::string> StorageEngine::getProcedureNames(const std::string& dbname) const {
    std::vector<std::string> result;
    if (!databaseExists(dbname)) return result;
    auto pdir = proceduresDir(dbname);
    if (!std::filesystem::exists(pdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(pdir)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 5 && name.substr(name.size() - 5) == ".proc") {
                result.push_back(name.substr(0, name.size() - 5));
            }
        }
    }
    return result;
}

// ========================================================================
// Schema management
// ========================================================================

static std::filesystem::path schemaMarkerPath(const std::string& dbname,
                                              const std::string& schemaname) {
    return std::filesystem::path(dbname) / (".schema_" + schemaname);
}

DBStatus StorageEngine::createSchema(const std::string& dbname,
                                     const std::string& schemaname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (schemaname.empty() || !validStoredIdentifier(schemaname, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = schemaMarkerPath(dbname, schemaname);
    if (std::filesystem::exists(path)) return DBStatus::TABLE_ALREADY_EXISTS;
    return index_file::writeAtomically(path, "") ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::dropSchema(const std::string& dbname,
                                   const std::string& schemaname,
                                   bool cascade) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (schemaname.empty() || !validStoredIdentifier(schemaname, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = schemaMarkerPath(dbname, schemaname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    if (cascade) {
        std::string prefix = schemaname + "__";
        auto dbPath = std::filesystem::path(dbname);
        std::vector<std::string> tablesToDrop;
        for (const auto& entry : std::filesystem::directory_iterator(dbPath)) {
            if (!entry.is_regular_file()) continue;
            std::string name = entry.path().filename().string();
            if (name.size() > 3 && name.substr(name.size() - 3) == ".dt") {
                std::string tname = name.substr(0, name.size() - 3);
                if (tname.size() > prefix.size() && tname.substr(0, prefix.size()) == prefix) {
                    tablesToDrop.push_back(std::move(tname));
                }
            }
        }
        for (const auto& tname : tablesToDrop) {
            if (dropTable(dbname, tname) != DBStatus::OK) {
                return DBStatus::INVALID_VALUE;
            }
        }
    }
    std::error_code ec;
    std::filesystem::remove(path, ec);
    return ec ? DBStatus::INVALID_VALUE : DBStatus::OK;
}

DBStatus StorageEngine::renameSchema(const std::string& dbname,
                                     const std::string& oldname,
                                     const std::string& newname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (oldname.empty() || newname.empty() ||
        !validStoredIdentifier(oldname, MAX_TABLE_NAME_LEN) ||
        !validStoredIdentifier(newname, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto oldPath = schemaMarkerPath(dbname, oldname);
    auto newPath = schemaMarkerPath(dbname, newname);
    if (!std::filesystem::exists(oldPath)) return DBStatus::TABLE_NOT_FOUND;
    if (std::filesystem::exists(newPath)) return DBStatus::INVALID_VALUE;
    std::filesystem::rename(oldPath, newPath);
    // Rename all tables in the old schema
    std::string oldPrefix = oldname + "__";
    std::string newPrefix = newname + "__";
    auto dbPath = std::filesystem::path(dbname);
    for (const auto& entry : std::filesystem::directory_iterator(dbPath)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > 3 && name.substr(name.size() - 3) == ".dt") {
            std::string tname = name.substr(0, name.size() - 3);
            if (tname.size() > oldPrefix.size() && tname.substr(0, oldPrefix.size()) == oldPrefix) {
                std::string rest = tname.substr(oldPrefix.size());
                std::string newTname = newPrefix + rest;
                // Rename .dt, .stc, .idx files
                for (const char* ext : {".dt", ".stc", ".idx"}) {
                    auto oldFile = dbPath / (tname + ext);
                    auto newFile = dbPath / (newTname + ext);
                    if (std::filesystem::exists(oldFile)) {
                        std::filesystem::rename(oldFile, newFile);
                    }
                }
                // Update tlist.lst
                auto tlistPath = dbPath / "tlist.lst";
                if (std::filesystem::exists(tlistPath)) {
                    std::ifstream ifs(tlistPath);
                    std::vector<std::string> lines;
                    std::string line;
                    while (std::getline(ifs, line)) lines.push_back(line);
                    std::ofstream ofs(tlistPath);
                    for (const auto& l : lines) {
                        if (l == tname) ofs << newTname << '\n';
                        else ofs << l << '\n';
                    }
                }
            }
        }
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableSetSchema(const std::string& dbname,
                                            const std::string& tablename,
                                            const std::string& targetDbname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!databaseExists(targetDbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (tableExists(targetDbname, tablename)) return DBStatus::TABLE_ALREADY_EXISTS;

    auto srcPath = std::filesystem::path(dbname);
    auto dstPath = std::filesystem::path(targetDbname);

    // Move known table files (.dt, .idx, .stc, .seq)
    for (const char* ext : {".dt", ".idx", ".stc", ".seq"}) {
        auto oldFile = srcPath / (tablename + ext);
        auto newFile = dstPath / (tablename + ext);
        if (std::filesystem::exists(oldFile)) {
            std::filesystem::rename(oldFile, newFile);
        }
    }

    // Move index files: {tname}_{col}.{ext}
    for (const auto& entry : std::filesystem::directory_iterator(srcPath)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        // Match patterns like tname_col.fti, tname_col.gin, etc.
        size_t underscore = name.find('_');
        if (underscore != std::string::npos && name.substr(0, underscore) == tablename) {
            std::filesystem::rename(entry.path(), dstPath / name);
        }
    }

    // Also move composite index file if exists
    auto compIdx = srcPath / (tablename + "_composite.idx");
    if (std::filesystem::exists(compIdx)) {
        std::filesystem::rename(compIdx, dstPath / (tablename + "_composite.idx"));
    }

    // Update tlist.lst in source database: remove tablename
    {
        auto srcTlist = srcPath / "tlist.lst";
        if (std::filesystem::exists(srcTlist)) {
            std::ifstream ifs(srcTlist);
            std::vector<std::string> lines;
            std::string line;
            while (std::getline(ifs, line)) lines.push_back(line);
            std::ofstream ofs(srcTlist);
            for (const auto& l : lines) {
                if (l != tablename) ofs << l << '\n';
            }
        }
    }

    // Update tlist.lst in target database: add tablename
    {
        auto dstTlist = dstPath / "tlist.lst";
        std::vector<std::string> lines;
        if (std::filesystem::exists(dstTlist)) {
            std::ifstream ifs(dstTlist);
            std::string line;
            while (std::getline(ifs, line)) lines.push_back(line);
        }
        lines.push_back(tablename);
        std::ofstream ofs(dstTlist);
        for (const auto& l : lines) ofs << l << '\n';
    }

    // Move permissions from source to target database
    {
        auto permPath = dbPath("permissions.dat");
        if (std::filesystem::exists(permPath)) {
            std::ifstream ifs(permPath);
            std::vector<std::string> keepLines;
            std::vector<std::string> moveLines;
            std::string line;
            while (std::getline(ifs, line)) {
                // Format: dbname tablename username permission
                std::stringstream ss(line);
                std::string ldb, ltbl, luser, lperm;
                ss >> ldb >> ltbl >> luser >> lperm;
                if (ldb == dbname && ltbl == tablename) {
                    moveLines.push_back(targetDbname + " " + tablename + " " + luser + " " + lperm);
                } else {
                    keepLines.push_back(line);
                }
            }
            std::ofstream ofs(permPath);
            for (const auto& l : keepLines) ofs << l << '\n';
            std::ofstream ofsAppend(permPath, std::ios::app);
            for (const auto& l : moveLines) ofsAppend << l << '\n';
        }
    }

    return DBStatus::OK;
}

bool StorageEngine::schemaExists(const std::string& dbname,
                                 const std::string& schemaname) const {
    // The public namespace is implicit for databases initialized by older
    // bootstrap paths (including a manually prepared test/server directory).
    // New databases persist the marker as well, but validation must preserve
    // the PostgreSQL invariant that public always exists.
    if (schemaname == "public" && databaseExists(dbname)) return true;
    if (schemaname.empty() || !validStoredIdentifier(schemaname, MAX_TABLE_NAME_LEN)) {
        return false;
    }
    return std::filesystem::exists(schemaMarkerPath(dbname, schemaname));
}

std::vector<std::string> StorageEngine::getSchemaNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto dbPath = std::filesystem::path(dbname);
    if (!std::filesystem::exists(dbPath)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(dbPath)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 8 && name.substr(0, 8) == ".schema_") {
                result.push_back(name.substr(8));
            }
        }
    }
    return result;
}

std::vector<std::string> StorageEngine::getTablesInSchema(
    const std::string& dbname, const std::string& schemaname) const {
    std::vector<std::string> result;
    std::string prefix = schemaname + "__";
    auto dbPath = std::filesystem::path(dbname);
    if (!std::filesystem::exists(dbPath)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(dbPath)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 3 && name.substr(name.size() - 3) == ".dt") {
                std::string tname = name.substr(0, name.size() - 3);
                if (tname.size() > prefix.size() &&
                    tname.substr(0, prefix.size()) == prefix) {
                    result.push_back(tname.substr(prefix.size()));
                }
            }
        }
    }
    return result;
}

// ========================================================================
// User-defined functions (simple expression-based)
// ========================================================================

static std::filesystem::path udfDir(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".funcs";
}

static std::filesystem::path udfPath(const std::string& dbname,
                                     const std::string& funcname) {
    return std::filesystem::path(dbname) / ".funcs" / (funcname + ".func");
}

DBStatus StorageEngine::createUDF(const std::string& dbname,
                                   const std::string& funcname,
                                   const std::string& param,
                                   const std::string& expression,
                                   char provolatile,
                                   const std::string& language) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(funcname)) return DBStatus::INVALID_ARGUMENT;
    auto fdir = udfDir(dbname);
    if (!ensureMetadataDirectory(fdir)) return DBStatus::IO_ERROR;
    if (std::filesystem::exists(udfPath(dbname, funcname))) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ostringstream serialized;
    serialized << param << "\n" << expression << "\n" << provolatile << "\n"
               << (language.empty() ? "sql" : language) << "\n";
    return persistMetadata(udfPath(dbname, funcname), serialized.str());
}

DBStatus StorageEngine::createUDF(const std::string& dbname,
                                   const std::string& funcname,
                                   const std::vector<std::string>& params,
                                   const std::vector<std::string>& types,
                                   const std::string& expression,
                                   char provolatile,
                                   const std::string& language) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(funcname)) return DBStatus::INVALID_ARGUMENT;
    auto fdir = udfDir(dbname);
    if (!ensureMetadataDirectory(fdir)) return DBStatus::IO_ERROR;
    if (std::filesystem::exists(udfPath(dbname, funcname))) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ostringstream serialized;
    serialized << "PARAMS:";
    for (size_t i = 0; i < params.size(); ++i) {
        if (i > 0) serialized << ',';
        serialized << params[i] << ':' << (i < types.size() ? types[i] : "");
    }
    serialized << "\n" << expression << "\n" << provolatile << "\n";
    return persistMetadata(udfPath(dbname, funcname), serialized.str());
}

DBStatus StorageEngine::dropUDF(const std::string& dbname,
                                 const std::string& funcname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(funcname)) return DBStatus::INVALID_ARGUMENT;
    auto path = udfPath(dbname, funcname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::error_code error;
    if (!std::filesystem::remove(path, error) || error) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

bool StorageEngine::udfExists(const std::string& dbname,
                              const std::string& funcname) const {
    return databaseExists(dbname) && validMetadataObjectName(funcname) &&
           std::filesystem::exists(udfPath(dbname, funcname));
}

// Defined near applyScalarFunc; shared by scalar dispatch and callUDF.
static bool evalUDFBody(const StorageEngine::UDFInfo& udf,
                        const std::string& funcName,
                        const std::vector<std::string>& argValues,
                        StorageEngine* engine,
                        const std::string& dbname,
                        std::string& returnValue,
                        const std::map<std::string, std::string>* extraVars = nullptr);

// Stage EXECUTE FUNCTION context for the imminent trigger firing: NEW/OLD
// row values (dotted lowercase keys) plus TG_* diagnostics.  Consumed by
// the trigger executor's UDF dispatch.
static void stageExecFunctionCtx(const StorageEngine& eng,
                                 const std::string& tgName,
                                 const std::string& tgWhen,
                                 const std::string& tgOp,
                                 const std::string& tgTable,
                                 bool rowLevel,
                                 const std::map<std::string, std::string>* newVals,
                                 const std::map<std::string, std::string>* oldVals,
                                 const TableSchema* ctxCols = nullptr) {
StorageEngine::TriggerCtx ctx;
auto add = [&](const char* prefix, const std::map<std::string, std::string>* m) {
        if (!m) return;
        for (const auto& kv : *m) {
            std::string key = prefix + kv.first;
            for (auto& ch : key) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
            ctx.vars[key] = kv.second;
        }
};
add("new.", newVals);
add("old.", oldVals);
// The absent side of the NEW/OLD pair is a NULL record in PostgreSQL: bind
// every column to null so old.col in an INSERT trigger reads as NULL rather
// than surviving as literal text.
if (ctxCols) {
    for (size_t i = 0; i < ctxCols->len; ++i) {
        std::string col = ctxCols->cols[i].dataName;
        for (auto& ch : col) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        if (!newVals) ctx.vars["new." + col] = "null";
        if (!oldVals) ctx.vars["old." + col] = "null";
    }
}
ctx.vars["tg_name"] = tgName;
ctx.vars["tg_when"] = tgWhen;
ctx.vars["tg_level"] = rowLevel ? "ROW" : "STATEMENT";
ctx.vars["tg_op"] = tgOp;
ctx.vars["tg_relname"] = tgTable;
eng.setExecFunctionCtx(std::move(ctx));
}


StorageEngine::UDFInfo StorageEngine::getUDF(const std::string& dbname,
                                              const std::string& funcname) const {
    UDFInfo info;
    if (!databaseExists(dbname) || !validMetadataObjectName(funcname)) return info;
    auto path = udfPath(dbname, funcname);
    std::ifstream ifs(path);
    if (!ifs) return info;
    std::string line;
    if (std::getline(ifs, line)) {
        if (line.substr(0, 7) == "PARAMS:") {
            std::string rest = line.substr(7);
            size_t p = 0;
            while (p < rest.size()) {
                size_t comma = rest.find(',', p);
                std::string part = rest.substr(p, comma - p);
                if (!part.empty()) {
                    size_t colon = part.find(':');
                    if (colon != std::string::npos) {
                        info.paramNames.push_back(part.substr(0, colon));
                        info.paramTypes.push_back(part.substr(colon + 1));
                    } else {
                        info.paramNames.push_back(part);
                    }
                }
                if (comma == std::string::npos) break;
                p = comma + 1;
            }
            info.paramName = info.paramNames.empty() ? "" : info.paramNames[0];
        } else {
            info.paramName = line;
            info.paramNames.push_back(line);
        }
    }
    std::getline(ifs, info.expression);
    std::string volLine;
    if (std::getline(ifs, volLine) && !volLine.empty()) {
        info.provolatile = volLine[0];
    } else {
        info.provolatile = 'v';
    }
    std::string langLine;
    if (std::getline(ifs, langLine)) {
        std::string lang = langLine;
        for (char& c : lang) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        info.language = trim(lang).empty() ? "sql" : trim(lang);
    } else {
        info.language = "sql";
    }
    info.name = funcname;
    return info;
}


bool StorageEngine::callUDF(const std::string& dbname, const std::string& funcname,
                            const std::vector<std::string>& argValues,
                            std::string& returnValue) const {
    auto udf = getUDF(dbname, funcname);
    if (udf.expression.empty()) return false;
    return evalUDFBody(udf, funcname, argValues,
                       const_cast<StorageEngine*>(this), dbname, returnValue);
}

bool StorageEngine::callUDFWithCtx(const std::string& dbname,
                                   const std::string& funcname,
                                   const std::vector<std::string>& argValues,
                                   const TriggerCtx& ctx,
                                   std::string& returnValue) const {
    auto udf = getUDF(dbname, funcname);
    if (udf.expression.empty()) return false;
    return evalUDFBody(udf, funcname, argValues,
                       const_cast<StorageEngine*>(this), dbname, returnValue,
                       &ctx.vars);
}

std::vector<std::string> StorageEngine::getUDFNames(const std::string& dbname) const {
    std::vector<std::string> result;
    if (!databaseExists(dbname)) return result;
    auto fdir = udfDir(dbname);
    if (!std::filesystem::exists(fdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(fdir)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 5 && name.substr(name.size() - 5) == ".func") {
                result.push_back(name.substr(0, name.size() - 5));
            }
        }
    }
    return result;
}

// ========================================================================
// Table-valued functions
// ========================================================================

static std::filesystem::path tvfDir(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".tvf";
}

static std::filesystem::path tvfPath(const std::string& dbname,
                                     const std::string& funcname) {
    return std::filesystem::path(dbname) / ".tvf" / (funcname + ".tvf");
}

DBStatus StorageEngine::createTVF(const std::string& dbname,
                                   const std::string& funcname,
                                   const std::string& param,
                                   const std::string& sql) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(funcname)) return DBStatus::INVALID_ARGUMENT;
    auto tdir = tvfDir(dbname);
    if (!ensureMetadataDirectory(tdir)) return DBStatus::IO_ERROR;
    if (std::filesystem::exists(tvfPath(dbname, funcname))) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ostringstream serialized;
    serialized << param << "\n" << sql << "\n";
    return persistMetadata(tvfPath(dbname, funcname), serialized.str());
}

DBStatus StorageEngine::dropTVF(const std::string& dbname,
                                 const std::string& funcname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(funcname)) return DBStatus::INVALID_ARGUMENT;
    auto path = tvfPath(dbname, funcname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    std::error_code error;
    if (!std::filesystem::remove(path, error) || error) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

bool StorageEngine::tvfExists(const std::string& dbname,
                              const std::string& funcname) const {
    return databaseExists(dbname) && validMetadataObjectName(funcname) &&
           std::filesystem::exists(tvfPath(dbname, funcname));
}

std::string StorageEngine::getTVFSQL(const std::string& dbname,
                                      const std::string& funcname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(funcname)) return "";
    auto path = tvfPath(dbname, funcname);
    if (!std::filesystem::exists(path)) return "";
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string param, sql;
    std::getline(ifs, param);
    std::getline(ifs, sql);
    return sql;
}

std::string StorageEngine::getTVFParam(const std::string& dbname,
                                      const std::string& funcname) const {
    if (!databaseExists(dbname) || !validMetadataObjectName(funcname)) return "";
    auto path = tvfPath(dbname, funcname);
    if (!std::filesystem::exists(path)) return "";
    std::ifstream ifs(path);
    if (!ifs) return "";
    std::string param;
    std::getline(ifs, param);
    return param;
}

std::vector<std::string> StorageEngine::getTVFNames(const std::string& dbname) const {
    std::vector<std::string> result;
    if (!databaseExists(dbname)) return result;
    auto tdir = tvfDir(dbname);
    if (!std::filesystem::exists(tdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(tdir)) {
        if (entry.is_regular_file()) {
            std::string name = entry.path().filename().string();
            if (name.size() > 4 && name.substr(name.size() - 4) == ".tvf") {
                result.push_back(name.substr(0, name.size() - 4));
            }
        }
    }
    return result;
}

// ========================================================================
// Statistics
// ========================================================================

std::filesystem::path StorageEngine::statsPath(const std::string& dbname) const {
    return dbPath(dbname) / ".stats";
}

// Helper: compute MCV (Most Common Values) from a list of values
static std::vector<std::pair<std::string, size_t>> computeMCV(
    const std::vector<std::string>& vals, size_t topN = 10) {
    std::map<std::string, size_t> freq;
    for (const auto& v : vals) freq[v]++;
    std::vector<std::pair<std::string, size_t>> result(freq.begin(), freq.end());
    std::sort(result.begin(), result.end(),
              [](const auto& a, const auto& b) { return a.second > b.second; });
    if (result.size() > topN) result.resize(topN);
    return result;
}

static std::string mcvToString(const std::vector<std::pair<std::string, size_t>>& mcv) {
    std::string s;
    for (size_t i = 0; i < mcv.size(); ++i) {
        if (i > 0) s += ";";
        s += std::to_string(mcv[i].second) + ":" + mcv[i].first;
    }
    return s;
}

static std::vector<std::pair<std::string, size_t>> mcvFromString(const std::string& s) {
    std::vector<std::pair<std::string, size_t>> result;
    size_t pos = 0;
    while (pos < s.size()) {
        size_t semi = s.find(';', pos);
        std::string item = (semi == std::string::npos) ? s.substr(pos) : s.substr(pos, semi - pos);
        size_t colon = item.find(':');
        if (colon != std::string::npos) {
            try {
                size_t freq = std::stoull(item.substr(0, colon));
                result.push_back({item.substr(colon + 1), freq});
            } catch (...) {}
        }
        if (semi == std::string::npos) break;
        pos = semi + 1;
    }
    return result;
}

// Parse a stats line into ColumnStats. Format:
// tname cname card|min|max|hist|mcv
static StorageEngine::ColumnStats parseStatsLine(const std::string& line) {
    std::stringstream ss(line);
    std::string tname, cname;
    ss >> tname >> cname;
    // Read remainder after cname; cardinality is at start, followed by |min|max|hist|mcv
    std::string rest;
    std::getline(ss, rest);
    rest = trim(rest);
    // Extract cardinality (number at start of rest)
    size_t card = 0;
    size_t numEnd = 0;
    while (numEnd < rest.size() && std::isdigit(static_cast<unsigned char>(rest[numEnd]))) ++numEnd;
    try { card = std::stoull(rest.substr(0, numEnd)); } catch (...) {}
    // The pipe-separated fields start at numEnd
    std::string pipePart = (numEnd < rest.size()) ? rest.substr(numEnd) : "";
    // Split pipePart by '|', skipping leading empty segments
    std::vector<std::string> parts;
    size_t p = 0;
    while (p < pipePart.size()) {
        size_t pipe = pipePart.find('|', p);
        std::string part = (pipe == std::string::npos) ? pipePart.substr(p) : pipePart.substr(p, pipe - p);
        parts.push_back(part);
        if (pipe == std::string::npos) break;
        p = pipe + 1;
    }
    // Positional layout after cardinality: |min|max|hist|mcv|nulls.
    // parts[0] is the empty split before min (the | right after the
    // cardinality); min/max may themselves be legitimately empty (an
    // all-NULL column), so leading-empty skipping would misalign fields.
    // Old files may omit mcv/nulls; guard by size.
    std::vector<std::string> realParts;
    for (size_t i = 1; i < parts.size(); ++i) realParts.push_back(parts[i]);
    if (realParts.size() < 4 && parts.size() >= 1) {
        // zero-delimiter degenerate line; fall back to old alignment
        size_t startIdx = 0;
        while (startIdx < parts.size() && parts[startIdx].empty()) ++startIdx;
        realParts.clear();
        for (size_t i = startIdx; i < parts.size(); ++i) realParts.push_back(parts[i]);
    }

    StorageEngine::ColumnStats cs;
    cs.cardinality = card;
    if (realParts.size() > 0) cs.minVal = realParts[0];
    if (realParts.size() > 1) cs.maxVal = realParts[1];
    // Histogram
    if (realParts.size() > 2 && !realParts[2].empty()) {
        const std::string& histStr = realParts[2];
        size_t pos = 0;
        while (pos < histStr.size()) {
            size_t semi = histStr.find(';', pos);
            std::string bucket = (semi == std::string::npos) ? histStr.substr(pos) : histStr.substr(pos, semi - pos);
            size_t comma = bucket.find(',');
            if (comma != std::string::npos) {
                cs.histogram.push_back({bucket.substr(0, comma), bucket.substr(comma + 1)});
            }
            if (semi == std::string::npos) break;
            pos = semi + 1;
        }
    }
    // MCV
    if (realParts.size() > 3 && !realParts[3].empty()) {
        cs.mcv = mcvFromString(realParts[3]);
    }
    // NULL count (optional 5th field; absent in pre-nullCount stats files)
    if (realParts.size() > 4 && !realParts[4].empty()) {
        try { cs.nullCount = std::stoull(realParts[4]); } catch (...) {}
    }
    return cs;
}

// Write a single ColumnStats entry
static void writeStatsEntry(std::ostream& ofs, const std::string& tname,
                            const std::string& cname, const StorageEngine::ColumnStats& cs) {
    ofs << tname << " " << cname << " " << cs.cardinality
        << "|" << cs.minVal << "|" << cs.maxVal << "|";
    for (size_t i = 0; i < cs.histogram.size(); ++i) {
        if (i > 0) ofs << ";";
        ofs << cs.histogram[i].first << "," << cs.histogram[i].second;
    }
    ofs << "|" << mcvToString(cs.mcv) << "|" << cs.nullCount << "\n";
}

bool StorageEngine::analyzeTable(const std::string& dbname,
                                 const std::string& tablename) {
    if (!tableExists(dbname, tablename)) return false;
    TableSchema tbl = getTableSchema(dbname, tablename);

    TableStats stats;
    stats.rowCount = 0;
    std::map<std::string, std::set<std::string>> distinctVals;
    std::map<std::string, std::vector<std::string>> allVals;
    std::map<std::string, std::string> minVals, maxVals;
    std::map<std::string, size_t> nullCounts;

    if (!forEachRow(dbname, tablename, [&](uint32_t, uint16_t, const char* data, size_t len) {
        stats.rowCount++;
        std::string row(data, len);
        for (size_t i = 0; i < tbl.len; ++i) {
            std::string val = extractColumnValue(row, tbl, i);
            if (val.empty()) ++nullCounts[tbl.cols[i].dataName];
            distinctVals[tbl.cols[i].dataName].insert(val);
            allVals[tbl.cols[i].dataName].push_back(val);
            if (minVals.find(tbl.cols[i].dataName) == minVals.end() || val < minVals[tbl.cols[i].dataName]) {
                minVals[tbl.cols[i].dataName] = val;
            }
            if (maxVals.find(tbl.cols[i].dataName) == maxVals.end() || val > maxVals[tbl.cols[i].dataName]) {
                maxVals[tbl.cols[i].dataName] = val;
            }
        }
    })) return false;

    const size_t HIST_BUCKETS = 10;
    const size_t MCV_TOP_N = 10;
    for (size_t i = 0; i < tbl.len; ++i) {
        const std::string& cname = tbl.cols[i].dataName;
        StorageEngine::ColumnStats cs;
        cs.cardinality = distinctVals[cname].size();
        cs.nullCount = nullCounts[cname];
        cs.minVal = minVals[cname];
        cs.maxVal = maxVals[cname];
        auto& vals = allVals[cname];
        // Build equi-depth histogram
        if (vals.size() >= HIST_BUCKETS * 2) {
            bool isNumeric = (!tbl.cols[i].isVariableLength &&
                              (tbl.cols[i].dataType == "int" || tbl.cols[i].dataType == "long" ||
                               tbl.cols[i].dataType == "tinyint" || tbl.cols[i].dataType == "float" ||
                               tbl.cols[i].dataType == "double" || tbl.cols[i].dataType == "decimal"));
            if (isNumeric) {
                std::vector<long long> nums;
                nums.reserve(vals.size());
                for (const auto& v : vals) {
                    try { nums.push_back(std::stoll(v)); } catch (...) { nums.push_back(0); }
                }
                std::sort(nums.begin(), nums.end());
                size_t perBucket = nums.size() / HIST_BUCKETS;
                for (size_t b = 0; b < HIST_BUCKETS; ++b) {
                    size_t start = b * perBucket;
                    size_t end = (b == HIST_BUCKETS - 1) ? nums.size() - 1 : (b + 1) * perBucket;
                    cs.histogram.push_back({std::to_string(nums[start]), std::to_string(nums[end])});
                }
            } else {
                std::sort(vals.begin(), vals.end());
                size_t perBucket = vals.size() / HIST_BUCKETS;
                for (size_t b = 0; b < HIST_BUCKETS; ++b) {
                    size_t start = b * perBucket;
                    size_t end = (b == HIST_BUCKETS - 1) ? vals.size() - 1 : (b + 1) * perBucket;
                    cs.histogram.push_back({vals[start], vals[end]});
                }
            }
        }
        // Compute MCV
        cs.mcv = computeMCV(vals, MCV_TOP_N);
        stats.colStats[cname] = cs;
    }

    // Load existing stats, update this table's entry (preserve multi-col stats)
    std::map<std::string, TableStats> allStats;
    auto spath = statsPath(dbname);
    if (std::filesystem::exists(spath)) {
        std::ifstream ifs(spath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string tname, cname;
            ss >> tname >> cname;
            if (cname == "__rows__") {
                std::string rc;
                std::getline(ss, rc);
                try { allStats[tname].rowCount = std::stoull(rc); } catch (...) {}
                continue;
            }
            if (cname == "__multi__") {
                std::string colKey;
                ss >> colKey;
                std::string rest;
                std::getline(ss, rest);
                // Reconstruct line for parseStatsLine
                allStats[tname].multiColStats[colKey] = parseStatsLine(tname + " " + colKey + " " + rest);
                continue;
            }
            allStats[tname].colStats[cname] = parseStatsLine(line);
        }
    }
    // Preserve multi-col stats from existing entry
    auto it = allStats.find(tablename);
    if (it != allStats.end()) {
        stats.multiColStats = it->second.multiColStats;
    }
    allStats[tablename] = stats;

    // Write back
    std::ostringstream serialized;
    for (const auto& kv : allStats) {
        serialized << kv.first << " __rows__ " << kv.second.rowCount << "||\n";
        for (const auto& cv : kv.second.colStats) {
            writeStatsEntry(serialized, kv.first, cv.first, cv.second);
        }
        for (const auto& mv : kv.second.multiColStats) {
            serialized << kv.first << " __multi__ " << mv.first << " " << mv.second.cardinality
                << "|" << mv.second.minVal << "|" << mv.second.maxVal << "|";
            for (size_t i = 0; i < mv.second.histogram.size(); ++i) {
                if (i > 0) serialized << ";";
                serialized << mv.second.histogram[i].first << "," << mv.second.histogram[i].second;
            }
            serialized << "|" << mcvToString(mv.second.mcv) << "\n";
        }
    }
    return index_file::writeAtomically(spath, serialized.str());
}

bool StorageEngine::analyzeMultiColumn(const std::string& dbname, const std::string& tablename,
                                       const std::vector<std::string>& colnames) {
    if (!tableExists(dbname, tablename)) return false;
    if (colnames.size() < 2) return false;
    TableSchema tbl = getTableSchema(dbname, tablename);

    // Build column index map
    std::map<std::string, size_t> colIdx;
    for (size_t i = 0; i < tbl.len; ++i) {
        colIdx[tbl.cols[i].dataName] = i;
    }
    for (const auto& c : colnames) {
        if (colIdx.find(c) == colIdx.end()) return false;
    }

    std::string colKey;
    for (size_t i = 0; i < colnames.size(); ++i) {
        if (i > 0) colKey += ",";
        colKey += colnames[i];
    }

    std::map<std::string, size_t> distinctVals;
    std::map<std::string, std::string> minVals, maxVals;
    size_t rowCount = 0;

    if (!forEachRow(dbname, tablename, [&](uint32_t, uint16_t, const char* data, size_t len) {
        rowCount++;
        std::string row(data, len);
        std::string combined;
        for (size_t i = 0; i < colnames.size(); ++i) {
            if (i > 0) combined += "#";
            combined += extractColumnValue(row, tbl, colIdx[colnames[i]]);
        }
        distinctVals[combined]++;
        if (minVals.empty() || combined < minVals.begin()->first) minVals[combined] = combined;
        if (maxVals.empty() || combined > maxVals.rbegin()->first) maxVals[combined] = combined;
    })) return false;

    StorageEngine::ColumnStats cs;
    cs.cardinality = distinctVals.size();
    if (!minVals.empty()) cs.minVal = minVals.begin()->first;
    if (!maxVals.empty()) cs.maxVal = maxVals.rbegin()->first;

    // MCV for combined values
    std::vector<std::pair<std::string, size_t>> freqVec(distinctVals.begin(), distinctVals.end());
    std::sort(freqVec.begin(), freqVec.end(),
              [](const auto& a, const auto& b) { return a.second > b.second; });
    if (freqVec.size() > 10) freqVec.resize(10);
    cs.mcv = freqVec;

    // Load existing stats
    std::map<std::string, TableStats> allStats;
    auto spath = statsPath(dbname);
    if (std::filesystem::exists(spath)) {
        std::ifstream ifs(spath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string tname, cname;
            ss >> tname >> cname;
            if (cname == "__rows__") {
                std::string rc; std::getline(ss, rc);
                try { allStats[tname].rowCount = std::stoull(rc); } catch (...) {}
                continue;
            }
            if (cname == "__multi__") {
                std::string colKey; ss >> colKey;
                std::string rest; std::getline(ss, rest);
                allStats[tname].multiColStats[colKey] = parseStatsLine(tname + " " + colKey + " " + rest);
                continue;
            }
            allStats[tname].colStats[cname] = parseStatsLine(line);
        }
    }
    allStats[tablename].multiColStats[colKey] = cs;

    // Write back
    std::ostringstream serialized;
    for (const auto& kv : allStats) {
        serialized << kv.first << " __rows__ " << kv.second.rowCount << "||\n";
        for (const auto& cv : kv.second.colStats) {
            writeStatsEntry(serialized, kv.first, cv.first, cv.second);
        }
        for (const auto& mv : kv.second.multiColStats) {
            serialized << kv.first << " __multi__ " << mv.first << " " << mv.second.cardinality
                << "|" << mv.second.minVal << "|" << mv.second.maxVal << "|";
            for (size_t i = 0; i < mv.second.histogram.size(); ++i) {
                if (i > 0) serialized << ";";
                serialized << mv.second.histogram[i].first << "," << mv.second.histogram[i].second;
            }
            serialized << "|" << mcvToString(mv.second.mcv) << "\n";
        }
    }
    return index_file::writeAtomically(spath, serialized.str());
}

std::map<std::string, double> StorageEngine::computeFunctionalDependencies(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& colnames) const {
    std::map<std::string, double> result;
    if (!tableExists(dbname, tablename) || colnames.size() < 2) return result;
    TableSchema tbl = getTableSchema(dbname, tablename);

    std::map<std::string, size_t> colIdx;
    for (size_t i = 0; i < tbl.len; ++i) colIdx[tbl.cols[i].dataName] = i;
    for (const auto& c : colnames) {
        if (colIdx.find(c) == colIdx.end()) return result;
    }

    // Collect the projected values for each requested column, row by row.
    std::vector<std::vector<std::string>> rows; // rows[r][k] = value of colnames[k]
    if (!const_cast<StorageEngine*>(this)->forEachRow(dbname, tablename,
        [&](uint32_t, uint16_t, const char* data, size_t len) {
            std::string row(data, len);
            std::vector<std::string> vals;
            vals.reserve(colnames.size());
            for (const auto& c : colnames) {
                vals.push_back(const_cast<StorageEngine*>(this)->extractColumnValue(
                    row, tbl, colIdx[c]));
            }
            rows.push_back(std::move(vals));
        })) return result;

    size_t rowCount = rows.size();
    if (rowCount == 0) return result;

    // For each ordered pair (a -> b): group rows by a-value, and within each group
    // count how often the majority b-value occurs; degree = sum / rowCount.
    for (size_t ai = 0; ai < colnames.size(); ++ai) {
        for (size_t bi = 0; bi < colnames.size(); ++bi) {
            if (ai == bi) continue;
            std::map<std::string, std::map<std::string, size_t>> groups;
            for (const auto& r : rows) {
                groups[r[ai]][r[bi]]++;
            }
            size_t consistent = 0;
            for (const auto& g : groups) {
                size_t best = 0;
                for (const auto& bv : g.second) best = std::max(best, bv.second);
                consistent += best;
            }
            double degree = static_cast<double>(consistent) / static_cast<double>(rowCount);
            result[colnames[ai] + "=>" + colnames[bi]] = degree;
        }
    }
    return result;
}

std::map<std::string, int64_t> StorageEngine::computeNDistinct(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& colnames) const {
    std::map<std::string, int64_t> result;
    if (!tableExists(dbname, tablename) || colnames.size() < 2) return result;
    TableSchema tbl = getTableSchema(dbname, tablename);
    std::map<std::string, size_t> colIdx;
    for (size_t i = 0; i < tbl.len; ++i) colIdx[tbl.cols[i].dataName] = i;
    for (const auto& c : colnames)
        if (colIdx.find(c) == colIdx.end()) return result;

    std::vector<std::vector<std::string>> rows;
    if (!const_cast<StorageEngine*>(this)->forEachRow(dbname, tablename,
        [&](uint32_t, uint16_t, const char* data, size_t len) {
            std::string row(data, len);
            std::vector<std::string> vals;
            vals.reserve(colnames.size());
            for (const auto& c : colnames)
                vals.push_back(const_cast<StorageEngine*>(this)->extractColumnValue(
                    row, tbl, colIdx[c]));
            rows.push_back(std::move(vals));
        })) return result;
    if (rows.empty()) return result;

    // Per-column distinct counts.
    for (size_t k = 0; k < colnames.size(); ++k) {
        std::set<std::string> s;
        for (const auto& r : rows) s.insert(r[k]);
        result[colnames[k]] = static_cast<int64_t>(s.size());
    }
    // Full-group distinct combination count.
    std::set<std::string> combos;
    for (const auto& r : rows) {
        std::string key;
        for (const auto& v : r) { key += v; key += '\x01'; }
        combos.insert(key);
    }
    std::string groupKey;
    for (size_t k = 0; k < colnames.size(); ++k) {
        if (k) groupKey += ", ";
        groupKey += colnames[k];
    }
    result[groupKey] = static_cast<int64_t>(combos.size());
    return result;
}

std::vector<std::pair<std::string, int64_t>> StorageEngine::computeMCVCombinations(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& colnames, size_t topN) const {
    std::vector<std::pair<std::string, int64_t>> result;
    if (!tableExists(dbname, tablename) || colnames.empty()) return result;
    TableSchema tbl = getTableSchema(dbname, tablename);
    std::map<std::string, size_t> colIdx;
    for (size_t i = 0; i < tbl.len; ++i) colIdx[tbl.cols[i].dataName] = i;
    for (const auto& c : colnames)
        if (colIdx.find(c) == colIdx.end()) return result;

    std::map<std::string, int64_t> counts;
    if (!const_cast<StorageEngine*>(this)->forEachRow(dbname, tablename,
        [&](uint32_t, uint16_t, const char* data, size_t len) {
            std::string row(data, len);
            std::string disp = "(";
            for (size_t k = 0; k < colnames.size(); ++k) {
                if (k) disp += ", ";
                disp += const_cast<StorageEngine*>(this)->extractColumnValue(
                    row, tbl, colIdx[colnames[k]]);
            }
            disp += ")";
            counts[disp]++;
        })) return result;

    result.assign(counts.begin(), counts.end());
    std::sort(result.begin(), result.end(),
              [](const std::pair<std::string, int64_t>& a,
                 const std::pair<std::string, int64_t>& b) {
                  if (a.second != b.second) return a.second > b.second;
                  return a.first < b.first;
              });
    if (result.size() > topN) result.resize(topN);
    return result;
}

StorageEngine::BufferPoolStats StorageEngine::getBufferPoolStats() const {
    BufferPoolStats stats;
    // Page allocators (table data files)
    for (const auto& kv : pageAllocators_) {
        if (kv.second && kv.second->bufferPool()) {
            auto* bp = kv.second->bufferPool();
            stats.totalHits += bp->hits();
            stats.totalMisses += bp->misses();
        }
    }
    // Primary key indexes
    for (const auto& kv : pkIndexCache_) {
        if (kv.second) {
            stats.totalHits += kv.second->cacheHits();
            stats.totalMisses += kv.second->cacheMisses();
        }
    }
    // Secondary indexes
    for (const auto& kv : secondaryIndexCache_) {
        if (kv.second) {
            stats.totalHits += kv.second->cacheHits();
            stats.totalMisses += kv.second->cacheMisses();
        }
    }
    size_t total = stats.totalHits + stats.totalMisses;
    stats.hitRate = total == 0 ? 0.0 : 100.0 * static_cast<double>(stats.totalHits) / static_cast<double>(total);
    return stats;
}

std::vector<StorageEngine::BufferCacheEntry> StorageEngine::getBufferCacheEntries() const {
    std::vector<BufferCacheEntry> result;
    for (const auto& kv : pageAllocators_) {
        if (kv.second && kv.second->bufferPool()) {
            auto* bp = kv.second->bufferPool();
            auto frames = bp->getFrameInfo();
            for (const auto& f : frames) {
                if (f.valid) {
                    result.push_back({kv.first, f.pageId, f.dirty, f.pinCount});
                }
            }
        }
    }
    return result;
}

uint32_t StorageEngine::tableNumPages(const std::string& dbname,
                                      const std::string& tablename) const {
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    if (!pa) return 0;
    return pa->numPages();
}

size_t StorageEngine::getTableRowCount(const std::string& dbname,
                                        const std::string& tablename) const {
    auto spath = statsPath(dbname);
    if (!std::filesystem::exists(spath)) return 0;
    std::ifstream ifs(spath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string tname, cname;
        ss >> tname >> cname;
        if (tname == tablename && cname == "__rows__") {
            std::string rest;
            std::getline(ss, rest);
            try { return std::stoull(rest); } catch (...) { return 0; }
        }
    }
    return 0;
}

StorageEngine::ColumnStats StorageEngine::getColumnStats(
    const std::string& dbname, const std::string& tablename,
    const std::string& colname) const {
    auto spath = statsPath(dbname);
    if (!std::filesystem::exists(spath)) return {};
    std::ifstream ifs(spath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string tname, cname;
        ss >> tname >> cname;
        if (tname == tablename && cname == colname) {
            std::string rest;
            std::getline(ss, rest);
            return parseStatsLine(tname + " " + cname + " " + rest);
        }
    }
    return {};
}

StorageEngine::ColumnStats StorageEngine::getMultiColumnStats(
    const std::string& dbname, const std::string& tablename,
    const std::string& colKey) const {
    auto spath = statsPath(dbname);
    if (!std::filesystem::exists(spath)) return {};
    std::ifstream ifs(spath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string tname, tag, key;
        ss >> tname >> tag >> key;
        if (tname == tablename && tag == "__multi__" && key == colKey) {
            std::string rest;
            std::getline(ss, rest);
            return parseStatsLine(tname + " " + key + " " + rest);
        }
    }
    return {};
}

std::filesystem::path StorageEngine::indexPath(const std::string& dbname,
                                                const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".idx");
}

// ========================================================================
// Tablespace management
// ========================================================================
std::filesystem::path StorageEngine::tablespaceDir(const std::string& dbname,
                                                    const std::string& tablespaceName) const {
    if (tablespaceName.empty() || tablespaceName == "pg_default") {
        return dbPath(dbname);
    }
    auto tsPath = dbPath(dbname) / "pg_tblspc" / (tablespaceName + ".path");
    if (std::filesystem::exists(tsPath)) {
        std::ifstream ifs(tsPath);
        std::string path;
        if (std::getline(ifs, path) && !path.empty()) {
            return std::filesystem::path(path);
        }
    }
    // Never silently fall back to pg_default: doing so can make a relation
    // appear empty after restart and can overwrite unrelated data.
    return dbPath(dbname) / "pg_tblspc" / (tablespaceName + ".missing");
}

DBStatus StorageEngine::createTablespace(const std::string& dbname,
                                          const std::string& tsName,
                                          const std::string& physicalPath) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (tsName.empty() || tsName == "pg_default" || tsName == "pg_global") {
        return DBStatus::INVALID_VALUE; // reserved names
    }
    auto tsDir = dbPath(dbname) / "pg_tblspc";
    if (!std::filesystem::exists(tsDir)) {
        std::filesystem::create_directories(tsDir);
    }
    auto tsPath = tsDir / (tsName + ".path");
    if (std::filesystem::exists(tsPath)) return DBStatus::TABLE_ALREADY_EXISTS;

    // Ensure physical directory exists
    if (!std::filesystem::exists(physicalPath)) {
        std::filesystem::create_directories(physicalPath);
    }
    std::ofstream ofs(tsPath);
    if (!ofs) return DBStatus::INVALID_VALUE;
    ofs << physicalPath << "\n";
    return DBStatus::OK;
}

DBStatus StorageEngine::dropTablespace(const std::string& dbname,
                                        const std::string& tsName) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (tsName.empty() || tsName == "pg_default" || tsName == "pg_global") {
        return DBStatus::INVALID_VALUE;
    }
    auto tsPath = dbPath(dbname) / "pg_tblspc" / (tsName + ".path");
    if (!std::filesystem::exists(tsPath)) return DBStatus::TABLE_NOT_FOUND;

    // Check if any table uses this tablespace
    auto tables = getTableNames(dbname);
    for (const auto& tname : tables) {
        TableSchema tbl = getTableSchema(dbname, tname);
        if (tbl.tablespace == tsName) return DBStatus::INVALID_VALUE; // not empty
    }
    std::filesystem::remove(tsPath);
    return DBStatus::OK;
}

std::vector<std::string> StorageEngine::listTablespaces(const std::string& dbname) const {
    std::vector<std::string> result;
    result.push_back("pg_default");
    auto tsDir = dbPath(dbname) / "pg_tblspc";
    if (!std::filesystem::exists(tsDir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(tsDir)) {
        std::string fname = entry.path().filename().string();
        if (fname.size() > 5 && fname.substr(fname.size() - 5) == ".path") {
            result.push_back(fname.substr(0, fname.size() - 5));
        }
    }
    return result;
}

// ========================================================================
// Page Allocator
// ========================================================================
namespace {

bool installHeapWritebackWalBarrier(const StorageEngine& engine,
                                    const std::string& dbname,
                                    PageAllocator& allocator) {
    WALManager* wal = engine.getWAL(dbname);
    if (!wal || !allocator.bufferPool()) return false;
    // Capture the manager, not StorageEngine::getWAL(): writeback holds the
    // buffer-pool mutex, while getWAL takes cacheMutex_. Background writeback
    // takes those locks in the opposite order. The database-cache teardown
    // path erases allocators before their corresponding WAL manager.
    allocator.bufferPool()->setWritebackBarrier([wal]() {
        return wal->XLogFlush(wal->currentWriteLsn());
    });
    return true;
}

}  // namespace

PageAllocator* StorageEngine::getPageAllocator(const std::string& dbname,
                                                const std::string& tablename) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + "/" + tablename;
    auto it = pageAllocators_.find(key);
    if (it != pageAllocators_.end()) {
        return it->second.get();
    }

    TableSchema tbl = getTableSchema(dbname, tablename);
    if (tbl.formatVersion != DATA_FILE_FORMAT_VERSION) {
        std::cerr << "[storage] table " << dbname << "/" << tablename
                  << " uses an unsupported schema format; recreate it" << std::endl;
        return nullptr;
    }
    const std::string tablespace = tbl.tablespace.empty() ? "pg_default" : tbl.tablespace;
    if (tablespace != "pg_default") {
        auto marker = dbPath(dbname) / "pg_tblspc" / (tablespace + ".path");
        if (!std::filesystem::exists(marker)) return nullptr;
    }
    std::filesystem::path dt = dataPath(dbname, tablename);

    auto pa = std::make_unique<PageAllocator>(dt.string(), tbl.rowSize(), pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion);
    if (!installHeapWritebackWalBarrier(*this, dbname, *pa) || !pa->open()) {
        return nullptr;
    }
    PageAllocator* ptr = pa.get();
    pageAllocators_[key] = std::move(pa);
    return ptr;
}

void StorageEngine::closeAllPageAllocators() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    pageAllocators_.clear();
}

static bool readWholeBinaryFile(const std::filesystem::path& path,
                                std::vector<char>& bytes) {
    bytes.clear();
    std::error_code ec;
    if (!std::filesystem::exists(path, ec)) return !ec;
    const auto size = std::filesystem::file_size(path, ec);
    if (ec || size > static_cast<uintmax_t>(std::numeric_limits<size_t>::max())) return false;
    bytes.resize(static_cast<size_t>(size));
    if (bytes.empty()) return true;
    std::ifstream in(path, std::ios::binary);
    if (!in) return false;
    in.read(bytes.data(), static_cast<std::streamsize>(bytes.size()));
    return in.good() || in.eof();
}

bool StorageEngine::flushDatabaseCaches(const std::string& dbname, bool heapPages) {
    return flushSelectedCaches(dbname, nullptr, heapPages);
}

bool StorageEngine::flushTableCaches(
    const std::string& dbname,
    const std::set<std::string>& tablenames,
    bool heapPages) {
    if (tablenames.empty()) return true;
    return flushSelectedCaches(dbname, &tablenames, heapPages);
}

bool StorageEngine::flushSelectedCaches(
    const std::string& dbname,
    const std::set<std::string>* tablenames,
    bool heapPages) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    const std::string tablePrefix = dbname + "/";
    const std::string hashPrefix = dbname + ".";
    const std::string toastPrefix = dbname + ":";
    const auto slashKeySelected = [&](const std::string& key) {
        if (!tablenames) return key.rfind(tablePrefix, 0) == 0;
        for (const auto& table : *tablenames) {
            const std::string relationKey = tablePrefix + table;
            if (key == relationKey ||
                (key.size() > relationKey.size() &&
                 key.compare(0, relationKey.size(), relationKey) == 0 &&
                 (key[relationKey.size()] == '/' ||
                  key[relationKey.size()] == '#'))) {
                return true;
            }
        }
        return false;
    };
    const auto hashKeySelected = [&](const std::string& key) {
        if (!tablenames) return key.rfind(hashPrefix, 0) == 0;
        for (const auto& table : *tablenames) {
            if (key.rfind(hashPrefix + table + ".", 0) == 0) return true;
        }
        return false;
    };
    const auto toastKeySelected = [&](const std::string& key) {
        if (!tablenames) return key.rfind(toastPrefix, 0) == 0;
        for (const auto& table : *tablenames) {
            if (key == toastPrefix + table) return true;
        }
        return false;
    };

    bool ok = true;
    auto flushWalLoggedIndex = [&](const std::filesystem::path& path,
                                   bool dirty,
                                   const std::function<bool()>& flush) {
        if (!dirty) return true;
        // Write the whole-file WAL image pair at most once per checkpoint
        // epoch per file.  The physical flush below already puts committed
        // entries on disk at commit time (index consistency after kill -9
        // rides on that flush — verified by the barrier kill-storm), so the
        // image is an integrity snapshot, not the primary durability
        // mechanism. Recovery validates these legacy images but cannot
        // blindly replay an epoch baseline over later commits; an abandoned
        // transaction instead triggers a rebuild from the recovered heap.
        // Repeating the image every commit made WAL volume grow with index
        // size per transaction (~120KB per INSERT).
        const std::string pathKey = path.string();
        const bool needImage =
            indexImageWrittenEpoch_.find(pathKey) == indexImageWrittenEpoch_.end() ||
            indexImageWrittenEpoch_[pathKey] != indexImageEpoch_;
        if (!needImage) {
            return flush();
        }
        std::vector<char> before;
        if (!readWholeBinaryFile(path, before)) return false;

        WALManager* wal = getWAL(dbname);
        if (!wal) return false;
        const Lsn beforeLsn = walIndexFileImage(dbname, path, before, true);
        if (beforeLsn == INVALID_LSN || !wal->XLogFlush(beforeLsn)) return false;

        if (!flush()) return false;
        std::vector<char> after;
        if (!readWholeBinaryFile(path, after)) return false;
        const Lsn afterLsn = walIndexFileImage(dbname, path, after, false);
        if (afterLsn == INVALID_LSN || !wal->XLogFlush(afterLsn)) return false;
        indexImageWrittenEpoch_[pathKey] = indexImageEpoch_;
        return true;
    };
    if (heapPages) {
        for (const auto& [key, allocator] : pageAllocators_) {
            if (slashKeySelected(key) && allocator && !allocator->flush()) {
                ok = false;
            }
        }
    }
    for (const auto& [key, index] : pkIndexCache_) {
        if (slashKeySelected(key) && index &&
            !flushWalLoggedIndex(index->filePath(), index->hasDirtyPages(),
                                 [&] { return index->flush(); })) {
            ok = false;
        }
    }
    for (const auto& [key, index] : secondaryIndexCache_) {
        if (slashKeySelected(key) && index &&
            !flushWalLoggedIndex(index->filePath(), index->hasDirtyPages(),
                                 [&] { return index->flush(); })) {
            ok = false;
        }
    }
    for (const auto& [key, index] : hashIndexCache_) {
        if (hashKeySelected(key) && index &&
            !flushWalLoggedIndex(index->filePath(), index->hasDirtyData(),
                                 [&] { return index->flush(); })) {
            ok = false;
        }
    }
    for (const auto& [key, index] : bloomIndexCache_) {
        if (hashKeySelected(key) && index &&
            !flushWalLoggedIndex(index->filePath(), index->hasDirtyData(),
                                 [&] { return index->flush(); })) {
            ok = false;
        }
    }
    if (heapPages) {
        for (const auto& [key, allocator] : toastPageAllocators_) {
            if (toastKeySelected(key) && allocator && !allocator->flush()) {
                ok = false;
            }
        }
    }
    for (const auto& [key, index] : toastIndexes_) {
        if (toastKeySelected(key) && index &&
            !flushWalLoggedIndex(index->filePath(), index->hasDirtyPages(),
                                 [&] { return index->flush(); })) {
            ok = false;
        }
    }
    return ok;
}

void StorageEngine::closeDatabaseCaches(const std::string& dbname) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    const std::string tablePrefix = dbname + "/";
    const std::string toastPrefix = dbname + ":";

    auto eraseTableCaches = [&tablePrefix](auto& cache) {
        for (auto it = cache.begin(); it != cache.end();) {
            if (it->first.rfind(tablePrefix, 0) == 0) {
                it = cache.erase(it);
            } else {
                ++it;
            }
        }
    };
    eraseTableCaches(pageAllocators_);
    eraseTableCaches(fsmCache_);
    eraseTableCaches(vmCache_);
    eraseTableCaches(pkIndexCache_);
    eraseTableCaches(secondaryIndexCache_);
    eraseTableCaches(secidxLinesCache_);
    eraseTableCaches(hashidxLinesCache_);
    for (auto it = hashIndexCache_.begin(); it != hashIndexCache_.end();) {
        if (it->first.rfind(dbname + ".", 0) == 0) {
            it = hashIndexCache_.erase(it);
        } else {
            ++it;
        }
    }
    for (auto it = bloomIndexCache_.begin();
         it != bloomIndexCache_.end();) {
        if (it->first.rfind(dbname + ".", 0) == 0) {
            it = bloomIndexCache_.erase(it);
        } else {
            ++it;
        }
    }
    exclusionCache_.erase(dbname);
    {
        std::lock_guard<std::mutex> lock(schemaCacheMutex_);
        for (auto it = schemaCache_.begin(); it != schemaCache_.end();) {
            if (it->first.rfind(tablePrefix, 0) == 0) {
                it = schemaCache_.erase(it);
            } else {
                ++it;
            }
        }
    }
    {
        // Drop deferred (possibly dirty) sequence state: the .seq files are
        // about to disappear with the database/table directory.
        std::lock_guard<std::mutex> lock(seqCacheMutex_);
        for (auto it = seqFileCache_.begin(); it != seqFileCache_.end();) {
            if (it->first.rfind(tablePrefix, 0) == 0) {
                it = seqFileCache_.erase(it);
            } else {
                ++it;
            }
        }
    }

    for (auto it = toastPageAllocators_.begin(); it != toastPageAllocators_.end();) {
        if (it->first.rfind(toastPrefix, 0) == 0) {
            it = toastPageAllocators_.erase(it);
        } else {
            ++it;
        }
    }
    for (auto it = toastIndexes_.begin(); it != toastIndexes_.end();) {
        if (it->first.rfind(toastPrefix, 0) == 0) {
            it = toastIndexes_.erase(it);
        } else {
            ++it;
        }
    }

    {
        std::lock_guard<std::mutex> lock(spGiSTMutex_);
        for (auto it = spGiSTCache_.begin(); it != spGiSTCache_.end();) {
            if (it->first.rfind(tablePrefix, 0) == 0) {
                it = spGiSTCache_.erase(it);
            } else {
                ++it;
            }
        }
    }

    commitLogs_.erase(dbname);
    walManagers_.erase(dbname);
    lastCheckpointLsns_.erase(dbname);

    // These maps are also read/written by connection threads under their
    // own mutexes (recordModification / resetDeadTupleCount / stats
    // readers); erasing here without those mutexes raced the background
    // pruner against a concurrent insert (TSAN: data race on the map's
    // string keys).
    {
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        for (auto it = deadTupleCounts_.begin(); it != deadTupleCounts_.end();) {
            if (it->first.first == dbname) {
                it = deadTupleCounts_.erase(it);
            } else {
                ++it;
            }
        }
    }
    {
        std::lock_guard<std::mutex> lock(modifyMutex_);
        for (auto it = modifyCounts_.begin(); it != modifyCounts_.end();) {
            if (it->first.first == dbname) {
                it = modifyCounts_.erase(it);
            } else {
                ++it;
            }
        }
    }
}

bool StorageEngine::refreshPreparedTableCaches(
    const std::string& dbname, const std::string& tablename) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    const std::string tableKey = dbname + "/" + tablename;
    const std::string secondaryPrefix = tableKey + "/";
    const std::string auxiliaryPrefix = dbname + "." + tablename + ".";
    const std::string toastKey = dbname + ":" + tablename;

    // PREPARE flushes the producing backend before publishing its durable
    // record.  A different completing backend may nevertheless have clean,
    // older pages for the same relation cached.  Reject genuinely dirty
    // local state, then discard only clean data/index caches so completion
    // operates on the producer's on-disk generation.
    const auto pageCacheDirty = [](const auto& allocator) {
        if (!allocator || !allocator->bufferPool()) return false;
        for (const auto& frame : allocator->bufferPool()->getFrameInfo()) {
            if (frame.dirty) return true;
        }
        return false;
    };
    if (auto it = pageAllocators_.find(tableKey);
        it != pageAllocators_.end() && pageCacheDirty(it->second)) {
        return false;
    }
    if (auto it = pkIndexCache_.find(tableKey);
        it != pkIndexCache_.end() && it->second &&
        it->second->hasDirtyPages()) {
        return false;
    }
    for (const auto& [key, index] : secondaryIndexCache_) {
        if (key.rfind(secondaryPrefix, 0) == 0 && index &&
            index->hasDirtyPages()) {
            return false;
        }
    }
    for (const auto& [key, index] : hashIndexCache_) {
        if (key.rfind(auxiliaryPrefix, 0) == 0 && index &&
            index->hasDirtyData()) {
            return false;
        }
    }
    for (const auto& [key, index] : bloomIndexCache_) {
        if (key.rfind(auxiliaryPrefix, 0) == 0 && index &&
            index->hasDirtyData()) {
            return false;
        }
    }
    if (auto it = toastPageAllocators_.find(toastKey);
        it != toastPageAllocators_.end() && pageCacheDirty(it->second)) {
        return false;
    }
    if (auto it = toastIndexes_.find(toastKey);
        it != toastIndexes_.end() && it->second &&
        it->second->hasDirtyPages()) {
        return false;
    }

    if (auto it = pageAllocators_.find(tableKey);
        it != pageAllocators_.end()) {
        if (it->second && it->second->bufferPool()) {
            it->second->bufferPool()->invalidateAll();
        }
        pageAllocators_.erase(it);
    }
    pkIndexCache_.erase(tableKey);
    for (auto it = secondaryIndexCache_.begin();
         it != secondaryIndexCache_.end();) {
        if (it->first.rfind(secondaryPrefix, 0) == 0)
            it = secondaryIndexCache_.erase(it);
        else
            ++it;
    }
    for (auto it = hashIndexCache_.begin(); it != hashIndexCache_.end();) {
        if (it->first.rfind(auxiliaryPrefix, 0) == 0)
            it = hashIndexCache_.erase(it);
        else
            ++it;
    }
    for (auto it = bloomIndexCache_.begin();
         it != bloomIndexCache_.end();) {
        if (it->first.rfind(auxiliaryPrefix, 0) == 0)
            it = bloomIndexCache_.erase(it);
        else
            ++it;
    }
    if (auto it = toastPageAllocators_.find(toastKey);
        it != toastPageAllocators_.end()) {
        if (it->second && it->second->bufferPool()) {
            it->second->bufferPool()->invalidateAll();
        }
        toastPageAllocators_.erase(it);
    }
    toastIndexes_.erase(toastKey);
    {
        std::lock_guard<std::mutex> lock(spGiSTMutex_);
        for (auto it = spGiSTCache_.begin(); it != spGiSTCache_.end();) {
            if (it->first.rfind(secondaryPrefix, 0) == 0)
                it = spGiSTCache_.erase(it);
            else
                ++it;
        }
    }
    return true;
}

void StorageEngine::pruneMissingDatabaseCaches() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::set<std::string> stale;
    const auto collectDatabase = [&stale, this](const std::string& key,
                                                char separator) {
        const size_t pos = key.find(separator);
        const std::string dbname = pos == std::string::npos ? key : key.substr(0, pos);
        if (!dbname.empty() && !databaseExists(dbname)) stale.insert(dbname);
    };
    for (const auto& [dbname, _] : commitLogs_) {
        if (!databaseExists(dbname)) stale.insert(dbname);
    }
    for (const auto& [dbname, _] : walManagers_) {
        if (!databaseExists(dbname)) stale.insert(dbname);
    }
    for (const auto& [dbname, _] : lastCheckpointLsns_) {
        if (!databaseExists(dbname)) stale.insert(dbname);
    }
    for (const auto& [key, _] : pageAllocators_) collectDatabase(key, '/');
    for (const auto& [key, _] : fsmCache_) collectDatabase(key, '/');
    for (const auto& [key, _] : vmCache_) collectDatabase(key, '/');
    for (const auto& [key, _] : pkIndexCache_) collectDatabase(key, '/');
    for (const auto& [key, _] : secondaryIndexCache_) collectDatabase(key, '/');
    for (const auto& [key, _] : hashIndexCache_) collectDatabase(key, '.');
    for (const auto& [key, _] : bloomIndexCache_) collectDatabase(key, '.');
    for (const auto& [key, _] : toastPageAllocators_) collectDatabase(key, ':');
    for (const auto& [key, _] : toastIndexes_) collectDatabase(key, ':');
    for (const auto& [key, _] : spGiSTCache_) collectDatabase(key, '/');
    for (const auto& dbname : stale) closeDatabaseCaches(dbname);
}

FreeSpaceMap* StorageEngine::getFSM(const std::string& dbname,
                                     const std::string& tablename) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + "/" + tablename;
    auto it = fsmCache_.find(key);
    if (it != fsmCache_.end()) return it->second.get();

    auto fsm = std::make_unique<FreeSpaceMap>(fsmPath(dbname, tablename).string());
    fsm->open();
    FreeSpaceMap* ptr = fsm.get();
    fsmCache_[key] = std::move(fsm);
    return ptr;
}

void StorageEngine::closeAllFSM() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    fsmCache_.clear();
}

VisibilityMap* StorageEngine::getVM(const std::string& dbname,
                                     const std::string& tablename) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + "/" + tablename;
    auto it = vmCache_.find(key);
    if (it != vmCache_.end()) return it->second.get();

    auto vm = std::make_unique<VisibilityMap>(vmPath(dbname, tablename).string());
    vm->open();
    VisibilityMap* ptr = vm.get();
    vmCache_[key] = std::move(vm);
    return ptr;
}

void StorageEngine::closeAllVM() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    vmCache_.clear();
}

CommitLog* StorageEngine::getCommitLog(const std::string& dbname) const {
    // commitLogs_ is a mutable shared map; lock it (cacheMutex_ is recursive,
    // so callers that already hold it are fine).
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto it = commitLogs_.find(dbname);
    if (it != commitLogs_.end()) return it->second.get();

    auto clog = std::make_unique<CommitLog>(dbPath(dbname).string());
    CommitLog* ptr = clog.get();
    commitLogs_[dbname] = std::move(clog);
    return ptr;
}

void StorageEngine::closeAllCommitLogs() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    commitLogs_.clear();
}

int64_t StorageEngine::encodeRid(uint32_t pageId, uint16_t slotId) {
    return static_cast<int64_t>((static_cast<uint64_t>(pageId) << 32) | static_cast<uint64_t>(slotId));
}

void StorageEngine::decodeRid(int64_t rid, uint32_t& pageId, uint16_t& slotId) {
    uint64_t urid = static_cast<uint64_t>(rid);
    pageId = static_cast<uint32_t>(urid >> 32);
    slotId = static_cast<uint16_t>(urid & 0xFFFF);
}

static std::string ssiRidKey(const std::string& dbname,
                             const std::string& tablename,
                             int64_t rid) {
    return dbname + "\x1f" + tablename + "\x1f" + std::to_string(rid);
}

class ActiveReferentialRows {
public:
    ActiveReferentialRows(std::set<std::string>& active,
                          std::vector<std::string> rows)
        : active_(active), rows_(std::move(rows)) {
        for (const auto& row : rows_) active_.insert(row);
    }

    ~ActiveReferentialRows() {
        for (const auto& row : rows_) active_.erase(row);
    }

    ActiveReferentialRows(const ActiveReferentialRows&) = delete;
    ActiveReferentialRows& operator=(const ActiveReferentialRows&) = delete;

private:
    std::set<std::string>& active_;
    std::vector<std::string> rows_;
};

static std::string ssiRelationKey(const std::string& dbname,
                                  const std::string& tablename) {
    return dbname + "\x1f" + tablename;
}

static std::string ssiPageKey(const std::string& dbname,
                              const std::string& tablename,
                              uint32_t pageId) {
    return dbname + "\x1f" + tablename + "\x1fpage\x1f" + std::to_string(pageId);
}

bool StorageEngine::forEachRow(const std::string& dbname, const std::string& tablename,
                                const std::function<void(uint32_t, uint16_t, const char*, size_t)>& callback,
                                const ReadView* readView,
                                const std::vector<std::string>& targetPartitions,
                                bool registerSiread,
                                bool indexMaintenanceView) const {
    if (!indexMaintenanceView && transactionContext().inTransaction &&
        dbname == transactionContext().txnDB) {
        transactionContext().hasRead = true;
    }
    const ReadView* rv = readView;
    ReadView autocommitView;
    if (indexMaintenanceView) {
        rv = nullptr;
    } else if (!rv && transactionContext().inTransaction &&
               transactionContext().txnDB == dbname) {
        rv = &transactionContext().readView;
    } else if (!rv) {
        // Autocommit readers still need MVCC filtering: transactional DELETE
        // retains the dead tuple until VACUUM, so a sequential scan must not
        // expose a committed xmax merely because no explicit transaction is
        // active on this backend.
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions_.empty()
            ? autocommitView.lowLimitId : *activeTransactions_.begin();
        autocommitView.activeTxnIds = activeTransactions_;
        autocommitView.subTxnIds.clear();
        autocommitView.commitLog = getCommitLog(dbname);
        rv = &autocommitView;
    }

    TableSchema tbl = getTableSchema(dbname, tablename);

    // A relation-level SIREAD marker is deliberately acquired even when the
    // scan returns no rows.  It is conservative (and therefore may reduce
    // serializable concurrency), but it closes the correctness hole where a
    // concurrent INSERT could otherwise evade row-level SSI tracking.
    if (registerSiread && transactionContext().inTransaction &&
        transactionContext().txnDB == dbname &&
        transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        const std::string relation = ssiRelationKey(dbname, tablename);
        transactionContext().txnReadRelations.insert(relation);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadRelations_[transactionContext().currentTxnId].insert(relation);
    }

    // Helper: visibility check, SSI tracking, header stripping, then callback
    const CommitLog* indexCommitLog =
        indexMaintenanceView ? getCommitLog(dbname) : nullptr;
    std::set<uint64_t> indexActiveTransactions;
    if (indexMaintenanceView) {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        for (uint64_t xid : activeTransactions_) {
            const auto database = activeTransactionDatabases_.find(xid);
            if (database != activeTransactionDatabases_.end() &&
                database->second == dbname) {
                indexActiveTransactions.insert(xid);
            }
        }
    }
    const auto belongsInPhysicalIndex = [
        indexCommitLog, &indexActiveTransactions,
        fmtVer = tbl.formatVersion
    ](const char* data, size_t len) {
        if (!usesHeapTupleHeader(fmtVer)) return true;
        if (!data || len < sizeof(HeapTupleHeaderData)) return false;

        const auto* tuple = castHeapHeader(data);
        const uint64_t xmin = tuple->t_fields.t_xmin;
        if (xminInvalid(tuple)) return false;
        if (xmin != 0 && indexCommitLog) {
            const auto status =
                indexCommitLog->getStatus(static_cast<TxnId>(xmin));
            if (status == CommitLog::Status::Aborted) return false;
            if (status == CommitLog::Status::InProgress &&
                !indexActiveTransactions.count(xmin) &&
                !xminCommitted(tuple)) {
                // Missing/truncated CLOG also decodes as IN_PROGRESS. Only a
                // live backend or a committed hint proves that such an xmin
                // still owns an eagerly inserted index entry.
                return false;
            }
        }

        const uint64_t xmax = tuple->t_fields.t_xmax;
        if (xmax == 0 || xmaxInvalid(tuple) || xmaxIsLock(tuple)) return true;
        if (!indexCommitLog) {
            return !indexActiveTransactions.count(xmax) &&
                !xmaxCommitted(tuple);
        }

        const auto status =
            indexCommitLog->getStatus(static_cast<TxnId>(xmax));
        if (status == CommitLog::Status::Aborted) return true;
        if (status == CommitLog::Status::Committed ||
            status == CommitLog::Status::SubCommitted) {
            return false;
        }
        // An active delete/update has already removed this version's entry.
        // An orphan IN_PROGRESS xmax is treated like an aborted delete unless
        // its committed hint proves otherwise.
        return !indexActiveTransactions.count(xmax) &&
            !xmaxCommitted(tuple);
    };

    auto emitRow = [
        &callback, rv, this, dbname, tablename, registerSiread,
        indexMaintenanceView, &belongsInPhysicalIndex,
        fmtVer = tbl.formatVersion, natts = tbl.len
    ](uint32_t pid, uint16_t sid, const char* data, size_t len) {
        if (len == 0) return;
        size_t hdrLen = rowHeaderSize(fmtVer, natts);
        if (len <= hdrLen) return;
        if (indexMaintenanceView) {
            if (!belongsInPhysicalIndex(data, len)) return;
        } else if (rv) {
            if (!rv->isVisible(data, len, fmtVer)) return;
        }
        if (registerSiread && this->transactionContext().inTransaction &&
            this->transactionContext().txnDB == dbname &&
            this->transactionContext().txnIsolationLevel ==
                IsolationLevel::SERIALIZABLE) {
            int64_t rid = this->encodeRid(pid, sid);
            std::string key = ssiRidKey(dbname, tablename, rid);
            std::string page = ssiPageKey(dbname, tablename, pid);
            this->transactionContext().txnReadRids.insert(key);
            this->transactionContext().txnReadPages.insert(page);
            std::lock_guard<std::mutex> lock(ssiMutex_);
            ssiReadSets_[this->transactionContext().currentTxnId].insert(std::move(key));
            ssiReadPages_[this->transactionContext().currentTxnId].insert(std::move(page));
        }
        size_t off = dataOffset(fmtVer, natts);
        if (usesHeapTupleHeader(fmtVer)) {
            const auto* htup = castHeapHeader(data);
            off = htup->t_hoff;
        }
        if (off >= len) return;
        // Publish the rid for condition evaluation (IS NULL / comparisons)
        // without touching the extraction-scope null binding.
        const int64_t condRid = this->encodeRid(pid, sid);
        g_condNullEngine = this; g_condNullRid = condRid;
        g_condNullTable = tablename; g_condNullDb = dbname;
        callback(pid, sid, data + off, len - off);
        g_condNullEngine = nullptr; g_condNullRid = -1;
        g_condNullTable.clear(); g_condNullDb.clear();
    };

    if (tbl.partitionType != TableSchema::PartitionType::None) {
        // Iterate physical leaves, including RANGE/LIST DEFAULT partitions
        // and hash subpartitions.  targetPartitions contains top-level names
        // produced by pruning, so all of a selected partition's leaves remain
        // visible.
        for (const auto& leaf : partitionLeaves(tbl)) {
            if (!targetPartitions.empty() &&
                std::find(targetPartitions.begin(), targetPartitions.end(),
                          leaf.partition) == targetPartitions.end()) {
                continue;
            }
            const auto path = leaf.subPartition.empty()
                ? partitionDataPath(dbname, tablename, leaf.partition)
                : partitionDataPath(dbname, tablename, leaf.partition,
                                    leaf.subPartition);
            auto ppa = std::make_unique<PageAllocator>(
                path.string(), tbl.rowSize(),
                pageSizeForFormatVersion(tbl.formatVersion),
                tbl.formatVersion);
            if (!ppa->open()) return false;
            const uint32_t pageCount = ppa->numPages();
            for (uint32_t pageId = 1; pageId < pageCount; ++pageId) {
                if (!lockManager_.pageLockShared(
                        dbname, tablename, pageId)) return false;
                char* buffer = ppa->fetchPage(pageId);
                if (!buffer) {
                    lockManager_.pageUnlock(dbname, tablename, pageId);
                    return false;
                }
                PageWrapper page(
                    buffer, ppa->pageSize(), tbl.formatVersion);
                page.forEachLive(
                    [&emitRow, pageId](uint16_t slotId, const char* data,
                                       size_t length) {
                        emitRow(pageId, slotId, data, length);
                    });
                ppa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
            }
            ppa->close();
        }
        return true;
    }

    PageAllocator* pa = getPageAllocator(dbname, tablename);
    if (!pa) return false;
    uint32_t np = pa->numPages();
    for (uint32_t pid = 1; pid < np; ++pid) {
        if (!lockManager_.pageLockShared(dbname, tablename, pid)) return false;
        char* buf = pa->fetchPage(pid);
        if (!buf) {
            lockManager_.pageUnlock(dbname, tablename, pid);
            return false;
        }
        PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
        page.forEachLive([&emitRow, pid](uint16_t sid, const char* data, size_t len) {
            emitRow(pid, sid, data, len);
        });
        pa->unpinPage(pid);
        lockManager_.pageUnlock(dbname, tablename, pid);
    }
    return true;
}

bool StorageEngine::forEachVisibleRow(
    const std::string& dbname, const std::string& tablename,
    const std::string& command,
    const std::function<void(uint32_t, uint16_t, const char*, size_t)>& callback,
    const ReadView* readView,
    const std::vector<std::string>& targetPartitions) const {
    const TableSchema tbl = getTableSchema(dbname, tablename);
    const std::string user = StorageEngine::getRLSUser();

    // The frontend installs the authenticated username before execution. An
    // absent identity is still kept on the policy path and therefore cannot
    // bypass an enabled RLS table.
    if (!shouldEnforceRLS(tbl, user)) {
        return forEachRow(dbname, tablename, callback, readView, targetPartitions);
    }

    const auto policies = getApplicablePolicies(dbname, tablename, command, user);
    // RLS is default-deny when no applicable policy exists. This is essential
    // for source scans: an empty policy list must never mean unrestricted data.
    if (policies.empty()) return true;

    struct VisibleRow {
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        std::string data;
    };
    std::vector<VisibleRow> visible;
    bool evaluationError = false;
    if (!forEachRow(dbname, tablename,
               [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
        if (evaluationError) return;
        const std::string row(data, len);
        std::map<std::string, std::string> values;
        std::map<std::string, std::string> typeHints;
        for (size_t i = 0; i < tbl.len; ++i) {
            const std::string value = extractColumnValueStatic(row, tbl, i);
            values[tbl.cols[i].dataName] = value;
            typeHints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
        }

        const bool allowed = evaluateRlsPolicies(
            policies, false, values, typeHints, dbname, user, evaluationError);
        if (allowed) visible.push_back({pageId, slotId, row});
    }, readView, targetPartitions)) return false;

    if (evaluationError) return false;
    for (const auto& row : visible) {
        callback(row.pageId, row.slotId, row.data.data(), row.data.size());
    }
    return true;
}

bool StorageEngine::rlsAppliesTo(const std::string& dbname,
                                  const std::string& tablename) const {
    return shouldEnforceRLS(getTableSchema(dbname, tablename),
                             StorageEngine::getRLSUser());
}

bool StorageEngine::forEachRowPageRange(
    const std::string& dbname, const std::string& tablename,
    uint32_t firstPage, uint32_t endPage,
    const std::function<void(uint32_t, uint16_t, const char*, size_t)>& callback,
    const ReadView* readView) const {
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        transactionContext().hasRead = true;
    }
    TableSchema tbl = getTableSchema(dbname, tablename);
    if (tbl.partitionType != TableSchema::PartitionType::None || firstPage >= endPage)
        return true;

    // Workers share the engine's page allocator.  BufferPool operations are
    // internally synchronized and the page lock prevents a writer from
    // changing a pinned page while its callback is reading it.  Using the
    // shared allocator is important: a private file descriptor would miss
    // dirty pages that have not reached disk yet.
    PageAllocator* allocator = getPageAllocator(dbname, tablename);
    if (!allocator) return false;

    ReadView autocommitView;
    const ReadView* rv = readView;
    if (!rv && transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        rv = &transactionContext().readView;
    } else if (!rv) {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions_.empty()
            ? autocommitView.lowLimitId : *activeTransactions_.begin();
        autocommitView.activeTxnIds = activeTransactions_;
        autocommitView.subTxnIds.clear();
        autocommitView.commitLog = getCommitLog(dbname);
        rv = &autocommitView;
    }
    const uint32_t pageCount = allocator->numPages();
    const uint32_t lastPage = std::min(endPage, pageCount);
    const uint32_t fmtVer = tbl.formatVersion;
    const size_t natts = tbl.len;

    auto emitRow = [&callback, rv, fmtVer, natts](uint32_t pid, uint16_t sid,
                                                   const char* data, size_t len) {
        if (len == 0) return;
        const size_t hdrLen = rowHeaderSize(fmtVer, natts);
        if (len <= hdrLen) return;
        if (rv && !rv->isVisible(data, len, fmtVer)) return;
        size_t offset = dataOffset(fmtVer, natts);
        if (usesHeapTupleHeader(fmtVer)) offset = castHeapHeader(data)->t_hoff;
        if (offset >= len) return;
        callback(pid, sid, data + offset, len - offset);
    };

    for (uint32_t pid = std::max<uint32_t>(1, firstPage); pid < lastPage; ++pid) {
        if (!lockManager_.pageLockShared(dbname, tablename, pid)) return false;
        char* buf = allocator->fetchPage(pid);
        if (!buf) {
            lockManager_.pageUnlock(dbname, tablename, pid);
            return false;
        }
        PageWrapper page(buf, allocator->pageSize(), tbl.formatVersion);
        page.forEachLive([&emitRow, pid](uint16_t sid, const char* data, size_t len) {
            emitRow(pid, sid, data, len);
        });
        allocator->unpinPage(pid);
        lockManager_.pageUnlock(dbname, tablename, pid);
    }
    return true;
}

bool StorageEngine::readRowByRid(PageAllocator* pa, int64_t rid, std::string& rowBuffer,
                                  const TableSchema& tbl) const {
    return readRowByRid(pa, rid, rowBuffer, tbl, nullptr);
}

bool StorageEngine::readRowByRid(PageAllocator* pa, int64_t rid,
                                  std::string& rowBuffer,
                                  const TableSchema& tbl,
                                  std::vector<bool>* nullColumns) const {
    if (!pa) return false;
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rid, pageId, slotId);
    char* buf = pa->fetchPage(pageId);
    if (!buf) return false;
    PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
    const char* data = nullptr;
    size_t len = 0;
    bool ok = page.read(slotId, data, len);
    if (ok && nullColumns) {
        nullColumns->assign(tbl.len, false);
        if (usesHeapTupleHeader(tbl.formatVersion) &&
            len >= sizeof(HeapTupleHeaderData)) {
            const auto* header = castHeapHeader(data);
            for (size_t i = 0; i < tbl.len; ++i) {
                (*nullColumns)[i] =
                    dbms::isNull(header, static_cast<int>(i));
            }
        }
    }
    pa->unpinPage(pageId);
    if (!ok) return false;
    rowBuffer = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
    return true;
}

bool StorageEngine::readVisibleRowByRid(const std::string& dbname, PageAllocator* pa,
                                         int64_t rid, std::string& rowBuffer,
                                         const TableSchema& tbl,
                                         const ReadView* readView,
                                         bool* readFailed) const {
    if (readFailed) *readFailed = false;
    if (!pa) {
        if (readFailed) *readFailed = true;
        return false;
    }
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rid, pageId, slotId);
    char* buf = pa->fetchPage(pageId);
    if (!buf) {
        if (readFailed) *readFailed = true;
        return false;
    }
    PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
    const char* data = nullptr;
    size_t len = 0;
    const bool ok = page.read(slotId, data, len);
    bool visible = ok;
    ReadView autocommitView;
    const ReadView* rv = readView;
    if (!rv && transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        rv = &transactionContext().readView;
    } else if (!rv) {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions_.empty()
            ? autocommitView.lowLimitId : *activeTransactions_.begin();
        autocommitView.activeTxnIds = activeTransactions_;
        autocommitView.subTxnIds.clear();
        autocommitView.commitLog = getCommitLog(dbname);
        rv = &autocommitView;
    }
    if (visible && rv) {
        visible = rv->isVisible(data, len, tbl.formatVersion);
    }
    if (visible) {
        rowBuffer = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
    }
    pa->unpinPage(pageId);
    return visible;
}

bool StorageEngine::readCurrentRowByRid(
    const std::string& dbname, const std::string& tablename,
    int64_t startRid, const TableSchema& tbl, int64_t& currentRid,
    std::string& rowBuffer, bool& readFailed) const {
    readFailed = false;
    rowBuffer.clear();
    PageAllocator* allocator = getPageAllocator(dbname, tablename);
    if (!allocator) {
        readFailed = true;
        return false;
    }

    ReadView autocommitView;
    const ReadView* view = nullptr;
    if (transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        view = &transactionContext().readView;
    } else {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId =
            TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions_.empty()
            ? autocommitView.lowLimitId : *activeTransactions_.begin();
        autocommitView.activeTxnIds = activeTransactions_;
        autocommitView.commitLog = getCommitLog(dbname);
        view = &autocommitView;
    }

    currentRid = startRid;
    std::set<int64_t> visited;
    for (size_t hop = 0; hop < 64; ++hop) {
        if (!visited.insert(currentRid).second) {
            readFailed = true;
            return false;
        }
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        decodeRid(currentRid, pageId, slotId);
        char* buffer = allocator->fetchPage(pageId);
        if (!buffer) {
            readFailed = true;
            return false;
        }
        PageWrapper page(buffer, allocator->pageSize(), tbl.formatVersion);
        const char* data = nullptr;
        size_t length = 0;
        if (!page.isValid()) {
            allocator->unpinPage(pageId);
            readFailed = true;
            return false;
        }
        if (!page.read(slotId, data, length)) {
            allocator->unpinPage(pageId);
            return false;
        }

        const bool visible = !usesHeapTupleHeader(tbl.formatVersion) ||
            !view || view->isVisible(data, length, tbl.formatVersion);
        if (visible) {
            rowBuffer = stripRowHeader(
                data, length, tbl.formatVersion, tbl.len);
            allocator->unpinPage(pageId);
            return true;
        }
        if (!usesHeapTupleHeader(tbl.formatVersion) ||
            length < sizeof(HeapTupleHeaderData)) {
            allocator->unpinPage(pageId);
            readFailed = usesHeapTupleHeader(tbl.formatVersion);
            return false;
        }

        const ItemPointer next = getCtid(castHeapHeader(data));
        allocator->unpinPage(pageId);
        if (next.pageId == 0 || next.offset == 0) return false;
        const int64_t nextRid = encodeRid(
            next.pageId, static_cast<uint16_t>(next.offset - 1));
        if (nextRid == currentRid) return false;
        currentRid = nextRid;
    }
    readFailed = true;
    return false;
}

bool StorageEngine::readIndexedRowByRid(const std::string& dbname,
                                        const std::string& tablename,
                                        int64_t rid, std::string& rowBuffer,
                                        const TableSchema& tbl,
                                        const ReadView* readView,
                                        bool* readFailed) const {
    if (readFailed) *readFailed = false;
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rid, pageId, slotId);
    (void)slotId;
    if (!lockManager_.pageLockShared(dbname, tablename, pageId)) {
        if (readFailed) *readFailed = true;
        return false;
    }
    PageAllocator* allocator = getPageAllocator(dbname, tablename);
    const bool visible = readVisibleRowByRid(
        dbname, allocator, rid, rowBuffer, tbl, readView, readFailed);
    lockManager_.pageUnlock(dbname, tablename, pageId);
    if (visible && transactionContext().inTransaction &&
        transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE &&
        dbname == transactionContext().txnDB) {
        transactionContext().hasRead = true;
        const std::string key = ssiRidKey(dbname, tablename, rid);
        const std::string page = ssiPageKey(dbname, tablename, pageId);
        transactionContext().txnReadRids.insert(key);
        transactionContext().txnReadPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_[transactionContext().currentTxnId].insert(key);
        ssiReadPages_[transactionContext().currentTxnId].insert(page);
    }
    return visible;
}

bool StorageEngine::isColumnNullByRid(const std::string& dbname,
                                      const std::string& tablename,
                                      int64_t rid, size_t colIdx) const {
    const TableSchema tbl = getTableSchema(dbname, tablename);
    if (colIdx >= tbl.len || !tbl.cols[colIdx].isNull) return false;
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    if (!pa) return false;

    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rid, pageId, slotId);
    char* buf = pa->fetchPage(pageId);
    if (!buf) return false;
    PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
    const char* data = nullptr;
    size_t len = 0;
    const bool ok = page.read(slotId, data, len);
    bool result = false;
    if (ok && usesHeapTupleHeader(tbl.formatVersion) &&
        len >= sizeof(HeapTupleHeaderData)) {
        result = dbms::isNull(castHeapHeader(data), static_cast<int>(colIdx));
    }
    pa->unpinPage(pageId);
    return result;
}

std::string StorageEngine::extractPKValue(const std::string& rowBuffer, const TableSchema& tbl) {
    if (g_condNullEngine && tbl.tablename == g_condNullTable) {
        std::map<std::string, std::string> values;
        auto* engine = const_cast<StorageEngine*>(g_condNullEngine);
        for (size_t i = 0; i < tbl.len; ++i) {
            values[tbl.cols[i].dataName] =
                engine->extractColumnValue(rowBuffer, tbl, i, g_condNullDb);
        }
        return tbl.buildPKValue(values);
    }
    return tbl.buildPKValue(rowBuffer);
}

std::string StorageEngine::extractPKValue(const std::string& rowBuffer,
                                          const TableSchema& tbl,
                                          const std::string& dbname) {
    std::map<std::string, std::string> values;
    for (size_t i = 0; i < tbl.len; ++i) {
        values[tbl.cols[i].dataName] =
            extractColumnValue(rowBuffer, tbl, i, dbname);
    }
    return tbl.buildPKValue(values);
}

BPTree* StorageEngine::getPKIndex(const std::string& dbname, const std::string& tablename) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + "/" + tablename;
    auto it = pkIndexCache_.find(key);
    if (it != pkIndexCache_.end()) {
        if (it->second && !it->second->hasStaleFileGeneration()) {
            return it->second.get();
        }
        pkIndexCache_.erase(it);
    }

    auto tree = std::make_unique<BPTree>(indexPath(dbname, tablename));
    if (tree->open()) {
        BPTree* ptr = tree.get();
        pkIndexCache_[key] = std::move(tree);
        return ptr;
    }
    return nullptr;
}

void StorageEngine::closeAllIndexes() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    pkIndexCache_.clear();
    secondaryIndexCache_.clear();
}

// ========================================================================
// Secondary Index
// ========================================================================
std::filesystem::path StorageEngine::secondaryIndexPath(const std::string& dbname,
                                                         const std::string& tablename,
                                                         const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".idx");
}

std::filesystem::path StorageEngine::secondaryIndexMetaPath(const std::string& dbname,
                                                             const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".secidx");
}

namespace {
std::filesystem::path namedIndexMetaPath(const StorageEngine& engine,
                                         const std::string& dbname,
                                         const std::string& tablename) {
    return engine.dbPath(dbname) / (tablename + ".idxnames");
}

bool readIndexMetadata(const std::filesystem::path& path, std::string& contents) {
    std::error_code error;
    if (!std::filesystem::exists(path, error)) return !error;
    if (!std::filesystem::is_regular_file(path, error) || error) return false;
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    contents.assign(std::istreambuf_iterator<char>(input), std::istreambuf_iterator<char>());
    return !input.bad();
}

bool writeIndexMetadata(const std::filesystem::path& path, const std::string& contents) {
    return index_file::writeAtomically(path, contents);
}

constexpr const char* UNIQUE_INDEX_METADATA_PREFIX =
    "DBMS_UNIQUE_INDEX_V1:";

bool consumeUniqueIndexMetadataPrefix(std::string& definition) {
    if (definition.rfind(UNIQUE_INDEX_METADATA_PREFIX, 0) != 0) {
        return false;
    }
    definition.erase(0, std::char_traits<char>::length(
                            UNIQUE_INDEX_METADATA_PREFIX));
    return true;
}
}

bool StorageEngine::registerIndexName(const std::string& dbname,
                                      const std::string& tablename,
                                      const std::string& indexName,
                                      const std::string& accessMethod,
                                      const std::string& key) {
    if (indexName.empty() || tablename.empty() || accessMethod.empty() || key.empty() ||
        indexName.find_first_of("\t\r\n") != std::string::npos ||
        accessMethod.find_first_of("\t\r\n") != std::string::npos ||
        key.find_first_of("\t\r\n") != std::string::npos) return false;
    std::vector<NamedIndexInfo> entries;
    std::string contents;
    const auto path = namedIndexMetaPath(*this, dbname, tablename);
    if (!readIndexMetadata(path, contents)) return false;
    std::istringstream in(contents);
    std::string name;
    while (std::getline(in, name, '\t')) {
        NamedIndexInfo entry;
        entry.name = name;
        if (!std::getline(in, entry.accessMethod, '\t') ||
            !std::getline(in, entry.key)) return false;
        if (entry.name != indexName) entries.push_back(std::move(entry));
    }
    entries.push_back({indexName, accessMethod, key});
    std::ostringstream serialized;
    for (const auto& entry : entries) {
        serialized << entry.name << '\t' << entry.accessMethod << '\t' << entry.key << '\n';
    }
    return writeIndexMetadata(path, serialized.str());
}

std::optional<StorageEngine::NamedIndexInfo> StorageEngine::getNamedIndex(
    const std::string& dbname, const std::string& tablename,
    const std::string& indexName) const {
    std::ifstream in(namedIndexMetaPath(*this, dbname, tablename));
    std::string name;
    while (std::getline(in, name, '\t')) {
        NamedIndexInfo entry;
        entry.name = name;
        if (!std::getline(in, entry.accessMethod, '\t') ||
            !std::getline(in, entry.key)) break;
        if (entry.name == indexName) return entry;
    }
    return std::nullopt;
}

bool StorageEngine::unregisterIndexName(const std::string& dbname,
                                        const std::string& tablename,
                                        const std::string& indexName) {
    const auto path = namedIndexMetaPath(*this, dbname, tablename);
    std::string contents;
    if (!readIndexMetadata(path, contents)) return false;
    std::istringstream in(contents);
    std::vector<NamedIndexInfo> entries;
    std::string name;
    bool removed = false;
    while (std::getline(in, name, '\t')) {
        NamedIndexInfo entry;
        entry.name = name;
        if (!std::getline(in, entry.accessMethod, '\t') ||
            !std::getline(in, entry.key)) return false;
        if (entry.name == indexName) { removed = true; continue; }
        entries.push_back(std::move(entry));
    }
    if (!in && entries.empty() && !removed) return false;
    std::ostringstream serialized;
    for (const auto& entry : entries) {
        serialized << entry.name << '\t' << entry.accessMethod << '\t' << entry.key << '\n';
    }
    if (!writeIndexMetadata(path, serialized.str())) return false;
    return removed;
}

// ========================================================================
// Hash Index
// ========================================================================
std::filesystem::path StorageEngine::hashIndexPath(const std::string& dbname,
                                                    const std::string& tablename,
                                                    const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".hidx");
}

std::filesystem::path StorageEngine::hashIndexMetaPath(const std::string& dbname,
                                                        const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".hashidx");
}

std::vector<std::string> StorageEngine::getHashIndexedColumns(const std::string& dbname,
                                                               const std::string& tablename) const {
    return readHashidxLines(dbname, tablename);
}

std::vector<std::string> StorageEngine::readHashidxLines(const std::string& dbname,
                                                         const std::string& tablename) const {
    const std::string key = dbname + "/" + tablename;
    {
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        auto it = hashidxLinesCache_.find(key);
        if (it != hashidxLinesCache_.end()) return it->second;
    }
    std::vector<std::string> lines;
    std::ifstream in(hashIndexMetaPath(dbname, tablename));
    if (in) {
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty()) lines.push_back(line);
        }
    }
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    hashidxLinesCache_.emplace(key, std::move(lines));
    return hashidxLinesCache_[key];
}

void StorageEngine::invalidateHashidxCache(const std::string& dbname,
                                           const std::string& tablename) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    hashidxLinesCache_.erase(dbname + "/" + tablename);
}

HashIndex* StorageEngine::getHashIndex(const std::string& dbname,
                                        const std::string& tablename,
                                        const std::string& colname) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + "." + tablename + "." + colname;
    auto it = hashIndexCache_.find(key);
    if (it != hashIndexCache_.end()) return it->second.get();
    auto idx = std::make_unique<HashIndex>(hashIndexPath(dbname, tablename, colname));
    if (idx->open()) {
        HashIndex* ptr = idx.get();
        hashIndexCache_[key] = std::move(idx);
        return ptr;
    }
    return nullptr;
}

DBStatus StorageEngine::createHashIndex(const std::string& dbname,
                                         const std::string& tablename,
                                         const std::string& colname,
                                         bool /*concurrently*/) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    bool found = false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { found = true; break; }
    }
    if (!found) return DBStatus::INVALID_VALUE;

    std::filesystem::path meta = hashIndexMetaPath(dbname, tablename);
    std::set<std::string> existing;
    {
        std::ifstream in(meta);
        std::string line;
        while (std::getline(in, line)) if (!line.empty()) existing.insert(line);
    }
    if (existing.count(colname)) return DBStatus::OK; // already exists
    existing.insert(colname);

    // Build hash index from existing data
    HashIndex* hidx = getHashIndex(dbname, tablename, colname);
    if (!hidx) return DBStatus::IO_ERROR;
    const std::string cacheKey = dbname + "." + tablename + "." + colname;
    auto discardIndex = [&]() {
        hidx->close();
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        hashIndexCache_.erase(cacheKey);
        std::filesystem::remove(hashIndexPath(dbname, tablename, colname));
    };
    hidx->clear();
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        std::string row(data, len);
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == colname) {
                std::string val = canonicalColumnKeyValue(
                    tbl.cols[i], extractColumnValue(
                                     row, tbl, i, dbname, true));
                if (!val.empty()) {
                    hidx->insert(val, encodeRid(pageId, slotId));
                }
                break;
            }
        }
    })) {
        discardIndex();
        return DBStatus::IO_ERROR;
    }
    if (!hidx->close() || !hidx->open()) {
        discardIndex();
        return DBStatus::IO_ERROR;
    }
    std::ostringstream serializedMeta;
    for (const auto& c : existing) serializedMeta << c << '\n';
    if (!index_file::writeAtomically(meta, serializedMeta.str())) {
        discardIndex();
        return DBStatus::IO_ERROR;
    }
    invalidateHashidxCache(dbname, tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::dropHashIndex(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& colname) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::filesystem::path meta = hashIndexMetaPath(dbname, tablename);
    std::set<std::string> existing;
    {
        std::ifstream in(meta);
        std::string line;
        while (std::getline(in, line)) if (!line.empty()) existing.insert(line);
    }
    existing.erase(colname);
    {
        std::ofstream out(meta, std::ios::trunc);
        for (const auto& c : existing) out << c << '\n';
    }
    invalidateHashidxCache(dbname, tablename);
    std::string key = dbname + "." + tablename + "." + colname;
    hashIndexCache_.erase(key);
    std::filesystem::remove(hashIndexPath(dbname, tablename, colname));
    return DBStatus::OK;
}

