bool StorageEngine::restoreDeletedRowIndexes(
    const std::string& dbname, const std::string& tablename,
    const TableSchema& tbl, const std::string& rowData, int64_t rid,
    std::set<BloomIndex*>& bloomUndoIndexes) {
    bool ok = true;
    const auto containsRid = [rid](const std::vector<int64_t>& values) {
        return std::find(values.begin(), values.end(), rid) != values.end();
    };

    if (tbl.hasPrimaryKey()) {
        BPTree* primary = getPKIndex(dbname, tablename);
        const std::string key = extractPKValue(rowData, tbl, dbname);
        if (!primary || key.empty()) {
            ok = false;
        } else {
            int64_t indexedRid = -1;
            if (primary->search(key, indexedRid)) {
                if (indexedRid != rid) ok = false;
            } else if (!primary->insert(key, rid)) {
                ok = false;
            }
        }
    }

    for (const auto& metadata : getIndexMetadata(dbname, tablename)) {
        EvaluatedIndexEntry entry;
        if (!secondaryIndexEntryFromBuffer(
                *this, metadata, tbl, rowData, dbname, entry)) {
            ok = false;
            continue;
        }
        if (!entry.included || entry.key.empty()) continue;
        BPTree* index = getSecondaryIndex(
            dbname, tablename, metadata.name);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->searchMulti(entry.key)) &&
            !index->insertMulti(entry.key, rid)) {
            ok = false;
        }
    }

    for (const auto& metadata : getCompositeIndexes(dbname, tablename)) {
        EvaluatedIndexEntry entry;
        if (!compositeIndexEntryFromBuffer(
                *this, metadata, tbl, rowData, dbname, entry)) {
            ok = false;
            continue;
        }
        if (!entry.included || entry.key.empty()) continue;
        BPTree* index = getCompositeIndexTree(
            dbname, tablename, metadata.name);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->searchMulti(entry.key)) &&
            !index->insertMulti(entry.key, rid)) {
            ok = false;
        }
    }

    for (const auto& columnName :
         getHashIndexedColumns(dbname, tablename)) {
        size_t columnIndex = tbl.len;
        for (size_t index = 0; index < tbl.len; ++index) {
            if (tbl.cols[index].dataName == columnName) {
                columnIndex = index;
                break;
            }
        }
        if (columnIndex >= tbl.len) {
            ok = false;
            continue;
        }
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname));
        if (value.empty()) continue;
        HashIndex* index = getHashIndex(dbname, tablename, columnName);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->search(value)) && !index->insert(value, rid)) {
            ok = false;
        }
    }

    for (const auto& columnName :
         getBloomIndexedColumns(dbname, tablename)) {
        size_t columnIndex = tbl.len;
        for (size_t index = 0; index < tbl.len; ++index) {
            if (tbl.cols[index].dataName == columnName) {
                columnIndex = index;
                break;
            }
        }
        if (columnIndex >= tbl.len) {
            ok = false;
            continue;
        }
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname));
        if (value.empty()) continue;
        BloomIndex* index = getBloomIndex(dbname, tablename, columnName);
        if (!index) {
            ok = false;
            continue;
        }
        bloomUndoIndexes.insert(index);
        if (!containsRid(index->search(value)) && !index->insert(value, rid)) {
            ok = false;
        }
    }
    return ok;
}

bool StorageEngine::undoDeletedRow(
    const TxnLogEntry& entry,
    std::set<BloomIndex*>& bloomUndoIndexes) {
    if (entry.op != TxnLogEntry::Op::Delete || entry.rowIdx < 0 ||
        entry.rowData.empty() || transactionContext().txnDB.empty()) {
        return false;
    }

    const std::string& dbname = transactionContext().txnDB;
    const std::string& tablename = entry.tableName;
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const TableSchema tbl = getTableSchema(dbname, tablename);
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(entry.rowIdx, pageId, slotId);

    bool heapOk = false;
    bool pageLocked = false;
    if (pa) {
        pageLocked = lockManager_.pageLockExclusive(
            dbname, tablename, pageId);
    }
    if (pa && pageLocked) {
        char* pageBuffer = pa->fetchPage(pageId);
        if (pageBuffer) {
            PageWrapper page(
                pageBuffer, pa->pageSize(), tbl.formatVersion);
            const char* currentData = nullptr;
            size_t currentLength = 0;
            if (page.isValid() &&
                page.read(slotId, currentData, currentLength) &&
                currentLength >=
                    rowHeaderSize(tbl.formatVersion, tbl.len) &&
                stripRowHeader(
                    currentData, currentLength, tbl.formatVersion,
                    tbl.len) == entry.rowData) {
                std::vector<char> stagedBuffer(
                    pageBuffer, pageBuffer + pa->pageSize());
                PageWrapper staged(
                    stagedBuffer.data(), pa->pageSize(),
                    tbl.formatVersion);
                std::string restored = replaceRowData(
                    std::string(currentData, currentLength),
                    entry.rowData, tbl.formatVersion, tbl.len);
                setRowXmax(
                    restored.data(), restored.size(), tbl.formatVersion, 0);
                uint16_t restoredSlot = slotId;
                const bool stagedOk = staged.update(
                    slotId, restored.data(), restored.size(), restoredSlot);
                const Lsn beforeLsn = stagedOk && restoredSlot == slotId
                    ? walPageImage(
                          dbname, tablename, pageId, pageBuffer,
                          pa->pageSize(), true)
                    : INVALID_LSN;
                const Lsn afterLsn = beforeLsn != INVALID_LSN
                    ? walPageImage(
                          dbname, tablename, pageId,
                          stagedBuffer.data(), pa->pageSize(), false)
                    : INVALID_LSN;
                WALManager* wal = getWAL(dbname);
                if (afterLsn != INVALID_LSN && wal &&
                    wal->XLogFlush(afterLsn)) {
                    std::memcpy(
                        pageBuffer, stagedBuffer.data(), pa->pageSize());
                    setPageLsnAndChecksum(pageBuffer, afterLsn);
                    pa->markDirty(pageId);
                    const size_t freePercent =
                        staged.freeSpace() * 100 / pa->pageSize();
                    getFSM(dbname, tablename)->setFreePercent(
                        pageId, static_cast<uint8_t>(freePercent));
                    getVM(dbname, tablename)->setAllVisible(pageId, false);
                    heapOk = pa->flush();
                }
            }
            pa->unpinPage(pageId);
        }
        lockManager_.pageUnlock(dbname, tablename, pageId);
    }

    // DELETE may have failed after removing only a prefix of its indexes.
    // Restore every missing exact key/RID pair even when the heap page is
    // unreadable; the logged OLD image is independent of that page.
    const bool indexesOk = restoreDeletedRowIndexes(
        dbname, tablename, tbl, entry.rowData, entry.rowIdx,
        bloomUndoIndexes);
    return heapOk && indexesOk;
}

// ========================================================================
// Transaction support (row undo log with opt-in DDL snapshots)
// ========================================================================

static void applySessionTempTableCommitActions(StorageEngine& engine,
                                               Session& session,
                                               const std::string& dbname) {
    std::vector<std::string> names;
    names.reserve(session.tempTableOnCommit.size());
    for (const auto& entry : session.tempTableOnCommit) names.push_back(entry.first);

    for (const auto& logicalName : names) {
        if (!session.tempTables.count(logicalName)) {
            session.tempTableOnCommit.erase(logicalName);
            continue;
        }
        const auto actionIt = session.tempTableOnCommit.find(logicalName);
        if (actionIt == session.tempTableOnCommit.end()) continue;
        const std::string physicalName = tempTablePrefix(session, logicalName);
        if (actionIt->second == "delete") {
            engine.truncateTable(dbname, physicalName);
        } else if (actionIt->second == "drop") {
            engine.dropTable(dbname, physicalName);
            session.tempTables.erase(logicalName);
            session.tempTableOnCommit.erase(logicalName);
        }
    }
    session.tempTablesCreatedInTransaction.clear();
}

static void rollbackSessionTempTables(StorageEngine& engine,
                                      Session& session,
                                      const std::string& dbname) {
    const auto created = session.tempTablesCreatedInTransaction;
    for (const auto& logicalName : created) {
        engine.dropTable(dbname, tempTablePrefix(session, logicalName));
        session.tempTables.erase(logicalName);
        session.tempTableOnCommit.erase(logicalName);
    }
    session.tempTablesCreatedInTransaction.clear();
}

namespace {

std::mutex g_databaseTxnLocksMutex;
std::map<std::string, std::shared_ptr<std::shared_mutex>> g_databaseTxnLocks;

std::shared_ptr<std::shared_mutex> databaseTxnLockFor(const std::string& dbname) {
    std::lock_guard<std::mutex> guard(g_databaseTxnLocksMutex);
    auto& lock = g_databaseTxnLocks[dbname];
    if (!lock) lock = std::make_shared<std::shared_mutex>();
    return lock;
}

std::filesystem::path transactionBackupPath(const std::string& dbname, uint64_t xid) {
    return std::filesystem::path(dbname + ".txn_backup." + std::to_string(xid));
}

} // anonymous namespace

DBStatus StorageEngine::beginTransaction(const std::string& dbname) {
    return beginTransaction(dbname, false);
}

void StorageEngine::preserveTransactionBackupOnRollback(bool preserve) {
    auto& context = transactionContext();
    context.preserveBackupOnRollback = preserve;
    if (!preserve || !context.inTransaction || !context.txnBackupPath.empty()) return;

    // Legacy direct callers may opt in after BEGIN. Upgrade their shared
    // database lock before taking the snapshot; the DDL wrapper uses the
    // exclusive begin overload and therefore does not need an upgrade.
    context.databaseSharedLock.reset();
    if (!context.databaseExclusiveLock) {
        context.databaseExclusiveLock = std::make_unique<std::unique_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }
    if (!createTransactionBackup()) {
        context.preserveBackupOnRollback = false;
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock = std::make_unique<std::shared_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }
}

void StorageEngine::registerDdlUndo(std::function<bool()> action) {
    if (!action || !transactionContext().inTransaction) return;
    transactionContext().ddlUndoActions.push_back(std::move(action));
}

void StorageEngine::markTransactionBackupDirty() {
    if (!transactionContext().txnBackupPath.empty()) {
        transactionContext().transactionBackupDirty = true;
    }
}

void StorageEngine::restoreTransactionBackupBeforeRowUndo(bool enable) {
    transactionContext().restoreBackupBeforeRowUndo = enable;
}

bool StorageEngine::hasTransactionBackup() const {
    return !transactionContext().txnBackupPath.empty();
}

bool StorageEngine::transactionBackupDirty() const {
    return transactionContext().transactionBackupDirty;
}

DBStatus StorageEngine::beginTransaction(const std::string& dbname, bool ddlSnapshot) {
    auto& context = transactionContext();
    if (context.inTransaction) {
        // BEGIN inside an active transaction is a warning/no-op in
        // PostgreSQL. Never publish the existing transaction merely because
        // a caller tried to start another one. An exclusive snapshot request
        // cannot safely upgrade the already-held shared database lock, and a
        // transaction may not silently switch databases.
        if (ddlSnapshot || context.txnDB != dbname) {
            return DBStatus::INVALID_VALUE;
        }
        return DBStatus::OK;
    }
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;

    context.databaseTxnMutex = databaseTxnLockFor(dbname);
    if (ddlSnapshot) {
        context.databaseExclusiveLock = std::make_unique<std::unique_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    } else {
        context.databaseSharedLock = std::make_unique<std::shared_lock<std::shared_mutex>>(
            *context.databaseTxnMutex);
    }

    // CatalogManager is lazily persisted and may contain the latest DDL
    // state only in memory.  Persist it before taking the transaction
    // snapshot so a DDL rollback can safely evict/reload the catalog.
    if (catalogService_ && !catalogService_->persistAll()) {
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock.reset();
        context.databaseTxnMutex.reset();
        return DBStatus::IO_ERROR;
    }

    // A ReadView and catalog snapshot are logical, in-memory state; neither
    // requires writing unrelated dirty buffers. Physical DDL rollback
    // snapshots are created later by createTransactionBackup(), which owns
    // the exclusive database lock and performs its own complete cache flush.

    // Assign transaction ID and create ReadView (if needed).
    transactionContext().currentTxnId = TxnIdGenerator::instance().nextTxId();
    if (transactionContext().currentTxnId == 0) {
        context.databaseExclusiveLock.reset();
        context.databaseSharedLock.reset();
        context.databaseTxnMutex.reset();
        return DBStatus::IO_ERROR;
    }
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.insert(transactionContext().currentTxnId);
        activeTransactionDatabases_[transactionContext().currentTxnId] = dbname;
    }
    // Initialize SSI tracking
    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_[transactionContext().currentTxnId].clear();
        ssiWriteSets_[transactionContext().currentTxnId].clear();
        ssiReadRelations_[transactionContext().currentTxnId].clear();
        ssiWriteRelations_[transactionContext().currentTxnId].clear();
        ssiReadPages_[transactionContext().currentTxnId].clear();
        ssiWritePages_[transactionContext().currentTxnId].clear();
        ssiReadIndexPredicates_[transactionContext().currentTxnId].clear();
        ssiWriteIndexKeys_[transactionContext().currentTxnId].clear();
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnHeapWritebackPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();
    if (transactionContext().txnIsolationLevel != IsolationLevel::READ_UNCOMMITTED) {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        transactionContext().readView.creatorTxnId = transactionContext().currentTxnId;
        transactionContext().readView.upLimitId = activeTransactions_.empty() ? transactionContext().currentTxnId : *activeTransactions_.begin();
        transactionContext().readView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        transactionContext().readView.activeTxnIds = activeTransactions_;
        transactionContext().readView.activeTxnIds.erase(transactionContext().currentTxnId);
        transactionContext().readView.subTxnIds.clear();
        transactionContext().readView.subTxnIds.insert(transactionContext().txnSubTxnIds.begin(), transactionContext().txnSubTxnIds.end());
        transactionContext().readView.commitLog = getCommitLog(dbname);
    }

    // Capture catalog snapshot for consistent catalog view within transaction
    captureCatalogSnapshot();

    transactionContext().txnLog.clear();
    transactionContext().specializedIndexTables.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().ddlUndoActions.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().inTransaction = true;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnBackupPath.clear();
    transactionContext().txnDB = dbname;
    return DBStatus::OK;
}

bool StorageEngine::createTransactionBackup() {
    auto& context = transactionContext();
    if (!context.inTransaction || context.txnDB.empty() || context.currentTxnId == 0) {
        return false;
    }
    if (!context.txnBackupPath.empty()) return true;
    const std::string dbname = context.txnDB;
    if (catalogService_ && !catalogService_->persistAll()) return false;

    // The exclusive database lock is acquired by beginTransaction(..., true)
    // before this copy starts. This prevents a physical restore from erasing
    // another backend's committed changes.
    const auto tables = getTableNames(dbname);
    if (!flushDatabaseCaches(dbname)) return false;

    const auto backup = transactionBackupPath(dbname, context.currentTxnId);
    std::error_code ec;
    std::filesystem::remove_all(backup, ec);
    if (!physicalBackup(dbname, backup.string())) {
        std::filesystem::remove_all(backup, ec);
        return false;
    }

    // UNLOGGED relations are intentionally empty after crash recovery. Remove
    // every physical fork/index/TOAST file from the snapshot while retaining
    // their schema and catalog metadata.
    for (const auto& tn : tables) {
        TableSchema ts = getTableSchema(dbname, tn);
        if (!ts.isUnlogged) continue;
        std::filesystem::path relationBackup = backup;
        if (!ts.tablespace.empty() && ts.tablespace != "pg_default") {
            relationBackup /= "tablespaces";
            relationBackup /= ts.tablespace;
        }
        if (!std::filesystem::exists(relationBackup)) continue;
        for (const auto& entry : std::filesystem::directory_iterator(relationBackup)) {
            if (isRelationPhysicalFileName(entry.path().filename().string(), tn)) {
                std::filesystem::remove_all(entry.path(), ec);
                if (ec) {
                    std::filesystem::remove_all(backup, ec);
                    return false;
                }
            }
        }
    }
    context.txnBackupPath = backup.string();
    context.transactionBackupDirty = false;
    context.ddlUndoSizeAtBackup = context.ddlUndoActions.size();
    return true;
}

DBStatus StorageEngine::commitTransaction() {
    if (!transactionContext().inTransaction) return DBStatus::OK;
    lockManager_.setResourceNamespace(transactionContext().txnDB);

    // SSI conflict detection for Serializable isolation
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        std::unique_lock<std::mutex> lock(ssiMutex_);
        bool hasOutgoing = false, hasIncoming = false;

        for (const auto& [otherTxId, otherWriteSet] : ssiWriteSets_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& rid : transactionContext().txnReadRids) {
                if (otherWriteSet.count(rid)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherWritePages] : ssiWritePages_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& page : transactionContext().txnReadPages) {
                if (otherWritePages.count(page)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherWriteKeys] : ssiWriteIndexKeys_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& predicate : transactionContext().txnReadIndexPredicates) {
                for (const auto& key : otherWriteKeys) {
                    if (ssiIndexPredicateMatches(predicate, key)) {
                        hasOutgoing = true;
                        ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                        ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                        break;
                    }
                }
                if (hasOutgoing) break;
            }
            if (hasOutgoing) break;
        }

        // Relation-level SIREAD coverage catches empty scans and predicates
        // whose result set did not contain a row. It is the conservative
        // fallback; non-empty scans use page coverage above.
        for (const auto& [otherTxId, otherWriteRelations] : ssiWriteRelations_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& relation : transactionContext().txnReadRelations) {
                if (otherWriteRelations.count(relation)) {
                    hasOutgoing = true;
                    ssiOutEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiInEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasOutgoing) break;
        }

        for (const auto& [otherTxId, otherReadSet] : ssiReadSets_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& rid : transactionContext().txnWrittenRids) {
                if (otherReadSet.count(rid)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadPages] : ssiReadPages_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& page : transactionContext().txnWrittenPages) {
                if (otherReadPages.count(page)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadPredicates] : ssiReadIndexPredicates_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& key : transactionContext().txnWrittenIndexKeys) {
                for (const auto& predicate : otherReadPredicates) {
                    if (ssiIndexPredicateMatches(predicate, key)) {
                        hasIncoming = true;
                        ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                        ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                        break;
                    }
                }
                if (hasIncoming) break;
            }
            if (hasIncoming) break;
        }

        for (const auto& [otherTxId, otherReadRelations] : ssiReadRelations_) {
            if (otherTxId == transactionContext().currentTxnId) continue;
            for (const auto& relation : transactionContext().txnWrittenRelations) {
                if (otherReadRelations.count(relation)) {
                    hasIncoming = true;
                    ssiInEdges_[transactionContext().currentTxnId].insert(otherTxId);
                    ssiOutEdges_[otherTxId].insert(transactionContext().currentTxnId);
                    break;
                }
            }
            if (hasIncoming) break;
        }

        if (hasOutgoing && hasIncoming) {
            // Dangerous structure detected - must abort
            uint64_t abortedId = transactionContext().currentTxnId;
            ssiReadSets_.erase(abortedId);
            ssiWriteSets_.erase(abortedId);
            ssiReadRelations_.erase(abortedId);
            ssiWriteRelations_.erase(abortedId);
            ssiReadPages_.erase(abortedId);
            ssiWritePages_.erase(abortedId);
            ssiReadIndexPredicates_.erase(abortedId);
            ssiWriteIndexKeys_.erase(abortedId);
            ssiOutEdges_.erase(abortedId);
            for (auto& [k, v] : ssiInEdges_) v.erase(abortedId);
            ssiInEdges_.erase(abortedId);
            for (auto& [k, v] : ssiOutEdges_) v.erase(abortedId);
            transactionContext().txnReadRids.clear();
            transactionContext().txnWrittenRids.clear();
            transactionContext().txnReadRelations.clear();
            transactionContext().txnWrittenRelations.clear();
            transactionContext().txnReadPages.clear();
            transactionContext().txnWrittenPages.clear();
            transactionContext().txnReadIndexPredicates.clear();
            transactionContext().txnWrittenIndexKeys.clear();
            // rollbackTransaction() performs its own SSI cleanup and must
            // acquire ssiMutex_.  Release the detection lock first to avoid
            // self-deadlocking on the serialization-failure path.
            lock.unlock();
            rollbackTransaction();
            return DBStatus::SERIALIZATION_FAILURE;
        }

        // Keep committed SSI coverage while another serializable transaction
        // is active; a later committer may need the completed transaction's
        // read/write edges to finish dangerous-structure detection.  The last
        // transaction out clears the global history below.
        transactionContext().txnReadRids.clear();
        transactionContext().txnWrittenRids.clear();
        transactionContext().txnReadRelations.clear();
        transactionContext().txnWrittenRelations.clear();
        transactionContext().txnReadPages.clear();
        transactionContext().txnWrittenPages.clear();
        transactionContext().txnReadIndexPredicates.clear();
        transactionContext().txnWrittenIndexKeys.clear();
    }

    // Run deferred CHECK constraints queued for this transaction before committing.
    {
        auto it = transactionContext().deferredChecks.find(transactionContext().currentTxnId);
        if (it != transactionContext().deferredChecks.end()) {
            for (const auto& dc : it->second) {
                if (!runDeferredCheck(dc)) {
                    rollbackTransaction();
                    return DBStatus::INVALID_VALUE;
                }
            }
            transactionContext().deferredChecks.erase(it);
        }
    }

    // Full-text, GIN, GiST, SP-GiST and BRIN use whole-file sidecars.  Rebuild
    // each relation once at the transaction boundary instead of once per row.
    // Hold an outer IX token through visibility publication: in this lock
    // manager IX is physically exclusive, so another writer cannot change the
    // heap between the snapshot scan and this transaction becoming visible.
    auto& committingContext = transactionContext();
    for (const auto& entry : committingContext.txnLog) {
        committingContext.specializedIndexTables.insert(entry.tableName);
    }
    for (const auto& tableName : committingContext.specializedIndexTables) {
        if (!tableExists(committingContext.txnDB, tableName)) continue;
        if (!lockManager_.lockIntentExclusive(tableName)) {
            rollbackTransaction();
            return DBStatus::LOCK_CONFLICT;
        }
    }
    if (!committingContext.specializedIndexTables.empty()) {
        const ReadView savedReadView = committingContext.readView;
        const IsolationLevel savedIsolation =
            committingContext.txnIsolationLevel;
        {
            std::lock_guard<std::mutex> lock(globalTxnMutex_);
            committingContext.readView.creatorTxnId =
                committingContext.currentTxnId;
            committingContext.readView.lowLimitId =
                TxnIdGenerator::instance().maxCommittedTxId() + 1;
            committingContext.readView.upLimitId =
                activeTransactions_.empty()
                    ? committingContext.readView.lowLimitId
                    : *activeTransactions_.begin();
            committingContext.readView.activeTxnIds = activeTransactions_;
            committingContext.readView.activeTxnIds.erase(
                committingContext.currentTxnId);
            committingContext.readView.subTxnIds.clear();
            committingContext.readView.commitLog =
                getCommitLog(committingContext.txnDB);
        }
        // The maintenance scan is an implementation detail, not a new user
        // predicate read that participates in SSI conflict detection.
        committingContext.txnIsolationLevel = IsolationLevel::READ_COMMITTED;
        bool specializedIndexesOk = true;
        for (const auto& tableName :
             committingContext.specializedIndexTables) {
            if (!tableExists(committingContext.txnDB, tableName)) continue;
            if (!rebuildSpecializedIndexes(
                    committingContext.txnDB, tableName,
                    /*clearDirtyState=*/false)) {
                specializedIndexesOk = false;
                break;
            }
        }
        committingContext.readView = savedReadView;
        committingContext.txnIsolationLevel = savedIsolation;
        if (!specializedIndexesOk) {
            rollbackTransaction();
            return DBStatus::IO_ERROR;
        }
    }

    // A transaction is not durable until its COMMIT record is present and
    // flushed. Fail closed before publishing CLOG visibility: otherwise a
    // WAL/fsync error could expose committed rows that crash recovery cannot
    // reconstruct.
    const std::string committingDb = transactionContext().txnDB;
    const uint64_t committingTxnId = transactionContext().currentTxnId;
    // Resolve the exact heap pages before the commit becomes irrevocable.
    struct CommitHeapPage {
        std::string tablename;
        uint32_t pageId = 0;
        PageAllocator* allocator = nullptr;
    };
    std::vector<CommitHeapPage> commitHeapPages;
    std::vector<PageAllocator*> commitAllocationState;
    std::set<PageAllocator*> seenAllocationState;
    for (const auto& [tableName, pageId] :
         transactionContext().txnHeapWritebackPages) {
        if (tableName.empty() || pageId == 0) {
            rollbackTransaction();
            return DBStatus::CORRUPTED_DATA;
        }
        // A relation can legitimately disappear after its last DML (for
        // example INSERT followed by DROP in one DDL-capable transaction).
        if (!tableExists(committingDb, tableName)) continue;
        PageAllocator* allocator = getPageAllocator(committingDb, tableName);
        if (!allocator || !allocator->bufferPool()) {
            rollbackTransaction();
            return DBStatus::IO_ERROR;
        }
        if (!allocator->pageExistsOnDisk(pageId).has_value()) {
            rollbackTransaction();
            return DBStatus::IO_ERROR;
        }
        commitHeapPages.push_back({tableName, pageId, allocator});
        if (seenAllocationState.insert(allocator).second &&
            allocator->hasDirtyAllocationState()) {
            commitAllocationState.push_back(allocator);
        }
    }

    // Main heap pages have WAL full-page images and can be written after the
    // COMMIT record. TOAST heap pages do not: once the main tuple containing
    // __TOAST__<id> becomes visible, every referenced chunk must already be
    // durable. The table IX tokens acquired above prevent a writer from
    // changing these buffers while PageAllocator copies them. Flush only the
    // relations touched by this transaction instead of publishing unrelated
    // databases-wide heap state.
    bool toastHeapWritebackOk = true;
    {
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        for (const auto& tableName :
             committingContext.specializedIndexTables) {
            const auto allocator = toastPageAllocators_.find(
                committingDb + ":" + tableName);
            if (allocator != toastPageAllocators_.end() &&
                allocator->second && !allocator->second->flush()) {
                toastHeapWritebackOk = false;
                break;
            }
        }
    }
    if (!toastHeapWritebackOk) {
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    if (!flushTableCaches(
            committingDb, committingContext.specializedIndexTables,
            /*heapPages=*/false)) {
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    // DML releases short-lived page locks after each mutation. Reacquire the
    // written pages in the set's deterministic order and hold them across the
    // WAL durability boundary plus writeback. This prevents both user writers
    // and a simultaneous commit from changing a frame while it is copied.
    size_t lockedCommitHeapPages = 0;
    const auto releaseCommitHeapPageLocks = [&]() {
        while (lockedCommitHeapPages > 0) {
            const auto& page = commitHeapPages[lockedCommitHeapPages - 1];
            lockManager_.pageUnlock(
                committingDb, page.tablename, page.pageId);
            --lockedCommitHeapPages;
        }
    };
    for (const auto& page : commitHeapPages) {
        if (!lockManager_.pageLockExclusive(
                committingDb, page.tablename, page.pageId)) {
            releaseCommitHeapPageLocks();
            rollbackTransaction();
            return DBStatus::LOCK_CONFLICT;
        }
        ++lockedCommitHeapPages;
    }

    WALManager* wal = getWAL(committingDb);
    if (!wal) {
        releaseCommitHeapPageLocks();
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    // A fresh/reused page is not visible to another StorageEngine until page
    // zero publishes the allocator's numPages/free-list change.  Flush all
    // heap WAL first, then durably write data pages before the header under a
    // recoverable extent marker.  This remains a reversible failure point:
    // no COMMIT record has entered WAL yet, so rollback is still legal.
    if (!commitAllocationState.empty()) {
        const Lsn heapWalEnd = wal->currentWriteLsn();
        if (!wal->XLogFlush(heapWalEnd)) {
            releaseCommitHeapPageLocks();
            rollbackTransaction();
            return DBStatus::IO_ERROR;
        }
        for (PageAllocator* allocator : commitAllocationState) {
            if (!allocator ||
                !allocator->flushAllocationStateForCommit()) {
                releaseCommitHeapPageLocks();
                rollbackTransaction();
                return DBStatus::IO_ERROR;
            }
        }
    }
    const Lsn commitLsn = walXactCommit(committingDb, committingTxnId);
    if (commitLsn == INVALID_LSN || !wal->XLogFlush(commitLsn)) {
        releaseCommitHeapPageLocks();
        rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    // WAL is now the durable source of truth, including every page image that
    // preceded the COMMIT record. Write back only this transaction's pages;
    // on failure retain their dirty bits for checkpoint/bgwriter retry. An
    // already-durable COMMIT must never be followed by a contradictory ABORT.
    bool heapWritebackOk = true;
    for (const auto& page : commitHeapPages) {
        if (!page.allocator->flushPage(page.pageId)) {
            heapWritebackOk = false;
        }
    }
    releaseCommitHeapPageLocks();
    if (!heapWritebackOk) {
        std::cerr
            << "[storage] COMMIT WAL is durable but heap writeback failed for "
            << committingDb << ":" << committingTxnId
            << "; retaining dirty pages for retry" << std::endl;
    }

    // Logical decoding (P2-5): stream buffered row changes into every
    // logical replication slot.  Only committed changes cross this line —
    // rollback drains the buffer instead.
    {
        auto& txn = transactionContext();
        if (!txn.txnLogicalChanges.empty()) {
            std::vector<LogicalChange> changes;
            changes.reserve(txn.txnLogicalChanges.size());
            for (const auto& c : txn.txnLogicalChanges) {
                LogicalChange lc;
                lc.table = c.table;
                lc.op = static_cast<LogicalChange::Op>(c.op);
                lc.oldRow = c.oldRow;
                lc.newRow = c.newRow;
                changes.push_back(std::move(lc));
            }
            // Publication membership was already checked when the change
            // was buffered; every logical slot receives the batch and its
            // consumer side filters (a slot's plugin controls only the
            // output format).
            publishLogicalChanges(
                changes, committingTxnId, static_cast<uint64_t>(commitLsn));
            txn.txnLogicalChanges.clear();
        }
    }

    // COMMIT became irrevocable when its WAL record was flushed above.  CLOG
    // is the live visibility cache and recovery can reconstruct it from WAL;
    // a CLOG write failure must therefore never route through rollback and
    // append a contradictory ABORT record for the same xid.
    CommitLog* clog = getCommitLog(transactionContext().txnDB);
    if (clog) {
        clog->setStatus(transactionContext().currentTxnId, CommitLog::Status::Committed);
        if (!clog->flush()) {
            std::cerr
                << "[CLOG] COMMIT WAL is durable but CLOG publication failed for "
                << committingDb << ":" << committingTxnId
                << "; treating the transaction as committed and relying on WAL recovery"
                << std::endl;
        }
    }

    // The new sidecars are safe to publish only after CLOG makes the matching
    // heap generation visible. A retained marker is harmless (queries scan
    // the heap and startup repairs it), so a cleanup failure must not turn an
    // already-durable COMMIT into an apparent rollback.
    for (const auto& tableName :
         committingContext.specializedIndexTables) {
        if (!tableExists(committingDb, tableName)) continue;
        if (!clearSpecializedIndexDirty(
                *this, committingDb, tableName)) {
            std::cerr
                << "[index] committed with specialized-index marker retained for "
                << committingDb << "/" << tableName << std::endl;
        }
    }

    // Do not reclaim UPDATE/DELETE values at commit.  A snapshot predating
    // this commit can still need those values; removing them here makes that
    // snapshot observe a broken row.  VACUUM TOAST waits for active snapshots
    // and then reclaims objects no current physical tuple references.

    // Update max committed txId
    TxnIdGenerator::instance().notifyCommit(transactionContext().currentTxnId);
    // Remove from active set
    bool noActiveTransactions = false;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(transactionContext().currentTxnId);
        activeTransactionDatabases_.erase(transactionContext().currentTxnId);
        noActiveTransactions = activeTransactions_.empty();
    }
    if (noActiveTransactions) {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_.clear();
        ssiWriteSets_.clear();
        ssiReadRelations_.clear();
        ssiWriteRelations_.clear();
        ssiReadPages_.clear();
        ssiWritePages_.clear();
        ssiReadIndexPredicates_.clear();
        ssiWriteIndexKeys_.clear();
        ssiOutEdges_.clear();
        ssiInEdges_.clear();
    }
    transactionContext().txnLog.clear();
    transactionContext().txnHeapWritebackPages.clear();
    transactionContext().specializedIndexTables.clear();
    // Logical decoding: rollback discards buffered changes — subscribers
    // never see uncommitted work.
    transactionContext().txnLogicalChanges.clear();
    transactionContext().ddlUndoActions.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    discardTransactionBackup(transactionContext().txnDB);
    transactionContext().savepoints.clear();
    transactionContext().txnSubTxnIds.clear();
    clearCatalogSnapshot();
    lockManager_.unlockAll();
    lockManager_.unlockAllGaps();
    if (Session* session = currentSession();
        session && session->currentDB == transactionContext().txnDB) {
        applySessionTempTableCommitActions(*this, *session, transactionContext().txnDB);
    }
    transactionContext().constraintMode.clear();
    transactionContext().deferredChecks.erase(transactionContext().currentTxnId);
    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    flushDeferredSequences();
    return DBStatus::OK;
}

bool StorageEngine::undoVersionedUpdate(const TxnLogEntry& entry) {
    if (entry.op != TxnLogEntry::Op::Update ||
        entry.previousRowIdx < 0 || entry.rowIdx < 0 ||
        entry.previousRowIdx == entry.rowIdx ||
        transactionContext().txnDB.empty()) {
        return false;
    }

    const std::string& dbname = transactionContext().txnDB;
    const std::string& tablename = entry.tableName;
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const TableSchema tbl = getTableSchema(dbname, tablename);
    if (!pa || !usesHeapTupleHeader(tbl.formatVersion)) return false;

    // Capture both physical images before changing the heap. UPDATE records
    // keep NEW as well as OLD so index repair remains possible when the NEW
    // heap page is damaged or unavailable during rollback.
    bool heapOk = true;
    bool indexesOk = true;
    std::string currentRow = entry.newRowData;
    std::string heapCurrentRow;
    if (readRowByRid(pa, entry.rowIdx, heapCurrentRow, tbl)) {
        currentRow = std::move(heapCurrentRow);
    }
    if (currentRow.empty() || entry.rowData.empty()) return false;

    struct IndexUndoEntry {
        std::string name;
        EvaluatedIndexEntry current;
        EvaluatedIndexEntry previous;
    };
    std::vector<IndexUndoEntry> secondaryEntries;
    for (const auto& metadata : getIndexMetadata(dbname, tablename)) {
        IndexUndoEntry undo;
        undo.name = metadata.name;
        if (!secondaryIndexEntryFromBuffer(
                *this, metadata, tbl, currentRow, dbname, undo.current) ||
            !secondaryIndexEntryFromBuffer(
                *this, metadata, tbl, entry.rowData, dbname,
                undo.previous)) {
            indexesOk = false;
            continue;
        }
        secondaryEntries.push_back(std::move(undo));
    }

    std::vector<IndexUndoEntry> compositeEntries;
    for (const auto& metadata : getCompositeIndexes(dbname, tablename)) {
        IndexUndoEntry undo;
        undo.name = metadata.name;
        if (!compositeIndexEntryFromBuffer(
                *this, metadata, tbl, currentRow, dbname, undo.current) ||
            !compositeIndexEntryFromBuffer(
                *this, metadata, tbl, entry.rowData, dbname,
                undo.previous)) {
            indexesOk = false;
            continue;
        }
        compositeEntries.push_back(std::move(undo));
    }

    auto columnIndex = [&](const std::string& columnName) {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == columnName) return i;
        }
        return tbl.len;
    };
    std::map<std::string, std::pair<std::string, std::string>> hashValues;
    for (const auto& columnName : getHashIndexedColumns(dbname, tablename)) {
        const size_t index = columnIndex(columnName);
        if (index >= tbl.len) {
            indexesOk = false;
            continue;
        }
        hashValues[columnName] = {
            canonicalColumnKeyValue(
                tbl.cols[index], extractColumnValue(
                    currentRow, tbl, index, dbname, true)),
            canonicalColumnKeyValue(
                tbl.cols[index], extractColumnValue(
                    entry.rowData, tbl, index, dbname, true))};
    }
    std::map<std::string, std::pair<std::string, std::string>> bloomValues;
    for (const auto& columnName : getBloomIndexedColumns(dbname, tablename)) {
        const size_t index = columnIndex(columnName);
        if (index >= tbl.len) {
            indexesOk = false;
            continue;
        }
        bloomValues[columnName] = {
            canonicalColumnKeyValue(
                tbl.cols[index], extractColumnValue(
                    currentRow, tbl, index, dbname, true)),
            canonicalColumnKeyValue(
                tbl.cols[index], extractColumnValue(
                    entry.rowData, tbl, index, dbname, true))};
    }

    uint32_t previousPageId = 0;
    uint16_t previousSlotId = 0;
    decodeRid(entry.previousRowIdx, previousPageId, previousSlotId);
    uint32_t currentPageId = 0;
    uint16_t currentSlotId = 0;
    decodeRid(entry.rowIdx, currentPageId, currentSlotId);

    const auto publishStagedPage = [&](
        uint32_t pageId, char* liveBuffer,
        std::vector<char>& stagedBuffer, PageWrapper& stagedPage) {
        const Lsn beforeLsn = walPageImage(
            dbname, tablename, pageId, liveBuffer, pa->pageSize(), true);
        if (beforeLsn == INVALID_LSN) return false;
        const Lsn afterLsn = walPageImage(
            dbname, tablename, pageId, stagedBuffer.data(),
            pa->pageSize(), false);
        WALManager* wal = getWAL(dbname);
        if (afterLsn == INVALID_LSN || !wal ||
            !wal->XLogFlush(afterLsn)) {
            return false;
        }
        std::memcpy(liveBuffer, stagedBuffer.data(), pa->pageSize());
        setPageLsnAndChecksum(liveBuffer, afterLsn);
        pa->markDirty(pageId);
        const size_t freePercent =
            stagedPage.freeSpace() * 100 / pa->pageSize();
        getFSM(dbname, tablename)->setFreePercent(
            pageId, static_cast<uint8_t>(freePercent));
        getVM(dbname, tablename)->setAllVisible(pageId, false);
        return pa->flush();
    };

    // Restore OLD in its original slot, preserving its xmin and null bitmap.
    bool previousRestored = false;
    if (lockManager_.pageLockExclusive(
            dbname, tablename, previousPageId)) {
        char* previousPageBuffer = pa->fetchPage(previousPageId);
        if (previousPageBuffer) {
            PageWrapper page(
                previousPageBuffer, pa->pageSize(), tbl.formatVersion);
            const char* tuple = nullptr;
            size_t tupleLength = 0;
            if (page.isValid() &&
                page.read(previousSlotId, tuple, tupleLength) &&
                tupleLength >= rowHeaderSize(tbl.formatVersion, tbl.len) &&
                stripRowHeader(
                    tuple, tupleLength, tbl.formatVersion, tbl.len) ==
                    entry.rowData) {
                std::vector<char> stagedBuffer(
                    previousPageBuffer,
                    previousPageBuffer + pa->pageSize());
                PageWrapper stagedPage(
                    stagedBuffer.data(), pa->pageSize(),
                    tbl.formatVersion);
                std::string restored = replaceRowData(
                    std::string(tuple, tupleLength), entry.rowData,
                    tbl.formatVersion, tbl.len);
                auto* header = castHeapHeader(restored.data());
                header->t_fields.t_xmax = 0;
                header->t_infomask &= ~(
                    HEAP_XMAX_COMMITTED | HEAP_XMAX_INVALID |
                    HEAP_XMAX_EXCL_LOCK | HEAP_XMAX_KEYSHR_LOCK |
                    HEAP_XMAX_LOCK_ONLY | HEAP_XMAX_IS_MULTI |
                    HEAP_UPDATED);
                setRowCtid(
                    restored.data(), restored.size(), tbl.formatVersion,
                    ItemPointer{
                        previousPageId,
                        static_cast<OffsetNumber>(previousSlotId + 1)});
                uint16_t restoredSlot = previousSlotId;
                if (stagedPage.update(
                        previousSlotId, restored.data(), restored.size(),
                        restoredSlot) &&
                    restoredSlot == previousSlotId) {
                    previousRestored = publishStagedPage(
                        previousPageId, previousPageBuffer,
                        stagedBuffer, stagedPage);
                }
            }
            pa->unpinPage(previousPageId);
        }
        lockManager_.pageUnlock(dbname, tablename, previousPageId);
    }

    // NEW is an aborted physical version after rollback and can be removed
    // immediately; no snapshot is allowed to observe its xmin.
    bool currentRemoved = false;
    if (lockManager_.pageLockExclusive(
            dbname, tablename, currentPageId)) {
        char* currentPageBuffer = pa->fetchPage(currentPageId);
        if (currentPageBuffer) {
            PageWrapper page(
                currentPageBuffer, pa->pageSize(), tbl.formatVersion);
            const char* tuple = nullptr;
            size_t tupleLength = 0;
            if (page.isValid()) {
                if (!page.read(currentSlotId, tuple, tupleLength)) {
                    currentRemoved = true;
                } else if (
                    tupleLength >=
                        rowHeaderSize(tbl.formatVersion, tbl.len) &&
                    stripRowHeader(
                        tuple, tupleLength, tbl.formatVersion,
                        tbl.len) == currentRow) {
                    std::vector<char> stagedBuffer(
                        currentPageBuffer,
                        currentPageBuffer + pa->pageSize());
                    PageWrapper stagedPage(
                        stagedBuffer.data(), pa->pageSize(),
                        tbl.formatVersion);
                    if (stagedPage.remove(currentSlotId)) {
                        currentRemoved = publishStagedPage(
                            currentPageId, currentPageBuffer,
                            stagedBuffer, stagedPage);
                    }
                }
            }
            pa->unpinPage(currentPageId);
        }
        lockManager_.pageUnlock(dbname, tablename, currentPageId);
    }
    heapOk = previousRestored && currentRemoved;

    const auto containsRid = [](const std::vector<int64_t>& values,
                                int64_t rid) {
        return std::find(values.begin(), values.end(), rid) != values.end();
    };
    if (tbl.hasPrimaryKey()) {
        BPTree* index = getPKIndex(dbname, tablename);
        const std::string currentKey = extractPKValue(currentRow, tbl, dbname);
        const std::string previousKey =
            extractPKValue(entry.rowData, tbl, dbname);
        if (!index || !index->isOpen() || currentKey.empty() ||
            previousKey.empty()) {
            indexesOk = false;
        } else {
            // Forward index maintenance may have failed before inserting NEW
            // (or even before removing OLD). Undo only mutations that are
            // actually present, then restore OLD only when it is absent.
            int64_t indexedRid = -1;
            if (index->search(currentKey, indexedRid) &&
                indexedRid == entry.rowIdx &&
                !index->remove(currentKey)) {
                indexesOk = false;
            }

            indexedRid = -1;
            if (index->search(previousKey, indexedRid)) {
                if (indexedRid != entry.previousRowIdx) indexesOk = false;
            } else if (!index->insert(
                           previousKey, entry.previousRowIdx)) {
                indexesOk = false;
            }
        }
    }

    for (const auto& undo : secondaryEntries) {
        BPTree* index = getSecondaryIndex(dbname, tablename, undo.name);
        if (!index || !index->isOpen()) {
            indexesOk = false;
            continue;
        }
        if (undo.current.included && !undo.current.key.empty()) {
            const auto currentRids = index->searchMulti(undo.current.key);
            if (containsRid(currentRids, entry.rowIdx) &&
                !index->removeMulti(undo.current.key, entry.rowIdx)) {
                indexesOk = false;
            }
        }
        if (undo.previous.included && !undo.previous.key.empty()) {
            const auto previousRids = index->searchMulti(undo.previous.key);
            if (!containsRid(previousRids, entry.previousRowIdx) &&
                !index->insertMulti(
                    undo.previous.key, entry.previousRowIdx)) {
                indexesOk = false;
            }
        }
    }
    for (const auto& undo : compositeEntries) {
        BPTree* index = getCompositeIndexTree(
            dbname, tablename, undo.name);
        if (!index || !index->isOpen()) {
            indexesOk = false;
            continue;
        }
        if (undo.current.included && !undo.current.key.empty()) {
            const auto currentRids = index->searchMulti(undo.current.key);
            if (containsRid(currentRids, entry.rowIdx) &&
                !index->removeMulti(undo.current.key, entry.rowIdx)) {
                indexesOk = false;
            }
        }
        if (undo.previous.included && !undo.previous.key.empty()) {
            const auto previousRids = index->searchMulti(undo.previous.key);
            if (!containsRid(previousRids, entry.previousRowIdx) &&
                !index->insertMulti(
                    undo.previous.key, entry.previousRowIdx)) {
                indexesOk = false;
            }
        }
    }
    for (const auto& [columnName, values] : hashValues) {
        HashIndex* index = getHashIndex(dbname, tablename, columnName);
        if (!index || !index->isOpen()) {
            indexesOk = false;
            continue;
        }
        if (!values.first.empty()) {
            const auto currentRids = index->search(values.first);
            if (containsRid(currentRids, entry.rowIdx) &&
                !index->remove(values.first, entry.rowIdx)) {
                indexesOk = false;
            }
        }
        if (!values.second.empty()) {
            const auto previousRids = index->search(values.second);
            if (!containsRid(previousRids, entry.previousRowIdx) &&
                !index->insert(values.second, entry.previousRowIdx)) {
                indexesOk = false;
            }
        }
    }
    for (const auto& [columnName, values] : bloomValues) {
        BloomIndex* index = getBloomIndex(dbname, tablename, columnName);
        if (!index || !index->isOpen()) {
            indexesOk = false;
            continue;
        }
        if (!values.first.empty()) {
            const auto currentRids = index->search(values.first);
            if (containsRid(currentRids, entry.rowIdx) &&
                !index->remove(values.first, entry.rowIdx)) {
                indexesOk = false;
            }
        }
        if (!values.second.empty()) {
            const auto previousRids = index->search(values.second);
            if (!containsRid(previousRids, entry.previousRowIdx) &&
                !index->insert(values.second, entry.previousRowIdx)) {
                indexesOk = false;
            }
        }
    }

    // Only NEW-only external objects are unreachable after the heap/index
    // undo.  OLD objects remain referenced by the restored tuple.
    deleteToastForRowExcept(
        dbname, tablename, currentRow, entry.rowData);
    return heapOk && indexesOk;
}

DBStatus StorageEngine::rollbackTransaction() {
    if (!transactionContext().inTransaction) return DBStatus::OK;
    lockManager_.setResourceNamespace(transactionContext().txnDB);

    auto& rollbackContext = transactionContext();
    const bool databaseWideUndo =
        rollbackContext.transactionBackupDirty ||
        !rollbackContext.ddlUndoActions.empty();
    for (const auto& entry : rollbackContext.txnLog) {
        rollbackContext.specializedIndexTables.insert(entry.tableName);
    }
    // Serialize whole-file access-method repair with every table writer and
    // retain these outer lock tokens until the aborted xid leaves the active
    // set.  The helper takes/relinquishes only a nested token.
    std::set<std::string> specializedLockedTables;
    bool specializedLocksOk = true;
    for (const auto& tableName : rollbackContext.specializedIndexTables) {
        if (!tableExists(rollbackContext.txnDB, tableName)) continue;
        if (lockManager_.lockIntentExclusive(tableName)) {
            specializedLockedTables.insert(tableName);
        } else {
            specializedLocksOk = false;
        }
    }

    const std::string rollbackDb = transactionContext().txnDB;
    const bool preserveBackup = transactionContext().preserveBackupOnRollback;
    const bool hasBackup = preserveBackup &&
        transactionContext().restoreBackupBeforeRowUndo &&
        transactionContext().transactionBackupDirty &&
        !transactionContext().txnBackupPath.empty();
    const size_t ddlUndoReplaySize = hasBackup
        ? transactionContext().ddlUndoSizeAtBackup
        : transactionContext().ddlUndoActions.size();
    bool snapshotRestoreOk = true;
    bool rowUndoOk = true;
    std::set<BloomIndex*> bloomUndoIndexes;

    // A DDL snapshot may have been taken in the middle of an explicit outer
    // transaction. Restore it before row undo so the row log can replay from
    // the same physical state captured by the snapshot. This also makes a
    // full ROLLBACK restore DROP/REPLACE operations without reintroducing the
    // rows that existed before the snapshot was taken.
    if (hasBackup) {
        snapshotRestoreOk = restoreTransactionBackup(rollbackDb);
    }

    // Mark transaction as aborted in CLOG. Continue rollback even if the
    // status cannot be persisted, but report the durability failure after all
    // in-memory and physical undo work has completed.
    bool clogOk = true;
    CommitLog* clog = getCommitLog(transactionContext().txnDB);
    if (clog) {
        clog->setStatus(transactionContext().currentTxnId, CommitLog::Status::Aborted);
        clogOk = clog->flush();
    }

    // Keep the xid in the active set until physical/index undo is complete.
    // Otherwise a concurrent reader may re-enable an index while it still
    // points at the aborted NEW version.
    bool noActiveTransactions = false;

    // Replay txnLog in reverse order to undo changes
    for (auto it = transactionContext().txnLog.rbegin(); it != transactionContext().txnLog.rend(); ++it) {
        PageAllocator* pa = getPageAllocator(transactionContext().txnDB, it->tableName);
        TableSchema tbl = getTableSchema(transactionContext().txnDB, it->tableName);

        if (it->op == TxnLogEntry::Op::Insert) {
            // Undo INSERT: remove the row
            uint32_t pageId; uint16_t slotId;
            decodeRid(it->rowIdx, pageId, slotId);
            // Read row data before removing so index entries can be cleaned up.
            // INSERT records carry the physical row payload so index cleanup
            // does not depend on successfully re-reading a damaged heap page.
            std::string insertedRow = it->rowData;
            std::string pkVal;
            std::vector<EvaluatedIndexEntry> secondaryIdxVals;
            std::vector<EvaluatedIndexEntry> compositeIdxVals;
            std::map<std::string, std::string> hashIdxVals;
            std::map<std::string, std::string> bloomIdxVals;
            std::string heapRow;
            if (readRowByRid(pa, it->rowIdx, heapRow, tbl)) {
                insertedRow = std::move(heapRow);
            } else {
                rowUndoOk = false;
            }
            if (insertedRow.empty()) {
                rowUndoOk = false;
            } else {
                pkVal = extractPKValue(
                    insertedRow, tbl, transactionContext().txnDB);
                for (const auto& metadata : getIndexMetadata(
                         transactionContext().txnDB, it->tableName)) {
                    EvaluatedIndexEntry entry;
                    if (!secondaryIndexEntryFromBuffer(
                            *this, metadata, tbl, insertedRow,
                            transactionContext().txnDB, entry)) {
                        rowUndoOk = false;
                        continue;
                    }
                    secondaryIdxVals.push_back(std::move(entry));
                }
                for (const auto& ci : getCompositeIndexes(
                         transactionContext().txnDB, it->tableName)) {
                    EvaluatedIndexEntry entry;
                    if (!compositeIndexEntryFromBuffer(
                            *this, ci, tbl, insertedRow,
                            transactionContext().txnDB, entry)) {
                        rowUndoOk = false;
                        continue;
                    }
                    compositeIdxVals.push_back(std::move(entry));
                }
                for (const auto& colname : getHashIndexedColumns(
                         transactionContext().txnDB, it->tableName)) {
                    size_t colIdx = tbl.len;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == colname) {
                            colIdx = i;
                            break;
                        }
                    }
                    if (colIdx < tbl.len) {
                        std::string value = canonicalColumnKeyValue(
                            tbl.cols[colIdx], extractColumnValue(
                                insertedRow, tbl, colIdx,
                                transactionContext().txnDB));
                        if (!value.empty()) hashIdxVals[colname] = value;
                    } else {
                        rowUndoOk = false;
                    }
                }
                for (const auto& colname : getBloomIndexedColumns(
                         transactionContext().txnDB, it->tableName)) {
                    size_t colIdx = tbl.len;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == colname) {
                            colIdx = i;
                            break;
                        }
                    }
                    if (colIdx < tbl.len) {
                        std::string value = canonicalColumnKeyValue(
                            tbl.cols[colIdx], extractColumnValue(
                                insertedRow, tbl, colIdx,
                                transactionContext().txnDB));
                        if (!value.empty()) {
                            bloomIdxVals[colname] = std::move(value);
                        }
                    } else {
                        rowUndoOk = false;
                    }
                }
            }
            if (!insertedRow.empty()) {
                deleteRowToast(transactionContext().txnDB, it->tableName, it->rowIdx);
            }
            if (!pa) {
                rowUndoOk = false;
            } else {
                char* pageBuf = pa->fetchPage(pageId);
                if (!pageBuf) {
                    rowUndoOk = false;
                } else {
                    PageWrapper page(
                        pageBuf, pa->pageSize(), tbl.formatVersion);
                    const char* currentData = nullptr;
                    size_t currentLength = 0;
                    if (!page.isValid() ||
                        !page.read(slotId, currentData, currentLength)) {
                        rowUndoOk = false;
                    } else {
                        const Lsn beforeLsn = walPageImage(
                            transactionContext().txnDB, it->tableName,
                            pageId, pageBuf, pa->pageSize(), true);
                        std::vector<char> stagedPage(
                            pageBuf, pageBuf + pa->pageSize());
                        PageWrapper staged(
                            stagedPage.data(), pa->pageSize(),
                            tbl.formatVersion);
                        if (beforeLsn == INVALID_LSN ||
                            !staged.remove(slotId)) {
                            rowUndoOk = false;
                        } else {
                            const Lsn lsn = walPageImage(
                                transactionContext().txnDB, it->tableName,
                                pageId, stagedPage.data(), pa->pageSize(),
                                false);
                            WALManager* wal = getWAL(
                                transactionContext().txnDB);
                            if (lsn == INVALID_LSN || !wal ||
                                !wal->XLogFlush(lsn)) {
                                rowUndoOk = false;
                            } else {
                                std::memcpy(
                                    pageBuf, stagedPage.data(),
                                    pa->pageSize());
                                setPageLsnAndChecksum(pageBuf, lsn);
                                pa->markDirty(pageId);
                                const size_t freePercent =
                                    staged.freeSpace() * 100 / pa->pageSize();
                                getFSM(
                                    transactionContext().txnDB,
                                    it->tableName)->setFreePercent(
                                        pageId,
                                        static_cast<uint8_t>(freePercent));
                                getVM(
                                    transactionContext().txnDB,
                                    it->tableName)->setAllVisible(
                                        pageId, false);
                                if (!pa->flush()) rowUndoOk = false;
                            }
                        }
                    }
                    pa->unpinPage(pageId);
                }
            }
            // Remove from PK index
            if (tbl.hasPrimaryKey()) {
                BPTree* pkIdx = getPKIndex(
                    transactionContext().txnDB, it->tableName);
                if (pkVal.empty() || !pkIdx ||
                    (!pkIdx->isOpen() && !pkIdx->open())) {
                    rowUndoOk = false;
                } else {
                    int64_t indexedRid = -1;
                    if (pkIdx->search(pkVal, indexedRid)) {
                        if (indexedRid != it->rowIdx ||
                            !pkIdx->remove(pkVal)) {
                            rowUndoOk = false;
                        }
                    }
                }
            }
            // Remove from secondary indexes
            for (const auto& entry : secondaryIdxVals) {
                if (!entry.included || entry.key.empty()) continue;
                BPTree* index = getSecondaryIndex(
                    transactionContext().txnDB, it->tableName, entry.name);
                if (!index || (!index->isOpen() && !index->open())) {
                    rowUndoOk = false;
                    continue;
                }
                while (true) {
                    const auto rids = index->searchMulti(entry.key);
                    if (std::find(rids.begin(), rids.end(), it->rowIdx) ==
                        rids.end()) {
                        break;
                    }
                    if (!index->removeMulti(entry.key, it->rowIdx)) {
                        rowUndoOk = false;
                        break;
                    }
                }
            }
            for (const auto& entry : compositeIdxVals) {
                if (!entry.included || entry.key.empty()) continue;
                BPTree* index = getCompositeIndexTree(
                    transactionContext().txnDB, it->tableName, entry.name);
                if (!index || (!index->isOpen() && !index->open())) {
                    rowUndoOk = false;
                    continue;
                }
                while (true) {
                    const auto rids = index->searchMulti(entry.key);
                    if (std::find(rids.begin(), rids.end(), it->rowIdx) ==
                        rids.end()) {
                        break;
                    }
                    if (!index->removeMulti(entry.key, it->rowIdx)) {
                        rowUndoOk = false;
                        break;
                    }
                }
            }
            for (const auto& kv : hashIdxVals) {
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, it->tableName, kv.first);
                if (!hashIdx ||
                    (!hashIdx->isOpen() && !hashIdx->open())) {
                    rowUndoOk = false;
                    continue;
                }
                while (true) {
                    const auto rids = hashIdx->search(kv.second);
                    if (std::find(rids.begin(), rids.end(), it->rowIdx) ==
                        rids.end()) {
                        break;
                    }
                    if (!hashIdx->remove(kv.second, it->rowIdx)) {
                        rowUndoOk = false;
                        break;
                    }
                }
            }
            for (const auto& [columnName, value] : bloomIdxVals) {
                BloomIndex* bloomIdx = getBloomIndex(
                    transactionContext().txnDB, it->tableName, columnName);
                if (!bloomIdx ||
                    (!bloomIdx->isOpen() && !bloomIdx->open())) {
                    rowUndoOk = false;
                    continue;
                }
                bloomUndoIndexes.insert(bloomIdx);
                while (true) {
                    const auto rids = bloomIdx->search(value);
                    if (std::find(rids.begin(), rids.end(), it->rowIdx) ==
                        rids.end()) {
                        break;
                    }
                    if (!bloomIdx->remove(value, it->rowIdx)) {
                        rowUndoOk = false;
                        break;
                    }
                }
            }
        } else if (it->op == TxnLogEntry::Op::Update) {
            if (it->previousRowIdx >= 0) {
                if (!undoVersionedUpdate(*it)) rowUndoOk = false;
                continue;
            }
            // Undo UPDATE: restore old row data
            uint32_t pageId; uint16_t slotId;
            decodeRid(it->rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            std::string currentRow;
            bool foundCurrent = false;
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, it->tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                // Read current row data before restoring (needed to remove stale index entries)
                const char* currentData = nullptr;
                size_t currentLen = 0;
                bool got = page.read(slotId, currentData, currentLen);
                if (got && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    currentRow = stripRowHeader(currentData, currentLen, tbl.formatVersion, tbl.len);
                    foundCurrent = true;
                } else if (!got) {
                    std::string targetPk = extractPKValue(
                        it->rowData, tbl, transactionContext().txnDB);
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (foundCurrent || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(
                            rowData, tbl, transactionContext().txnDB);
                        if (pk == targetPk) {
                            currentRow = rowData;
                            foundCurrent = true;
                        }
                    });
                }
                // Restore old row data
                if (got && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), it->rowData, tbl.formatVersion, tbl.len);
                    setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                } else if (!got) {
                    std::string targetPk = extractPKValue(
                        it->rowData, tbl, transactionContext().txnDB);
                    bool restored = false;
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (restored || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(
                            rowData, tbl, transactionContext().txnDB);
                        if (pk == targetPk) {
                            std::string fullRow = replaceRowData(
                                std::string(data, len), it->rowData, tbl.formatVersion, tbl.len);
                            setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            page.update(sid, fullRow.data(), fullRow.size());
                            restored = true;
                        }
                    });
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, it->tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Rebuild indexes: remove current (stale) values then insert restored values
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, it->tableName);
            if (pkIdx) {
                if (foundCurrent) {
                    std::string currentPk = extractPKValue(
                        currentRow, tbl, transactionContext().txnDB);
                    if (!currentPk.empty()) pkIdx->remove(currentPk);
                }
                std::string pkVal = extractPKValue(
                    it->rowData, tbl, transactionContext().txnDB);
                if (!pkVal.empty()) pkIdx->insert(pkVal, it->rowIdx);
            }
            for (const auto& metadata : getIndexMetadata(
                     transactionContext().txnDB, it->tableName)) {
                BPTree* index = getSecondaryIndex(
                    transactionContext().txnDB, it->tableName, metadata.name);
                if (!index) {
                    rowUndoOk = false;
                    continue;
                }
                if (foundCurrent) {
                    EvaluatedIndexEntry entry;
                    if (!secondaryIndexEntryFromBuffer(
                            *this, metadata, tbl, currentRow,
                            transactionContext().txnDB, entry)) {
                        rowUndoOk = false;
                    } else if (entry.included && !entry.key.empty()) {
                        index->removeMulti(entry.key, it->rowIdx);
                    }
                }
                EvaluatedIndexEntry entry;
                if (!secondaryIndexEntryFromBuffer(
                        *this, metadata, tbl, it->rowData,
                        transactionContext().txnDB, entry)) {
                    rowUndoOk = false;
                } else if (entry.included && !entry.key.empty() &&
                           !index->insertMulti(entry.key, it->rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, it->tableName)) {
                BPTree* index = getCompositeIndexTree(
                    transactionContext().txnDB, it->tableName, ci.name);
                if (!index) {
                    rowUndoOk = false;
                    continue;
                }
                if (foundCurrent) {
                    EvaluatedIndexEntry entry;
                    if (!compositeIndexEntryFromBuffer(
                            *this, ci, tbl, currentRow,
                            transactionContext().txnDB, entry)) {
                        rowUndoOk = false;
                    } else if (entry.included && !entry.key.empty()) {
                        index->removeMulti(entry.key, it->rowIdx);
                    }
                }
                EvaluatedIndexEntry entry;
                if (!compositeIndexEntryFromBuffer(
                        *this, ci, tbl, it->rowData,
                        transactionContext().txnDB, entry)) {
                    rowUndoOk = false;
                } else if (entry.included && !entry.key.empty() &&
                           !index->insertMulti(entry.key, it->rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, it->tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, it->tableName, colname);
                if (!hashIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = canonicalColumnKeyValue(
                        tbl.cols[colIdx], extractColumnValue(
                            currentRow, tbl, colIdx,
                            transactionContext().txnDB));
                    if (!currentVal.empty()) hashIdx->remove(currentVal, it->rowIdx);
                }
                std::string oldVal = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        it->rowData, tbl, colIdx,
                        transactionContext().txnDB));
                if (!oldVal.empty()) hashIdx->insert(oldVal, it->rowIdx);
            }
            for (const auto& colname : getBloomIndexedColumns(
                     transactionContext().txnDB, it->tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) {
                        colIdx = i;
                        break;
                    }
                }
                if (colIdx >= tbl.len) {
                    rowUndoOk = false;
                    continue;
                }
                BloomIndex* bloomIdx = getBloomIndex(
                    transactionContext().txnDB, it->tableName, colname);
                if (!bloomIdx) {
                    rowUndoOk = false;
                    continue;
                }
                bloomUndoIndexes.insert(bloomIdx);
                if (foundCurrent) {
                    const std::string currentVal = canonicalColumnKeyValue(
                        tbl.cols[colIdx], extractColumnValue(
                            currentRow, tbl, colIdx,
                            transactionContext().txnDB));
                    if (!currentVal.empty() &&
                        !bloomIdx->remove(currentVal, it->rowIdx)) {
                        rowUndoOk = false;
                    }
                }
                const std::string oldVal = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        it->rowData, tbl, colIdx,
                        transactionContext().txnDB));
                if (!oldVal.empty() &&
                    !bloomIdx->insert(oldVal, it->rowIdx)) {
                    rowUndoOk = false;
                }
            }
            if (foundCurrent) {
                // Index cleanup needs the logical new values, so reclaim the
                // superseded chunks only after every stale key is removed.
                deleteToastForRowExcept(transactionContext().txnDB,
                                        it->tableName, currentRow,
                                        it->rowData);
            }
        } else if (it->op == TxnLogEntry::Op::Delete) {
            if (!undoDeletedRow(*it, bloomUndoIndexes)) {
                rowUndoOk = false;
            }
        }
    }
    for (BloomIndex* index : bloomUndoIndexes) {
        if (!index->flush()) rowUndoOk = false;
    }

    // DDL wrappers register CREATE undo actions in the outer transaction.
    // Replay them only after row undo: INSERTs into a table created in the
    // same transaction still need that table to exist while their rows are
    // being removed.
    bool ddlUndoOk = true;
    auto ddlUndoEnd = transactionContext().ddlUndoActions.rend();
    auto ddlUndoBegin = transactionContext().ddlUndoActions.rbegin();
    if (ddlUndoReplaySize < transactionContext().ddlUndoActions.size()) {
        ddlUndoBegin = transactionContext().ddlUndoActions.rbegin() +
                       (transactionContext().ddlUndoActions.size() - ddlUndoReplaySize);
    }
    for (auto it = ddlUndoBegin; it != ddlUndoEnd; ++it) {
        try {
            if (!(*it)()) ddlUndoOk = false;
        } catch (...) {
            ddlUndoOk = false;
        }
    }
    transactionContext().ddlUndoActions.clear();

    // A commit attempt can already have rebuilt these sidecars with the
    // transaction's NEW versions before a later durability step fails.  Once
    // heap/DDL undo is complete, derive them again from a fresh view that
    // excludes this now-aborted xid.
    for (const auto& tableName :
         rollbackContext.specializedIndexTables) {
        if (!tableExists(rollbackDb, tableName) ||
            specializedLockedTables.count(tableName)) {
            continue;
        }
        if (lockManager_.lockIntentExclusive(tableName)) {
            specializedLockedTables.insert(tableName);
        } else {
            specializedLocksOk = false;
        }
    }
    const ReadView savedRollbackReadView = rollbackContext.readView;
    const IsolationLevel savedRollbackIsolation =
        rollbackContext.txnIsolationLevel;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        rollbackContext.readView.creatorTxnId = 0;
        rollbackContext.readView.lowLimitId =
            TxnIdGenerator::instance().maxCommittedTxId() + 1;
        rollbackContext.readView.upLimitId = activeTransactions_.empty()
            ? rollbackContext.readView.lowLimitId
            : *activeTransactions_.begin();
        rollbackContext.readView.activeTxnIds = activeTransactions_;
        rollbackContext.readView.subTxnIds.clear();
        rollbackContext.readView.commitLog = getCommitLog(rollbackDb);
    }
    rollbackContext.txnIsolationLevel = IsolationLevel::READ_COMMITTED;
    bool specializedUndoOk = specializedLocksOk;
    for (const auto& tableName :
         rollbackContext.specializedIndexTables) {
        if (!tableExists(rollbackDb, tableName)) continue;
        if (!specializedLockedTables.count(tableName) ||
            !rebuildSpecializedIndexes(rollbackDb, tableName)) {
            specializedUndoOk = false;
        }
    }
    rollbackContext.readView = savedRollbackReadView;
    rollbackContext.txnIsolationLevel = savedRollbackIsolation;

    // PREPARE and statement-level cache pressure can publish uncommitted
    // index generations before rollback.  Persist every heap/index undo as
    // one boundary before advertising ABORT; otherwise a new backend can
    // reopen the pre-rollback B-tree/hash sidecars even though this backend's
    // in-memory indexes are correct.
    const bool undoFlushOk = databaseWideUndo
        ? flushDatabaseCaches(rollbackDb)
        : flushTableCaches(
              rollbackDb, rollbackContext.specializedIndexTables);

    // Write WAL ABORT marker after undo.
    WALManager* wal = getWAL(transactionContext().txnDB);
    bool abortWalOk = true;
    if (wal) {
        const Lsn abortLsn = walXactAbort(transactionContext().txnDB,
                                           transactionContext().currentTxnId);
        abortWalOk = abortLsn != INVALID_LSN && wal->XLogFlush(abortLsn);
    } else {
        abortWalOk = false;
    }

    // The heap and every current-version index now agree again, so readers
    // may stop treating this xid as a source of snapshot-incomplete indexes.
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(transactionContext().currentTxnId);
        activeTransactionDatabases_.erase(transactionContext().currentTxnId);
        noActiveTransactions = activeTransactions_.empty();
    }

    transactionContext().deferredChecks.erase(transactionContext().currentTxnId);
    transactionContext().txnLog.clear();
    transactionContext().specializedIndexTables.clear();
    // Logical decoding: rollback discards buffered changes — subscribers
    // never see uncommitted work.
    transactionContext().txnLogicalChanges.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().savepoints.clear();
    transactionContext().txnSubTxnIds.clear();
    clearCatalogSnapshot();
    lockManager_.unlockAll();
    lockManager_.unlockAllGaps();

    // Clean up SSI data for aborted transaction
    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        if (noActiveTransactions) {
            ssiReadSets_.clear();
            ssiWriteSets_.clear();
            ssiReadRelations_.clear();
            ssiWriteRelations_.clear();
            ssiReadPages_.clear();
            ssiWritePages_.clear();
            ssiReadIndexPredicates_.clear();
            ssiWriteIndexKeys_.clear();
            ssiOutEdges_.clear();
            ssiInEdges_.clear();
        } else {
            ssiReadSets_.erase(transactionContext().currentTxnId);
            ssiWriteSets_.erase(transactionContext().currentTxnId);
            ssiReadRelations_.erase(transactionContext().currentTxnId);
            ssiWriteRelations_.erase(transactionContext().currentTxnId);
            ssiReadPages_.erase(transactionContext().currentTxnId);
            ssiWritePages_.erase(transactionContext().currentTxnId);
            ssiReadIndexPredicates_.erase(transactionContext().currentTxnId);
            ssiWriteIndexKeys_.erase(transactionContext().currentTxnId);
            ssiOutEdges_.erase(transactionContext().currentTxnId);
            for (auto& [k, v] : ssiInEdges_) v.erase(transactionContext().currentTxnId);
            ssiInEdges_.erase(transactionContext().currentTxnId);
            for (auto& [k, v] : ssiOutEdges_) v.erase(transactionContext().currentTxnId);
        }
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnHeapWritebackPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();

    if (Session* session = currentSession();
        session && session->currentDB == transactionContext().txnDB) {
        rollbackSessionTempTables(*this, *session, transactionContext().txnDB);
    }

    if (!preserveBackup) discardTransactionBackup(rollbackDb);

    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    transactionContext().constraintMode.clear();
    transactionContext().deferredChecks.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    // Sequences are non-transactional: persist advanced counters even on
    // rollback so concurrent transactions cannot observe reused values.
    flushDeferredSequences();
    const bool rollbackOk = snapshotRestoreOk && rowUndoOk && ddlUndoOk &&
                            specializedUndoOk && undoFlushOk && clogOk &&
                            abortWalOk;
    if (!rollbackOk) {
        std::cerr << "[transaction] rollback incomplete for " << rollbackDb
                  << " (snapshot=" << snapshotRestoreOk
                  << ", rows=" << rowUndoOk
                  << ", ddl=" << ddlUndoOk
                  << ", specialized_indexes=" << specializedUndoOk
                  << ", flush=" << undoFlushOk
                  << ", clog=" << clogOk
                  << ", wal=" << abortWalOk << ")" << std::endl;
    }
    return rollbackOk ? DBStatus::OK : DBStatus::IO_ERROR;
}

bool StorageEngine::restoreTransactionBackup(const std::string& dbname) {
    if (dbname.empty()) return false;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto& context = transactionContext();
    std::filesystem::path backup = context.txnBackupPath;
    if (backup.empty()) {
        // No legacy snapshot format is created anymore. This fallback keeps
        // the API fail-closed for callers that have no current transaction.
        return false;
    }
    if (!std::filesystem::exists(backup) || !std::filesystem::is_directory(backup)) {
        return false;
    }

    // DDL may have changed relation files and catalog state without creating
    // row-level undo records.  Close every database-owned cache before
    // replacing the directory so no stale file handles survive the restore.
    if (catalogService_) catalogService_->evict(dbname);
    closeDatabaseCaches(dbname);
    const bool restored = physicalRestore(dbname, backup.string());
    if (restored) {
        std::error_code ec;
        std::filesystem::remove_all(backup, ec);
        context.txnBackupPath.clear();
        context.transactionBackupDirty = false;
        context.restoreBackupBeforeRowUndo = false;
        context.ddlUndoSizeAtBackup = 0;
    }
    return restored;
}

void StorageEngine::discardTransactionBackup(const std::string& dbname) {
    if (dbname.empty()) return;
    auto& context = transactionContext();
    std::error_code ec;
    if (!context.txnBackupPath.empty()) {
        std::filesystem::remove_all(context.txnBackupPath, ec);
        context.txnBackupPath.clear();
    }
    context.transactionBackupDirty = false;
    context.restoreBackupBeforeRowUndo = false;
    context.ddlUndoSizeAtBackup = 0;
}

// ========================================================================
// Two-phase commit support
// ========================================================================

static std::filesystem::path preparedDir() {
    return std::filesystem::path("info") / ".prepared";
}

static std::filesystem::path preparedPath(const std::string& xid) {
    return preparedDir() / xid;
}

static bool validPreparedXid(const std::string& xid) {
    if (xid.empty() || xid.size() > 200) return false;
    for (const unsigned char c : xid) {
        if (!(std::isalnum(c) || c == '_' || c == '-' || c == '.' || c == ':')) return false;
    }
    return true;
}

static bool writePreparedFileAtomically(const std::filesystem::path& target,
                                        const std::string& contents) {
    const auto parent = target.parent_path();
    const auto temp = target.string() + ".tmp." + std::to_string(::getpid());
    const int fd = ::open(temp.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC, 0600);
    if (fd < 0) return false;
    bool ok = true;
    size_t offset = 0;
    while (offset < contents.size()) {
        const ssize_t written = ::write(fd, contents.data() + offset,
                                        contents.size() - offset);
        if (written <= 0) { ok = false; break; }
        offset += static_cast<size_t>(written);
    }
    if (ok && ::fsync(fd) != 0) ok = false;
    if (::close(fd) != 0) ok = false;
    if (!ok) {
        std::error_code ec;
        std::filesystem::remove(temp, ec);
        return false;
    }
    std::error_code ec;
    std::filesystem::rename(temp, target, ec);
    if (ec) {
        std::filesystem::remove(temp, ec);
        return false;
    }
    const int dirFd = ::open(parent.c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (dirFd < 0) return false;
    const bool durable = ::fsync(dirFd) == 0;
    ::close(dirFd);
    return durable;
}

static bool removePreparedFileDurably(const std::filesystem::path& target) {
    std::error_code ec;
    if (std::filesystem::exists(target, ec) &&
        !std::filesystem::remove(target, ec)) return false;
    if (ec) return false;
    const int dirFd = ::open(target.parent_path().c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
    if (dirFd < 0) return false;
    const bool durable = ::fsync(dirFd) == 0;
    ::close(dirFd);
    return durable;
}

static bool readPreparedRecord(const std::filesystem::path& path,
                               PreparedTransactionRecord& record) {
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    std::string line;
    bool hasTxnId = false;
    bool hasDbname = false;
    bool hasFormat = false;
    bool hasIsolation = false;
    while (std::getline(input, line)) {
        try {
            if (line.rfind("PREPARED_FORMAT ", 0) == 0) {
                const std::string value = line.substr(std::string("PREPARED_FORMAT ").size());
                size_t consumed = 0;
                const long long format = std::stoll(value, &consumed);
                if (hasFormat || consumed != value.size() ||
                    format < PreparedTransactionRecord::MINIMUM_FORMAT ||
                    format > PreparedTransactionRecord::CURRENT_FORMAT) {
                    return false;
                }
                record.format = static_cast<int>(format);
                hasFormat = true;
            } else if (line.rfind("TXN_ID ", 0) == 0) {
                if (hasTxnId) return false;
                const std::string value = line.substr(7);
                size_t consumed = 0;
                record.txnId = std::stoull(value, &consumed);
                if (consumed != value.size()) return false;
                hasTxnId = true;
            } else if (line.rfind("DBNAME ", 0) == 0) {
                if (hasDbname || !hasFormat) return false;
                const std::string storedName = line.substr(7);
                if (record.format >= 5) {
                    if (!preparedHexDecode(storedName, record.dbname)) return false;
                } else {
                    record.dbname = storedName;
                }
                hasDbname = true;
            } else if (line.rfind("ISOLATION ", 0) == 0) {
                if (hasIsolation) return false;
                const int value = std::stoi(line.substr(10));
                if (value < static_cast<int>(IsolationLevel::READ_UNCOMMITTED) ||
                    value > static_cast<int>(IsolationLevel::SERIALIZABLE)) return false;
                record.isolation = static_cast<IsolationLevel>(value);
                hasIsolation = true;
            } else if (line.rfind("READONLY ", 0) == 0) {
                const std::string value = line.substr(9);
                if (value != "0" && value != "1") return false;
            } else if (line.rfind("LOCK ", 0) == 0) {
                std::istringstream lockLine(line.substr(5));
                std::string kind;
                if (!(lockLine >> kind)) return false;
                LockManager::PreparedLockInfo lock;
                std::string mode;
                std::string encodedTable;
                if (kind == "TABLE") {
                    if (!(lockLine >> mode >> encodedTable) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Table;
                } else if (kind == "ROW") {
                    std::string rid;
                    if (!(lockLine >> mode >> encodedTable >> rid) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    size_t consumed = 0;
                    lock.rid = std::stoll(rid, &consumed);
                    if (consumed != rid.size()) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Row;
                } else if (kind == "PAGE") {
                    std::string pageId;
                    if (!(lockLine >> mode >> encodedTable >> pageId) ||
                        !parsePreparedLockMode(mode, lock.mode) ||
                        !preparedHexDecode(encodedTable, lock.table)) return false;
                    size_t consumed = 0;
                    const auto parsed = std::stoull(pageId, &consumed);
                    if (consumed != pageId.size() || parsed > UINT32_MAX) return false;
                    lock.pageId = static_cast<uint32_t>(parsed);
                    lock.kind = LockManager::PreparedLockInfo::Kind::Page;
                } else if (kind == "GAP") {
                    std::string encodedLeft;
                    std::string encodedRight;
                    if (!(lockLine >> encodedTable >> encodedLeft >> encodedRight) ||
                        !preparedHexDecode(encodedTable, lock.table) ||
                        !preparedHexDecode(encodedLeft, lock.leftKey) ||
                        !preparedHexDecode(encodedRight, lock.rightKey)) return false;
                    lock.kind = LockManager::PreparedLockInfo::Kind::Gap;
                    lock.mode = LockManager::LockMode::Exclusive;
                } else {
                    return false;
                }
                if (lockLine >> mode) return false;
                lock.dbname = record.dbname;
                record.locks.push_back(std::move(lock));
            } else if (line.rfind("LOG ", 0) == 0) {
                if (!hasFormat) return false;
                size_t pos = 4;
                const size_t opEnd = line.find(' ', pos);
                if (opEnd == std::string::npos) return false;
                const std::string op = line.substr(pos, opEnd - pos);
                pos = opEnd + 1;
                const size_t tableEnd = line.find(' ', pos);
                if (tableEnd == std::string::npos) return false;
                const std::string storedTable = line.substr(pos, tableEnd - pos);
                pos = tableEnd + 1;
                const size_t ridEnd = line.find(' ', pos);
                if (ridEnd == std::string::npos) return false;
                PreparedTransactionRecord::LogEntry entry;
                if (op == "INSERT") entry.op = PreparedTransactionRecord::LogEntry::Op::Insert;
                else if (op == "UPDATE") entry.op = PreparedTransactionRecord::LogEntry::Op::Update;
                else if (op == "DELETE") entry.op = PreparedTransactionRecord::LogEntry::Op::Delete;
                else return false;
                if (record.format >= 5) {
                    if (!preparedHexDecode(storedTable, entry.tableName)) return false;
                } else {
                    entry.tableName = storedTable;
                }
                if (entry.tableName.empty() ||
                    !validStoredIdentifier(entry.tableName, MAX_TABLE_NAME_LEN)) {
                    return false;
                }
                const std::string rowRid = line.substr(pos, ridEnd - pos);
                size_t consumed = 0;
                entry.rowIdx = std::stoll(rowRid, &consumed);
                if (consumed != rowRid.size()) return false;
                pos = ridEnd + 1;
                if (record.format >= 3) {
                    const size_t previousRidEnd = line.find(' ', pos);
                    if (previousRidEnd == std::string::npos) return false;
                    const std::string previousRid =
                        line.substr(pos, previousRidEnd - pos);
                    consumed = 0;
                    entry.previousRowIdx = std::stoll(previousRid, &consumed);
                    if (consumed != previousRid.size()) return false;
                    pos = previousRidEnd + 1;
                }
                std::string oldRowHex;
                std::string newRowHex;
                if (record.format >= 4) {
                    const size_t oldRowEnd = line.find(' ', pos);
                    if (oldRowEnd == std::string::npos) return false;
                    oldRowHex = line.substr(pos, oldRowEnd - pos);
                    newRowHex = line.substr(oldRowEnd + 1);
                } else {
                    oldRowHex = line.substr(pos);
                }
                if (!preparedHexDecode(oldRowHex, entry.rowData) ||
                    (record.format >= 4 &&
                     !preparedHexDecode(newRowHex, entry.newRowData))) {
                    return false;
                }
                record.log.push_back(std::move(entry));
            } else if (line.rfind("LOGICAL ", 0) == 0) {
                if (!hasFormat || record.format < 6) return false;
                std::istringstream logicalLine(line.substr(8));
                std::string op;
                std::string encodedTable;
                std::string encodedOldRow;
                std::string encodedNewRow;
                std::string extra;
                if (!(logicalLine >> op >> encodedTable >> encodedOldRow >>
                      encodedNewRow) ||
                    (logicalLine >> extra)) {
                    return false;
                }
                LogicalChange change;
                if (op == "INSERT") {
                    change.op = LogicalChange::Op::Insert;
                } else if (op == "UPDATE") {
                    change.op = LogicalChange::Op::Update;
                } else if (op == "DELETE") {
                    change.op = LogicalChange::Op::Delete;
                } else {
                    return false;
                }
                if (!preparedHexDecode(encodedTable, change.table) ||
                    change.table.empty() ||
                    !validStoredIdentifier(change.table, MAX_TABLE_NAME_LEN) ||
                    !preparedHexDecode(encodedOldRow, change.oldRow) ||
                    !preparedHexDecode(encodedNewRow, change.newRow)) {
                    return false;
                }
                record.logicalChanges.push_back(std::move(change));
            } else if (!line.empty()) {
                return false;
            }
        } catch (...) {
            return false;
        }
    }
    if (!input.eof()) return false;
    return hasFormat && hasTxnId && hasDbname && hasIsolation && record.txnId != 0 &&
           !record.dbname.empty() && record.dbname.find('\n') == std::string::npos &&
           record.dbname.find('\r') == std::string::npos &&
           record.dbname.find('/') == std::string::npos &&
           record.dbname.find('\\') == std::string::npos &&
           record.dbname != "." && record.dbname != "..";
}

enum class PreparedTerminalState {
    InDoubt,
    Committed,
    Aborted,
    Corrupt
};

static PreparedTerminalState preparedTerminalState(
    const StorageEngine& engine, const std::string& dbname, uint64_t xid) {
    if (CommitLog* clog = engine.getCommitLog(dbname); clog) {
        const CommitLog::Status status = clog->getStatus(xid);
        if (status == CommitLog::Status::Committed) {
            return PreparedTerminalState::Committed;
        }
        if (status == CommitLog::Status::Aborted) {
            return PreparedTerminalState::Aborted;
        }
    }

    // CLOG can legitimately be unavailable immediately after a durable
    // terminal record.  Consult retained WAL so stale prepared metadata is
    // not mistaken for an in-doubt transaction in that window.
    WALManager* wal = engine.getWAL(dbname);
    if (!wal) return PreparedTerminalState::InDoubt;
    PreparedTerminalState result = PreparedTerminalState::InDoubt;
    for (Lsn lsn = wal->earliestAvailableLsn();;) {
        const auto record = wal->ReadRecord(lsn);
        if (!record || record->header.xl_tot_len == 0) break;
        if (record->rmid() == RM_XACT_ID &&
            (record->info() == XLOG_XACT_COMMIT ||
             record->info() == XLOG_XACT_ABORT)) {
            uint64_t recordXid = 0;
            if (!decodeXactWalRecord(*record, recordXid)) {
                return PreparedTerminalState::Corrupt;
            }
            if (recordXid == xid) {
                const PreparedTerminalState next =
                    record->info() == XLOG_XACT_COMMIT
                        ? PreparedTerminalState::Committed
                        : PreparedTerminalState::Aborted;
                if (result != PreparedTerminalState::InDoubt) {
                    return PreparedTerminalState::Corrupt;
                }
                result = next;
            }
        }
        lsn += record->header.xl_tot_len;
    }
    return result;
}

DBStatus StorageEngine::prepareTransaction(const std::string& xid) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    if (!transactionContext().ddlUndoActions.empty()) {
        // DDL undo callbacks are backend-local closures. Do not prepare a
        // transaction whose rollback semantics cannot survive this backend's
        // in-memory context; callers must commit/rollback it directly.
        return DBStatus::INVALID_VALUE;
    }

    // PREPARE is the last point at which backend-local deferred checks are
    // available.  Validate them before publishing any prepared state; a
    // COMMIT PREPARED may run in another process and cannot reconstruct this
    // queue from the row undo log.
    {
        auto it = transactionContext().deferredChecks.find(
            transactionContext().currentTxnId);
        if (it != transactionContext().deferredChecks.end()) {
            for (const auto& dc : it->second) {
                if (!runDeferredCheck(dc)) {
                    rollbackTransaction();
                    return DBStatus::INVALID_VALUE;
                }
            }
            transactionContext().deferredChecks.erase(it);
        }
    }

    auto& preparingContext = transactionContext();
    for (const auto& entry : preparingContext.txnLog) {
        preparingContext.specializedIndexTables.insert(entry.tableName);
    }
    // PREPARE is a physical hand-off to a potentially different backend.
    // Reacquire each modified table's writer token and retain it as prepared
    // ownership, so the selected heap/index caches cannot change while they
    // are published. Unrelated active tables stay entirely untouched.
    for (const auto& tableName : preparingContext.specializedIndexTables) {
        if (!tableExists(preparingContext.txnDB, tableName)) continue;
        if (!lockManager_.lockIntentExclusive(tableName)) {
            return DBStatus::LOCK_CONFLICT;
        }
    }
    if (!flushTableCaches(
            preparingContext.txnDB,
            preparingContext.specializedIndexTables)) {
        return DBStatus::IO_ERROR;
    }

    std::filesystem::path pdir = preparedDir();
    if (!std::filesystem::exists(pdir)) {
        std::filesystem::create_directories(pdir);
    }
    std::filesystem::path pfile = preparedPath(xid);
    if (std::filesystem::exists(pfile)) return DBStatus::DUPLICATE_KEY;

    std::ostringstream prepared;

    // Transaction metadata
    prepared << "PREPARED_FORMAT " << PreparedTransactionRecord::CURRENT_FORMAT << "\n";
    prepared << "TXN_ID " << transactionContext().currentTxnId << "\n";
    prepared << "DBNAME " << preparedHexEncode(transactionContext().txnDB) << "\n";
    prepared << "ISOLATION " << static_cast<int>(transactionContext().txnIsolationLevel) << "\n";
    prepared << "READONLY " << (transactionContext().readOnly ? 1 : 0) << "\n";

    // Held locks use a versioned, structured representation. A new process
    // must be able to reacquire the same advisory resources after restart;
    // thread IDs and internal namespace separators are not durable data.
    std::vector<LockManager::PreparedLockInfo> locks;
    if (!lockManager_.getPreparedLockInfos(locks)) return DBStatus::CORRUPTED_DATA;
    for (const auto& lock : locks) {
        const char* mode = preparedLockModeName(lock.mode);
        if (!mode || lock.dbname != transactionContext().txnDB || lock.table.empty()) {
            return DBStatus::CORRUPTED_DATA;
        }
        switch (lock.kind) {
            case LockManager::PreparedLockInfo::Kind::Table:
                prepared << "LOCK TABLE " << mode << " "
                         << preparedHexEncode(lock.table) << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Row:
                prepared << "LOCK ROW " << mode << " "
                         << preparedHexEncode(lock.table) << " " << lock.rid << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Page:
                prepared << "LOCK PAGE " << mode << " "
                         << preparedHexEncode(lock.table) << " " << lock.pageId << "\n";
                break;
            case LockManager::PreparedLockInfo::Kind::Gap:
                prepared << "LOCK GAP " << preparedHexEncode(lock.table) << " "
                         << preparedHexEncode(lock.leftKey) << " "
                         << preparedHexEncode(lock.rightKey) << "\n";
                break;
        }
    }

    // Transaction log
    for (const auto& entry : transactionContext().txnLog) {
        prepared << "LOG ";
        if (entry.op == TxnLogEntry::Op::Insert) prepared << "INSERT";
        else if (entry.op == TxnLogEntry::Op::Update) prepared << "UPDATE";
        else if (entry.op == TxnLogEntry::Op::Delete) prepared << "DELETE";
        prepared << " " << preparedHexEncode(entry.tableName) << " " << entry.rowIdx << " "
                 << entry.previousRowIdx << " "
                 << preparedHexEncode(entry.rowData) << " "
                 << preparedHexEncode(entry.newRowData) << "\n";
    }
    for (const auto& change : transactionContext().txnLogicalChanges) {
        const char* op = nullptr;
        if (change.op == 0) op = "INSERT";
        else if (change.op == 1) op = "UPDATE";
        else if (change.op == 2) op = "DELETE";
        if (!op || change.table.empty() ||
            !validStoredIdentifier(change.table, MAX_TABLE_NAME_LEN)) {
            return DBStatus::CORRUPTED_DATA;
        }
        prepared << "LOGICAL " << op << " "
                 << preparedHexEncode(change.table) << " "
                 << preparedHexEncode(change.oldRow) << " "
                 << preparedHexEncode(change.newRow) << "\n";
    }
    if (!writePreparedFileAtomically(pfile, prepared.str())) {
        return DBStatus::IO_ERROR;
    }
    const Lsn prepareLsn = walXactPrepare(transactionContext().txnDB,
                                           transactionContext().currentTxnId);
    WALManager* wal = getWAL(transactionContext().txnDB);
    if (prepareLsn == INVALID_LSN || !wal || !wal->XLogFlush(prepareLsn)) {
        (void)removePreparedFileDurably(pfile);
        return DBStatus::IO_ERROR;
    }

    if (!lockManager_.suspendCurrentLocksForPrepared(transactionContext().currentTxnId)) {
        (void)removePreparedFileDurably(pfile);
        return DBStatus::LOCK_CONFLICT;
    }

    // Keep a prepared xid in the global active set.  Its backend-local state
    // is suspended below, but its heap versions remain in progress until
    // COMMIT/ROLLBACK PREPARED.  Recovery registers prepared xids the same
    // way after a restart.

    // Clear transaction state but KEEP locks (2PC semantics)
    transactionContext().txnLog.clear();
    transactionContext().txnLogicalChanges.clear();
    transactionContext().specializedIndexTables.clear();
    transactionContext().snapshotImported = false;
    transactionContext().hasRead = false;
    transactionContext().hasWrite = false;
    transactionContext().savepoints.clear();
    transactionContext().txnSubTxnIds.clear();
    transactionContext().txnLoggedBeforePages.clear();
    transactionContext().constraintMode.clear();
    clearCatalogSnapshot();

    {
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadSets_.erase(transactionContext().currentTxnId);
        ssiWriteSets_.erase(transactionContext().currentTxnId);
        ssiReadRelations_.erase(transactionContext().currentTxnId);
        ssiWriteRelations_.erase(transactionContext().currentTxnId);
        ssiReadPages_.erase(transactionContext().currentTxnId);
        ssiWritePages_.erase(transactionContext().currentTxnId);
        ssiReadIndexPredicates_.erase(transactionContext().currentTxnId);
        ssiWriteIndexKeys_.erase(transactionContext().currentTxnId);
        ssiOutEdges_.erase(transactionContext().currentTxnId);
        for (auto& [k, v] : ssiInEdges_) v.erase(transactionContext().currentTxnId);
        ssiInEdges_.erase(transactionContext().currentTxnId);
        for (auto& [k, v] : ssiOutEdges_) v.erase(transactionContext().currentTxnId);
    }
    transactionContext().txnReadRids.clear();
    transactionContext().txnWrittenRids.clear();
    transactionContext().txnReadRelations.clear();
    transactionContext().txnWrittenRelations.clear();
    transactionContext().txnReadPages.clear();
    transactionContext().txnWrittenPages.clear();
    transactionContext().txnHeapWritebackPages.clear();
    transactionContext().txnReadIndexPredicates.clear();
    transactionContext().txnWrittenIndexKeys.clear();

    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    // The database transaction mutex is a backend-local implementation lock;
    // it cannot be unlocked safely by COMMIT/ROLLBACK PREPARED on another
    // thread. Physical table/row/page/gap ownership has already been
    // transferred by LockManager, so release this session lock at PREPARE.
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();
    transactionContext().txnBackupPath.clear();
    transactionContext().transactionBackupDirty = false;
    transactionContext().restoreBackupBeforeRowUndo = false;
    transactionContext().ddlUndoSizeAtBackup = 0;
    transactionContext().preserveBackupOnRollback = false;
    transactionContext().txnDB.clear();
    return DBStatus::OK;
}

DBStatus StorageEngine::commitPrepared(const std::string& xid) {
    if (transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    std::filesystem::path pfile = preparedPath(xid);
    if (!std::filesystem::exists(pfile)) return DBStatus::TABLE_NOT_FOUND;

    PreparedTransactionRecord record;
    if (!readPreparedRecord(pfile, record)) return DBStatus::CORRUPTED_DATA;
    const uint64_t savedTxnId = record.txnId;
    const std::string& savedDB = record.dbname;
    if (!databaseExists(savedDB)) return DBStatus::CORRUPTED_DATA;

    const PreparedTerminalState priorState =
        preparedTerminalState(*this, savedDB, savedTxnId);
    if (priorState == PreparedTerminalState::Corrupt) {
        return DBStatus::CORRUPTED_DATA;
    }
    if (priorState != PreparedTerminalState::InDoubt) {
        lockManager_.releasePreparedLocks(savedTxnId);
        if (!removePreparedFileDurably(pfile)) {
            std::cerr << "[2PC] could not remove terminal prepared metadata: "
                      << pfile << std::endl;
        }
        return priorState == PreparedTerminalState::Committed
            ? DBStatus::OK : DBStatus::INVALID_VALUE;
    }

    std::set<std::string> specializedTables;
    for (const auto& entry : record.log) {
        specializedTables.insert(entry.tableName);
    }
    lockManager_.setResourceNamespace(savedDB);
    for (const auto& tableName : specializedTables) {
        if (!tableExists(savedDB, tableName)) continue;
        if (!lockManager_.lockIntentExclusiveForPrepared(
                tableName, savedTxnId)) {
            lockManager_.unlockAll();
            return DBStatus::LOCK_CONFLICT;
        }
    }
    for (const auto& tableName : specializedTables) {
        if (tableExists(savedDB, tableName) &&
            !refreshPreparedTableCaches(savedDB, tableName)) {
            lockManager_.unlockAll();
            return DBStatus::IO_ERROR;
        }
    }

    // PREPARE deliberately left the old whole-file sidecars in place while
    // its xid stayed globally active.  Build the future committed generation
    // now, using a temporary view in which the prepared xid is the creator.
    auto& completionContext = transactionContext();
    const ReadView savedReadView = completionContext.readView;
    const IsolationLevel savedIsolation =
        completionContext.txnIsolationLevel;
    completionContext.currentTxnId = savedTxnId;
    completionContext.txnDB = savedDB;
    completionContext.inTransaction = true;
    completionContext.txnIsolationLevel = IsolationLevel::READ_COMMITTED;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        completionContext.readView.creatorTxnId = savedTxnId;
        completionContext.readView.lowLimitId =
            TxnIdGenerator::instance().maxCommittedTxId() + 1;
        completionContext.readView.upLimitId = activeTransactions_.empty()
            ? completionContext.readView.lowLimitId
            : *activeTransactions_.begin();
        completionContext.readView.activeTxnIds = activeTransactions_;
        completionContext.readView.activeTxnIds.erase(savedTxnId);
        completionContext.readView.subTxnIds.clear();
        completionContext.readView.commitLog = getCommitLog(savedDB);
    }
    bool specializedIndexesOk = true;
    for (const auto& tableName : specializedTables) {
        if (!tableExists(savedDB, tableName)) continue;
        if (!rebuildSpecializedIndexes(
                savedDB, tableName, /*clearDirtyState=*/false)) {
            specializedIndexesOk = false;
            break;
        }
    }
    completionContext.readView = savedReadView;
    completionContext.txnIsolationLevel = savedIsolation;
    completionContext.currentTxnId = 0;
    completionContext.inTransaction = false;
    completionContext.hasRead = false;
    completionContext.hasWrite = false;
    completionContext.txnDB.clear();
    if (!specializedIndexesOk) {
        lockManager_.unlockAll();
        return DBStatus::IO_ERROR;
    }

    // WAL COMMIT PREPARED marker. Keep the prepared transaction durable and
    // retryable if WAL insertion or fsync fails.
    if (!flushTableCaches(savedDB, specializedTables)) {
        lockManager_.unlockAll();
        return DBStatus::IO_ERROR;
    }
    WALManager* wal = getWAL(savedDB);
    if (!wal) {
        lockManager_.unlockAll();
        return DBStatus::IO_ERROR;
    }
    Lsn commitLsn = walXactCommit(savedDB, savedTxnId);
    if (commitLsn == INVALID_LSN || !wal->XLogFlush(commitLsn)) {
        lockManager_.unlockAll();
        return DBStatus::IO_ERROR;
    }

    // PREPARE persisted the publication-filtered row images. Publish them
    // only after the terminal COMMIT record is durable, matching ordinary
    // commit semantics without retaining backend-local state.
    publishLogicalChanges(
        record.logicalChanges, savedTxnId, static_cast<uint64_t>(commitLsn));

    CommitLog* clog = getCommitLog(savedDB);
    if (clog) {
        clog->setStatus(savedTxnId, CommitLog::Status::Committed);
        if (!clog->flush()) {
            std::cerr
                << "[CLOG] COMMIT PREPARED WAL is durable but CLOG publication failed for "
                << savedDB << ":" << savedTxnId
                << "; treating the transaction as committed and relying on WAL recovery"
                << std::endl;
        }
    }

    for (const auto& tableName : specializedTables) {
        if (!tableExists(savedDB, tableName)) continue;
        if (!clearSpecializedIndexDirty(*this, savedDB, tableName)) {
            std::cerr
                << "[index] committed prepared transaction with marker retained for "
                << savedDB << "/" << tableName << std::endl;
        }
    }

    // Normal commit logic
    TxnIdGenerator::instance().notifyCommit(savedTxnId);
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex_);
        activeTransactions_.erase(savedTxnId);
        activeTransactionDatabases_.erase(savedTxnId);
    }

    transactionContext().txnLog.clear();
    transactionContext().specializedIndexTables.clear();
    transactionContext().savepoints.clear();
    std::error_code backupEc;
    std::filesystem::remove_all(transactionBackupPath(savedDB, savedTxnId), backupEc);
    lockManager_.unlockAll();
    lockManager_.releasePreparedLocks(savedTxnId);
    transactionContext().currentTxnId = 0;
    transactionContext().inTransaction = false;
    transactionContext().readOnly = false;
    transactionContext().txnBackupPath.clear();
    transactionContext().txnDB.clear();
    transactionContext().databaseExclusiveLock.reset();
    transactionContext().databaseSharedLock.reset();
    transactionContext().databaseTxnMutex.reset();

    if (!removePreparedFileDurably(pfile)) {
        // The COMMIT decision is already durable.  Recovery recognizes the
        // terminal WAL record and removes stale metadata; reporting a
        // retryable error here could generate a duplicate terminal record.
        std::cerr << "[2PC] committed with prepared metadata retained for recovery: "
                  << pfile << std::endl;
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::rollbackPrepared(const std::string& xid) {
    if (transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (!validPreparedXid(xid)) return DBStatus::INVALID_VALUE;
    std::filesystem::path pfile = preparedPath(xid);
    if (!std::filesystem::exists(pfile)) return DBStatus::TABLE_NOT_FOUND;

    PreparedTransactionRecord record;
    if (!readPreparedRecord(pfile, record)) return DBStatus::CORRUPTED_DATA;
    const uint64_t savedTxnId = record.txnId;
    const std::string& savedDB = record.dbname;
    if (!databaseExists(savedDB)) return DBStatus::CORRUPTED_DATA;

    const PreparedTerminalState priorState =
        preparedTerminalState(*this, savedDB, savedTxnId);
    if (priorState == PreparedTerminalState::Corrupt) {
        return DBStatus::CORRUPTED_DATA;
    }
    if (priorState != PreparedTerminalState::InDoubt) {
        lockManager_.releasePreparedLocks(savedTxnId);
        if (!removePreparedFileDurably(pfile)) {
            std::cerr << "[2PC] could not remove terminal prepared metadata: "
                      << pfile << std::endl;
        }
        return priorState == PreparedTerminalState::Aborted
            ? DBStatus::OK : DBStatus::INVALID_VALUE;
    }

    std::set<std::string> specializedTables;
    for (const auto& entry : record.log) {
        specializedTables.insert(entry.tableName);
    }
    lockManager_.setResourceNamespace(savedDB);
    for (const auto& tableName : specializedTables) {
        if (!tableExists(savedDB, tableName)) continue;
        if (!lockManager_.lockIntentExclusiveForPrepared(
                tableName, savedTxnId)) {
            lockManager_.unlockAll();
            return DBStatus::LOCK_CONFLICT;
        }
    }
    for (const auto& tableName : specializedTables) {
        if (tableExists(savedDB, tableName) &&
            !refreshPreparedTableCaches(savedDB, tableName)) {
            lockManager_.unlockAll();
            return DBStatus::IO_ERROR;
        }
    }

    // Temporarily restore state and use normal rollback
    transactionContext().currentTxnId = savedTxnId;
    transactionContext().txnDB = savedDB;
    transactionContext().txnBackupPath = transactionBackupPath(savedDB, savedTxnId).string();
    transactionContext().txnIsolationLevel = record.isolation;
    transactionContext().inTransaction = true;
    transactionContext().txnLog.clear();
    transactionContext().specializedIndexTables.clear();
    transactionContext().txnLog.reserve(record.log.size());
    for (const auto& entry : record.log) {
        TxnLogEntry restored;
        if (entry.op == PreparedTransactionRecord::LogEntry::Op::Insert) {
            restored.op = TxnLogEntry::Op::Insert;
        } else if (entry.op == PreparedTransactionRecord::LogEntry::Op::Update) {
            restored.op = TxnLogEntry::Op::Update;
        } else {
            restored.op = TxnLogEntry::Op::Delete;
        }
        restored.tableName = entry.tableName;
        restored.rowIdx = entry.rowIdx;
        restored.rowData = entry.rowData;
        restored.newRowData = entry.newRowData;
        restored.previousRowIdx = entry.previousRowIdx;
        transactionContext().txnLog.push_back(std::move(restored));
    }

    DBStatus res = rollbackTransaction();
    if (res != DBStatus::OK) return res;
    lockManager_.releasePreparedLocks(savedTxnId);
    if (!removePreparedFileDurably(pfile)) {
        std::cerr << "[2PC] aborted with prepared metadata retained for recovery: "
                  << pfile << std::endl;
    }
    return DBStatus::OK;
}

std::vector<std::string> StorageEngine::listPreparedTransactions() const {
    std::vector<std::string> result;
    std::filesystem::path pdir = preparedDir();
    if (!std::filesystem::exists(pdir)) return result;
    for (const auto& entry : std::filesystem::directory_iterator(pdir)) {
        if (entry.is_regular_file()) {
            PreparedTransactionRecord record;
            if (readPreparedRecord(entry.path(), record) &&
                databaseExists(record.dbname)) {
                const PreparedTerminalState state = preparedTerminalState(
                    *this, record.dbname, record.txnId);
                if (state == PreparedTerminalState::Committed ||
                    state == PreparedTerminalState::Aborted) {
                    continue;
                }
            }
            result.push_back(entry.path().filename().string());
        }
    }
    return result;
}

// ========================================================================
// Savepoint support
// ========================================================================

DBStatus StorageEngine::savepoint(const std::string& name) {
    if (!transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
    if (transactionContext().transactionBackupDirty) {
        // A full DDL snapshot cannot safely describe a savepoint created
        // after the physical mutation. Fail closed until object-level DDL
        // savepoint images are available.
        return DBStatus::INVALID_VALUE;
    }
    auto& context = transactionContext();
    const auto deferred = context.deferredChecks.find(context.currentTxnId);
    const size_t deferredCheckSize = deferred == context.deferredChecks.end()
        ? 0 : deferred->second.size();
    context.savepoints.push_back({
        name,
        context.txnLog.size(),
        context.ddlUndoActions.size(),
        deferredCheckSize,
        context.txnLogicalChanges.size(),
        lockManager_.captureCheckpoint()
    });
    return DBStatus::OK;
}

DBStatus StorageEngine::rollbackToSavepoint(const std::string& name) {
    auto& context = transactionContext();
    if (!context.inTransaction) return DBStatus::INVALID_VALUE;
    if (context.transactionBackupDirty) return DBStatus::INVALID_VALUE;
    const auto reverseIt = std::find_if(
        context.savepoints.rbegin(), context.savepoints.rend(),
        [&](const TransactionContext::SavepointState& savepoint) {
            return savepoint.name == name;
        });
    if (reverseIt == context.savepoints.rend()) {
        return DBStatus::INVALID_VALUE;
    }
    const size_t savepointIndex = static_cast<size_t>(std::distance(
        context.savepoints.begin(), reverseIt.base()) - 1);
    const TransactionContext::SavepointState target = *reverseIt;
    const size_t txnLogSpIdx = target.txnLogSize;
    const size_t ddlSpIdx = target.ddlUndoSize;
    const size_t deferredCheckSpIdx = target.deferredCheckSize;
    const size_t logicalChangeSpIdx = target.logicalChangeSize;
    const auto deferredChecks = context.deferredChecks.find(
        context.currentTxnId);
    const size_t currentDeferredCheckSize =
        deferredChecks == context.deferredChecks.end()
            ? 0 : deferredChecks->second.size();
    if (txnLogSpIdx > context.txnLog.size() ||
        ddlSpIdx > context.ddlUndoActions.size() ||
        deferredCheckSpIdx > currentDeferredCheckSize ||
        logicalChangeSpIdx > context.txnLogicalChanges.size()) {
        return DBStatus::INVALID_VALUE;
    }

    bool rowUndoOk = true;
    std::set<BloomIndex*> bloomUndoIndexes;
    const auto removeSecondaryRid = [&](BPTree* index,
                                        const std::string& key,
                                        int64_t rid) {
        if (!index || (!index->isOpen() && !index->open())) return false;
        while (true) {
            const auto rids = index->searchMulti(key);
            const size_t occurrences = static_cast<size_t>(std::count(
                rids.begin(), rids.end(), rid));
            if (occurrences == 0) return true;
            for (size_t occurrence = 0; occurrence < occurrences;
                 ++occurrence) {
                if (!index->removeMulti(key, rid)) return false;
            }
        }
    };
    const auto removeHashRid = [&](HashIndex* index,
                                   const std::string& key,
                                   int64_t rid) {
        if (!index || (!index->isOpen() && !index->open())) return false;
        while (true) {
            const auto rids = index->search(key);
            const size_t occurrences = static_cast<size_t>(std::count(
                rids.begin(), rids.end(), rid));
            if (occurrences == 0) return true;
            for (size_t occurrence = 0; occurrence < occurrences;
                 ++occurrence) {
                if (!index->remove(key, rid)) return false;
            }
        }
    };
    const auto removeBloomRid = [&](BloomIndex* index,
                                    const std::string& key,
                                    int64_t rid) {
        if (!index || (!index->isOpen() && !index->open())) return false;
        while (true) {
            const auto rids = index->search(key);
            const size_t occurrences = static_cast<size_t>(std::count(
                rids.begin(), rids.end(), rid));
            if (occurrences == 0) return true;
            for (size_t occurrence = 0; occurrence < occurrences;
                 ++occurrence) {
                if (!index->remove(key, rid)) return false;
            }
        }
    };
    // Undo entries from end back to savepoint
    for (size_t i = transactionContext().txnLog.size(); i > txnLogSpIdx; --i) {
        auto& entry = transactionContext().txnLog[i - 1];
        PageAllocator* pa = getPageAllocator(transactionContext().txnDB, entry.tableName);
        TableSchema tbl = getTableSchema(transactionContext().txnDB, entry.tableName);
        if (entry.op == TxnLogEntry::Op::Insert) {
            // Remove from indexes first (row still exists). INSERT may have
            // failed after only a prefix of its access-method writes. Missing
            // mappings are therefore already-undone state, not rollback
            // failures; remove only exact mappings owned by this RID.
            std::string insertedRow = entry.rowData;
            std::string heapRow;
            if (readRowByRid(pa, entry.rowIdx, heapRow, tbl)) {
                insertedRow = std::move(heapRow);
            } else {
                rowUndoOk = false;
            }
            if (insertedRow.empty()) {
                rowUndoOk = false;
            } else if (tbl.hasPrimaryKey()) {
                BPTree* pkIdx = getPKIndex(
                    transactionContext().txnDB, entry.tableName);
                const std::string pkVal = extractPKValue(
                    insertedRow, tbl, transactionContext().txnDB);
                if (!pkIdx || (!pkIdx->isOpen() && !pkIdx->open()) ||
                    pkVal.empty()) {
                    rowUndoOk = false;
                } else {
                    int64_t indexedRid = -1;
                    if (pkIdx->search(pkVal, indexedRid) &&
                        indexedRid == entry.rowIdx &&
                        !pkIdx->remove(pkVal)) {
                        rowUndoOk = false;
                    }
                }
            }
            for (const auto& metadata : getIndexMetadata(
                     transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                EvaluatedIndexEntry indexEntry;
                if (!secondaryIndexEntryFromBuffer(
                        *this, metadata, tbl, insertedRow,
                        transactionContext().txnDB, indexEntry)) {
                    rowUndoOk = false;
                    continue;
                }
                if (!indexEntry.included || indexEntry.key.empty()) continue;
                BPTree* index = getSecondaryIndex(
                    transactionContext().txnDB, entry.tableName,
                    metadata.name);
                if (!removeSecondaryRid(
                        index, indexEntry.key, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                EvaluatedIndexEntry indexEntry;
                if (!compositeIndexEntryFromBuffer(
                        *this, ci, tbl, insertedRow,
                        transactionContext().txnDB, indexEntry)) {
                    rowUndoOk = false;
                    continue;
                }
                if (!indexEntry.included || indexEntry.key.empty()) continue;
                BPTree* index = getCompositeIndexTree(
                    transactionContext().txnDB, entry.tableName, ci.name);
                if (!removeSecondaryRid(
                        index, indexEntry.key, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) { colIdx = j; break; }
                }
                if (colIdx >= tbl.len) {
                    rowUndoOk = false;
                    continue;
                }
                std::string value = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        insertedRow, tbl, colIdx,
                        transactionContext().txnDB));
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!value.empty() &&
                    !removeHashRid(hashIdx, value, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& colname : getBloomIndexedColumns(
                     transactionContext().txnDB, entry.tableName)) {
                if (insertedRow.empty()) continue;
                size_t colIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == colname) {
                        colIdx = j;
                        break;
                    }
                }
                if (colIdx >= tbl.len) {
                    rowUndoOk = false;
                    continue;
                }
                const std::string value = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        insertedRow, tbl, colIdx,
                        transactionContext().txnDB));
                BloomIndex* bloomIdx = getBloomIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!bloomIdx ||
                    (!bloomIdx->isOpen() && !bloomIdx->open())) {
                    rowUndoOk = false;
                    continue;
                }
                bloomUndoIndexes.insert(bloomIdx);
                if (!value.empty() &&
                    !removeBloomRid(bloomIdx, value, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            if (!insertedRow.empty()) {
                // Preserve external values until every logical index key has
                // been removed from the access methods.
                deleteRowToast(transactionContext().txnDB, entry.tableName,
                               entry.rowIdx);
            }
            // Then remove the row from page
            uint32_t pageId; uint16_t slotId;
            decodeRid(entry.rowIdx, pageId, slotId);
            if (!pa) {
                rowUndoOk = false;
            } else {
                char* pageBuf = pa->fetchPage(pageId);
                if (!pageBuf) {
                    rowUndoOk = false;
                } else {
                    PageWrapper page(
                        pageBuf, pa->pageSize(), tbl.formatVersion);
                    const char* currentData = nullptr;
                    size_t currentLength = 0;
                    if (!page.isValid() ||
                        !page.read(slotId, currentData, currentLength)) {
                        rowUndoOk = false;
                    } else {
                        const Lsn beforeLsn = walPageImage(
                            transactionContext().txnDB, entry.tableName,
                            pageId, pageBuf, pa->pageSize(), true);
                        std::vector<char> stagedPage(
                            pageBuf, pageBuf + pa->pageSize());
                        PageWrapper staged(
                            stagedPage.data(), pa->pageSize(),
                            tbl.formatVersion);
                        if (beforeLsn == INVALID_LSN ||
                            !staged.remove(slotId)) {
                            rowUndoOk = false;
                        } else {
                            const Lsn lsn = walPageImage(
                                transactionContext().txnDB,
                                entry.tableName, pageId,
                                stagedPage.data(), pa->pageSize(), false);
                            WALManager* wal = getWAL(
                                transactionContext().txnDB);
                            if (lsn == INVALID_LSN || !wal ||
                                !wal->XLogFlush(lsn)) {
                                rowUndoOk = false;
                            } else {
                                std::memcpy(
                                    pageBuf, stagedPage.data(),
                                    pa->pageSize());
                                setPageLsnAndChecksum(pageBuf, lsn);
                                pa->markDirty(pageId);
                                const size_t freePercent =
                                    staged.freeSpace() * 100 /
                                    pa->pageSize();
                                getFSM(
                                    transactionContext().txnDB,
                                    entry.tableName)->setFreePercent(
                                        pageId,
                                        static_cast<uint8_t>(freePercent));
                                getVM(
                                    transactionContext().txnDB,
                                    entry.tableName)->setAllVisible(
                                        pageId, false);
                                if (!pa->flush()) rowUndoOk = false;
                            }
                        }
                    }
                    pa->unpinPage(pageId);
                }
            }
        } else if (entry.op == TxnLogEntry::Op::Update) {
            if (entry.previousRowIdx >= 0) {
                if (!undoVersionedUpdate(entry)) rowUndoOk = false;
                continue;
            }
            uint32_t pageId; uint16_t slotId;
            decodeRid(entry.rowIdx, pageId, slotId);
            char* pageBuf = pa->fetchPage(pageId);
            std::string currentRow;
            bool foundCurrent = false;
            if (pageBuf) {
                PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
                walPageImage(transactionContext().txnDB, entry.tableName, pageId,
                             pageBuf, pa->pageSize(), true);
                // Read current row data before restoring (needed to remove stale index entries)
                const char* currentData = nullptr;
                size_t currentLen = 0;
                if (page.read(slotId, currentData, currentLen) && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    currentRow = stripRowHeader(currentData, currentLen, tbl.formatVersion, tbl.len);
                    foundCurrent = true;
                } else {
                    std::string targetPk = extractPKValue(
                        entry.rowData, tbl, transactionContext().txnDB);
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (foundCurrent || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(
                            rowData, tbl, transactionContext().txnDB);
                        if (pk == targetPk) {
                            currentRow = rowData;
                            foundCurrent = true;
                        }
                    });
                }
                // Restore old row data
                if (page.read(slotId, currentData, currentLen) && currentLen >= rowHeaderSize(tbl.formatVersion, tbl.len)) {
                    std::string fullRow = replaceRowData(
                        std::string(currentData, currentLen), entry.rowData, tbl.formatVersion, tbl.len);
                    setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                    page.update(slotId, fullRow.data(), fullRow.size());
                } else {
                    std::string targetPk = extractPKValue(
                        entry.rowData, tbl, transactionContext().txnDB);
                    bool restored = false;
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        if (restored || len <= rowHeaderSize(tbl.formatVersion, tbl.len)) return;
                        std::string rowData = stripRowHeader(data, len, tbl.formatVersion, tbl.len);
                        std::string pk = extractPKValue(
                            rowData, tbl, transactionContext().txnDB);
                        if (pk == targetPk) {
                            std::string fullRow = replaceRowData(
                                std::string(data, len), entry.rowData, tbl.formatVersion, tbl.len);
                            setRowXmin(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            setRowXmax(fullRow.data(), fullRow.size(), tbl.formatVersion, 0);
                            page.update(sid, fullRow.data(), fullRow.size());
                            restored = true;
                        }
                    });
                }
                pa->markDirty(pageId);
                Lsn lsn = walPageImage(transactionContext().txnDB, entry.tableName,
                                       pageId, pageBuf, pa->pageSize(), false);
                if (lsn != INVALID_LSN) {
                    setPageLsnAndChecksum(pageBuf, lsn);
                    pa->markDirty(pageId);
                }
                pa->flush();
                pa->unpinPage(pageId);
            }
            // Rebuild indexes: remove current (stale) values then insert restored values
            BPTree* pkIdx = getPKIndex(transactionContext().txnDB, entry.tableName);
            if (pkIdx) {
                if (foundCurrent) {
                    std::string currentPk = extractPKValue(
                        currentRow, tbl, transactionContext().txnDB);
                    if (!currentPk.empty()) pkIdx->remove(currentPk);
                }
                std::string newPk = extractPKValue(
                    entry.rowData, tbl, transactionContext().txnDB);
                if (!newPk.empty()) pkIdx->insert(newPk, entry.rowIdx);
            }
            for (const auto& metadata : getIndexMetadata(
                     transactionContext().txnDB, entry.tableName)) {
                BPTree* index = getSecondaryIndex(
                    transactionContext().txnDB, entry.tableName,
                    metadata.name);
                if (!index) {
                    rowUndoOk = false;
                    continue;
                }
                if (foundCurrent) {
                    EvaluatedIndexEntry indexEntry;
                    if (!secondaryIndexEntryFromBuffer(
                            *this, metadata, tbl, currentRow,
                            transactionContext().txnDB, indexEntry)) {
                        rowUndoOk = false;
                    } else if (indexEntry.included &&
                               !indexEntry.key.empty() &&
                               !index->removeMulti(
                                   indexEntry.key, entry.rowIdx)) {
                        rowUndoOk = false;
                    }
                }
                EvaluatedIndexEntry indexEntry;
                if (!secondaryIndexEntryFromBuffer(
                        *this, metadata, tbl, entry.rowData,
                        transactionContext().txnDB, indexEntry)) {
                    rowUndoOk = false;
                } else if (indexEntry.included &&
                           !indexEntry.key.empty() &&
                           !index->insertMulti(
                               indexEntry.key, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& ci : getCompositeIndexes(transactionContext().txnDB, entry.tableName)) {
                BPTree* index = getCompositeIndexTree(
                    transactionContext().txnDB, entry.tableName, ci.name);
                if (!index) {
                    rowUndoOk = false;
                    continue;
                }
                if (foundCurrent) {
                    EvaluatedIndexEntry indexEntry;
                    if (!compositeIndexEntryFromBuffer(
                            *this, ci, tbl, currentRow,
                            transactionContext().txnDB, indexEntry)) {
                        rowUndoOk = false;
                    } else if (indexEntry.included &&
                               !indexEntry.key.empty() &&
                               !index->removeMulti(
                                   indexEntry.key, entry.rowIdx)) {
                        rowUndoOk = false;
                    }
                }
                EvaluatedIndexEntry indexEntry;
                if (!compositeIndexEntryFromBuffer(
                        *this, ci, tbl, entry.rowData,
                        transactionContext().txnDB, indexEntry)) {
                    rowUndoOk = false;
                } else if (indexEntry.included &&
                           !indexEntry.key.empty() &&
                           !index->insertMulti(
                               indexEntry.key, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            for (const auto& colname : getHashIndexedColumns(transactionContext().txnDB, entry.tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
                }
                if (colIdx >= tbl.len) continue;
                HashIndex* hashIdx = getHashIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!hashIdx) continue;
                if (foundCurrent) {
                    std::string currentVal = canonicalColumnKeyValue(
                        tbl.cols[colIdx], extractColumnValue(
                            currentRow, tbl, colIdx,
                            transactionContext().txnDB));
                    if (!currentVal.empty()) hashIdx->remove(currentVal, entry.rowIdx);
                }
                std::string oldVal = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        entry.rowData, tbl, colIdx,
                        transactionContext().txnDB));
                if (!oldVal.empty()) hashIdx->insert(oldVal, entry.rowIdx);
            }
            for (const auto& colname : getBloomIndexedColumns(
                     transactionContext().txnDB, entry.tableName)) {
                size_t colIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == colname) {
                        colIdx = i;
                        break;
                    }
                }
                if (colIdx >= tbl.len) {
                    rowUndoOk = false;
                    continue;
                }
                BloomIndex* bloomIdx = getBloomIndex(
                    transactionContext().txnDB, entry.tableName, colname);
                if (!bloomIdx) {
                    rowUndoOk = false;
                    continue;
                }
                bloomUndoIndexes.insert(bloomIdx);
                if (foundCurrent) {
                    const std::string currentVal = canonicalColumnKeyValue(
                        tbl.cols[colIdx], extractColumnValue(
                            currentRow, tbl, colIdx,
                            transactionContext().txnDB));
                    if (!currentVal.empty() &&
                        !bloomIdx->remove(currentVal, entry.rowIdx)) {
                        rowUndoOk = false;
                    }
                }
                const std::string oldVal = canonicalColumnKeyValue(
                    tbl.cols[colIdx], extractColumnValue(
                        entry.rowData, tbl, colIdx,
                        transactionContext().txnDB));
                if (!oldVal.empty() &&
                    !bloomIdx->insert(oldVal, entry.rowIdx)) {
                    rowUndoOk = false;
                }
            }
            if (foundCurrent) {
                deleteToastForRowExcept(transactionContext().txnDB,
                                        entry.tableName, currentRow,
                                        entry.rowData);
            }
        } else if (entry.op == TxnLogEntry::Op::Delete) {
            if (!undoDeletedRow(entry, bloomUndoIndexes)) {
                rowUndoOk = false;
            }
        }
    }
    for (BloomIndex* index : bloomUndoIndexes) {
        if (!index->flush()) rowUndoOk = false;
    }

    // DDL CREATE undo actions follow the same savepoint boundary. Row undo
    // above runs first so a newly-created relation remains available while
    // its rows are being removed.
    bool ddlUndoOk = true;
    if (rowUndoOk) {
        for (size_t i = transactionContext().ddlUndoActions.size();
             i > ddlSpIdx; --i) {
            try {
                if (!transactionContext().ddlUndoActions[i - 1]()) {
                    ddlUndoOk = false;
                }
            } catch (...) {
                ddlUndoOk = false;
            }
        }
    }

    // Never discard undo records after a partial savepoint rollback.  The
    // transaction's heap and indexes may already disagree, so keeping it
    // active would expose a state that neither COMMIT nor a later ROLLBACK TO
    // could repair. Escalate to a full abort while every log entry is intact.
    if (!rowUndoOk || !ddlUndoOk) {
        (void)rollbackTransaction();
        return DBStatus::IO_ERROR;
    }

    transactionContext().txnLog.resize(txnLogSpIdx);
    transactionContext().txnLogicalChanges.resize(logicalChangeSpIdx);
    if (deferredChecks != transactionContext().deferredChecks.end()) {
        deferredChecks->second.resize(deferredCheckSpIdx);
    }
    transactionContext().ddlUndoActions.resize(ddlSpIdx);
    lockManager_.rollbackToCheckpoint(target.lockCheckpoint);

    // ROLLBACK TO retains the target but destroys every savepoint created
    // after it, even when no row or DDL changes separated their declarations.
    context.savepoints.erase(
        context.savepoints.begin() +
            static_cast<std::ptrdiff_t>(savepointIndex + 1),
        context.savepoints.end());
    return DBStatus::OK;
}

DBStatus StorageEngine::releaseSavepoint(const std::string& name) {
    auto& context = transactionContext();
    if (!context.inTransaction) return DBStatus::INVALID_VALUE;
    const auto reverseIt = std::find_if(
        context.savepoints.rbegin(), context.savepoints.rend(),
        [&](const TransactionContext::SavepointState& savepoint) {
            return savepoint.name == name;
        });
    if (reverseIt == context.savepoints.rend()) {
        return DBStatus::INVALID_VALUE;
    }
    const size_t savepointIndex = static_cast<size_t>(std::distance(
        context.savepoints.begin(), reverseIt.base()) - 1);
    // RELEASE destroys the named savepoint and every savepoint nested after
    // it. With duplicate names, reverse lookup releases only the newest one.
    context.savepoints.erase(
        context.savepoints.begin() +
            static_cast<std::ptrdiff_t>(savepointIndex),
        context.savepoints.end());
    return DBStatus::OK;
}

// ========================================================================
// Row-Level Security (RLS)
// ========================================================================

static bool writePolicyFile(const std::filesystem::path& path,
                            const std::vector<StorageEngine::RowPolicy>& policies) {
    std::ofstream ofs(path);
    if (!ofs) return false;
    for (const auto& p : policies) {
        ofs << "POLICY " << escapeString(p.name) << " " << p.cmd;
        ofs << " AS:" << (p.permissive ? "PERMISSIVE" : "RESTRICTIVE");
        ofs << " USING:" << escapeString(p.usingExpr);
        ofs << " WITHCHECK:" << escapeString(p.withCheckExpr);
        ofs << " ROLES:";
        for (size_t i = 0; i < p.roles.size(); ++i) {
            if (i > 0) ofs << ",";
            ofs << escapeString(p.roles[i]);
        }
        ofs << "\n";
    }
    return true;
}

std::filesystem::path StorageEngine::rlsPath(const std::string& dbname, const std::string& tablename) const {
    return dbPath(dbname) / (tablename + ".rls");
}

DBStatus StorageEngine::createPolicy(const std::string& dbname, const std::string& tablename,
                                      const RowPolicy& policy) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    for (const auto& p : policies) {
        if (p.name == policy.name) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    policies.push_back(policy);
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

DBStatus StorageEngine::alterPolicy(const std::string& dbname, const std::string& tablename,
                                     const std::string& policyName, const RowPolicy& policy) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    bool found = false;
    for (const auto& p : policies) {
        if (p.name == policy.name && policy.name != policyName) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    for (auto& p : policies) {
        if (p.name == policyName) {
            p = policy;
            found = true;
            break;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

DBStatus StorageEngine::dropPolicy(const std::string& dbname, const std::string& tablename,
                                    const std::string& policyName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    auto rpath = rlsPath(dbname, tablename);
    auto policies = getPolicies(dbname, tablename);
    bool found = false;
    for (auto it = policies.begin(); it != policies.end(); ) {
        if (it->name == policyName) {
            it = policies.erase(it);
            found = true;
        } else {
            ++it;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return writePolicyFile(rpath, policies) ? DBStatus::OK : DBStatus::INVALID_VALUE;
}

std::vector<StorageEngine::RowPolicy> StorageEngine::getPolicies(const std::string& dbname,
                                                                   const std::string& tablename) const {
    std::vector<RowPolicy> result;
    auto rpath = rlsPath(dbname, tablename);
    if (!std::filesystem::exists(rpath)) return result;
    std::ifstream ifs(rpath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.substr(0, 7) != "POLICY ") continue;
        size_t pos = 7;
        size_t sp = line.find(' ', pos);
        if (sp == std::string::npos) continue;
        RowPolicy p;
        p.name = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 1;
        sp = line.find(" AS:", pos);
        if (sp == std::string::npos) continue;
        p.cmd = line.substr(pos, sp - pos);
        pos = sp + 4;
        size_t modeEnd = line.find(" USING:", pos);
        if (modeEnd == std::string::npos) continue;
        const std::string mode = line.substr(pos, modeEnd - pos);
        if (mode == "PERMISSIVE") p.permissive = true;
        else if (mode == "RESTRICTIVE") p.permissive = false;
        else continue;
        pos = modeEnd + 7;
        sp = line.find(" WITHCHECK:", pos);
        if (sp == std::string::npos) continue;
        p.usingExpr = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 11;
        sp = line.find(" ROLES:", pos);
        if (sp == std::string::npos) continue;
        p.withCheckExpr = unescapeString(line.substr(pos, sp - pos));
        pos = sp + 7;
        std::string rolesStr = line.substr(pos);
        if (!rolesStr.empty()) {
            std::stringstream ss(rolesStr);
            std::string role;
            while (std::getline(ss, role, ',')) {
                if (!role.empty()) p.roles.push_back(unescapeString(role));
            }
        }
        result.push_back(p);
    }
    return result;
}

std::vector<StorageEngine::RowPolicy> StorageEngine::getApplicablePolicies(
    const std::string& dbname, const std::string& tablename,
    const std::string& cmd, const std::string& username) const {
    auto all = getPolicies(dbname, tablename);
    std::vector<RowPolicy> result;
    for (const auto& p : all) {
        if (p.cmd != "ALL" && p.cmd != cmd) continue;
        if (p.roles.empty()) {
            result.push_back(p);
        } else {
            for (const auto& r : p.roles) {
                if (toLowerUtf8(r) == "public" || r == username ||
                    userHasRole(username, r)) {
                    result.push_back(p);
                    break;
                }
            }
        }
    }
    return result;
}

DBStatus StorageEngine::enableRowLevelSecurity(const std::string& dbname, const std::string& tablename,
                                                  bool force) {
    return alterTableRowLevelSecurity(dbname, tablename, true, force);
}

DBStatus StorageEngine::disableRowLevelSecurity(const std::string& dbname, const std::string& tablename) {
    return alterTableRowLevelSecurity(dbname, tablename, false, false);
}

DBStatus StorageEngine::alterTableRowLevelSecurity(
    const std::string& dbname, const std::string& tablename,
    std::optional<bool> enabled, std::optional<bool> forced) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    TableSchema tbl = getTableSchema(dbname, tablename);
    if (enabled) tbl.rowLevelSecurity = *enabled;
    if (forced) tbl.forceRowLevelSecurity = *forced;
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

